const ADMIN_QUESTIONS = [
 {exam:"admin", cat:"deploy", q:"An administrator needs the component that <b>parses, indexes, and writes event data to disk</b> in an index and then searches that data. Which component performs this role?", o:["Heavy forwarder","Indexer","Search head","Universal forwarder"], a:[1], e:"The <b>indexer</b> parses, indexes, stores incoming data to disk, and searches its own indexed data. A <b>heavy forwarder</b> can parse and cook data but typically forwards it rather than storing it in an index; <b>search heads</b> coordinate searches; <b>universal forwarders</b> only collect and forward.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Deploy/Datapipeline"},
 {exam:"admin", cat:"deploy", q:"Which sequence correctly represents the Splunk data pipeline from ingestion to results?", o:["Input &rarr; Indexing &rarr; Parsing &rarr; Search","Input &rarr; Parsing &rarr; Indexing &rarr; Search","Parsing &rarr; Input &rarr; Indexing &rarr; Search","Input &rarr; Parsing &rarr; Search &rarr; Indexing"], a:[1], e:"Data flows <b>Input &rarr; Parsing &rarr; Indexing &rarr; Search</b>. Parsing (event breaking, timestamp extraction, index-time metadata) always happens <b>before</b> the data is written to disk during indexing, and searching occurs only after data is indexed.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Deploy/Datapipeline"},
 {exam:"admin", cat:"license", q:"A Splunk deployment repeatedly records license warnings. Which condition <b>most directly</b> triggers a license violation?", o:["Running more concurrent searches than the license permits","Indexing more data in a single day than the licensed daily volume","Configuring more indexes than the license allows","Adding more authenticated users than the license allows"], a:[1], e:"A <b>license violation</b> is driven by exceeding your <b>licensed daily indexing volume</b>. Splunk measures the raw volume of data indexed per calendar day against the license quota; search concurrency, index count, and user count do not consume license volume.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/HowSplunklicensingworks"},
 {exam:"admin", cat:"confs", q:"The same setting is defined in an app's <code>local</code> and <code>default</code> directories. Which value takes effect?", o:["default always wins","local overrides default","The most recently edited file","They are merged and averaged"], a:[1], e:"In configuration layering, <b>local overrides default</b>. Never edit files in <code>default</code> (upgrades overwrite them); put your changes in <code>local</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Aboutconfigurationfiles"},
 {exam:"admin", cat:"confs", q:"Which command prints Splunk's merged, on-disk configuration and shows which file each setting came from?", o:["splunk show config","splunk btool <conf> list --debug","splunk diag","splunk validate"], a:[1], e:"<b>btool</b> (e.g. <code>splunk btool inputs list --debug</code>) prints the effective merged configuration and the <b>source file</b> of each setting - the go-to tool for troubleshooting precedence.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Troubleshooting/Usebtooltotroubleshootconfigurations"},
 {exam:"admin", cat:"indexes", q:"What is the correct order of the Splunk index bucket lifecycle?", o:["hot &rarr; warm &rarr; cold &rarr; frozen","hot &rarr; warm &rarr; cold &rarr; thawed","warm &rarr; hot &rarr; cold &rarr; frozen","hot &rarr; cold &rarr; warm &rarr; frozen"], a:[0], e:"Buckets age <b>hot &rarr; warm &rarr; cold &rarr; frozen</b>. Hot is writable; warm and cold are searchable but read-only; frozen data leaves the index (deleted or archived). <b>Thawed</b> is not part of the normal aging path - it is data restored from a frozen archive back into a searchable state.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/HowSplunkstoresindexes"},
 {exam:"admin", cat:"indexes", q:"An admin notices that older events vanish entirely from an index once buckets age out, and no archive of them exists. By default, what happens when a bucket rolls to <b>frozen</b>?", o:["It is deleted, unless <code>coldToFrozenDir</code> (or a freezing script) is configured","It is compressed and retained until <code>maxTotalDataSizeMB</code> is reached","It is archived automatically into the <code>colddb</code> directory","It is rolled back to warm and remains searchable"], a:[0], e:"When a bucket reaches <b>frozen</b>, Splunk <b>deletes</b> it by default. To retain the data, set <code>coldToFrozenDir</code> (or a <code>coldToFrozenScript</code>) so the bucket is archived instead. The <code>colddb</code> directory holds cold buckets, not frozen ones, and freezing is triggered by retention limits like <code>frozenTimePeriodInSecs</code> or <code>maxTotalDataSizeMB</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Setaretirementandarchivingpolicy"},
 {exam:"admin", cat:"users", q:"How are Splunk users granted permission to perform actions such as editing knowledge objects or running real-time searches?", o:["Directly, per individual user","Through roles, which are collections of capabilities","Through the index they can see","Through the license"], a:[1], e:"Permissions come from <b>roles</b>, which are built from <b>capabilities</b>. Users are assigned one or more roles; you don't grant capabilities to users directly.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"gdi", q:"You add a new data input without specifying an index. Where does the data go?", o:["It is discarded","Into the default index (main)","Into a new index named after the sourcetype","Into the _internal index"], a:[1], e:"Without an explicit index, events go to the <b>default index</b>, which is <b>main</b> unless changed. Best practice is to route data to purpose-built indexes.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Aboutdefaultfields"},
 {exam:"admin", cat:"forwarders", q:"An admin must choose between a universal forwarder and a heavy forwarder for a data-collection tier. Which statement <b>best</b> describes the primary difference?", o:["The heavy forwarder is a full Splunk Enterprise instance that can parse, filter, and route data, while the universal forwarder is lightweight and forwards mostly unparsed data","The universal forwarder parses and cooks data before sending, while the heavy forwarder forwards only raw, unparsed data","The heavy forwarder cannot send cooked data to indexers and must write to a local index instead","The universal forwarder includes full Splunk Web, while the heavy forwarder runs without any UI"], a:[0], e:"A <b>universal forwarder</b> is a lightweight agent that forwards <b>unparsed</b> data with a small footprint. A <b>heavy forwarder</b> is a full Splunk Enterprise instance that can <b>parse, filter, and route</b> data before forwarding it. The UF has no Splunk Web, and it is the UF (not the HF) that sends largely unparsed data.", d:"https://docs.splunk.com/Documentation/Forwarder/latest/Forwarder/Abouttheuniversalforwarder"},
 {exam:"admin", cat:"forwarders", q:"An admin wants to centrally distribute apps and configuration to several hundred universal forwarders. Which component performs this role?", o:["The deployment server, which pushes deployment apps to deployment clients","The deployer, which pushes apps to search head cluster members","The cluster manager, which distributes the configuration bundle to indexer peer nodes","The license manager, which pushes license pools to license peers"], a:[0], e:"The <b>deployment server</b> centrally manages configuration by pushing <b>deployment apps</b> to <b>deployment clients</b> such as forwarders. The <b>deployer</b> serves search head clusters, and the <b>cluster manager</b> distributes the configuration bundle to indexer peers - different roles for different tiers.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Aboutdeploymentserver"},
 {exam:"admin", cat:"inputs", q:"Which input type continuously watches a file or directory and indexes new data as it is appended, tracking its read position across restarts?", o:["monitor","batch","oneshot","upload"], a:[0], e:"A <b>monitor</b> input continuously watches files/directories and indexes new events as they arrive, remembering how far it has read. <b>batch</b> reads a file once and then <b>deletes</b> it, while <b>oneshot</b> and <b>upload</b> ingest a file a single time without ongoing monitoring.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"What does the HTTP Event Collector (HEC) enable?", o:["Applications to send data to Splunk over HTTP/HTTPS, authenticated with a token","Forwarders to send cooked data to indexers over TCP port 9997","Clients to send events over HTTP without any authentication","Users to run and export search results through the REST API"], a:[0], e:"<b>HEC</b> lets applications send data directly to Splunk over <b>HTTP/HTTPS</b>, authenticated with a <b>token</b> - agentless ingestion with no forwarder required. Token authentication is required, and HEC is an ingestion endpoint, not a search or forwarder-to-indexer channel.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/UsetheHTTPEventCollector"},
 {exam:"admin", cat:"parsing", q:"Which activity occurs during the <b>parsing</b> phase, rather than the input or search phases?", o:["Breaking the stream into events, extracting the timestamp, and setting index-time metadata","Reading raw bytes from the source and assigning the initial source and sourcetype","Applying search-time field extractions and calculated fields","Writing the rawdata and tsidx files to disk"], a:[0], e:"The <b>parsing</b> phase breaks the incoming stream into <b>events</b>, identifies <b>timestamps</b>, and applies index-time fields/metadata. Reading raw bytes and initial metadata assignment happen at the <b>input</b> phase, writing files to disk happens at <b>indexing</b>, and field extraction like calculated fields happens at <b>search</b> time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Deploy/Datapipeline"},
 {exam:"admin", cat:"parsing", q:"Which props.conf setting masks or replaces raw event text at index time using sed-style syntax?", o:["EXTRACT","SEDCMD","REPORT","FIELDALIAS"], a:[1], e:"<b>SEDCMD</b> applies sed-style substitution to <b>raw data at index time</b>, commonly used to anonymize or mask sensitive strings before the event is indexed.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Anonymizedata"},
 {exam:"admin", cat:"dsearch", q:"In a distributed search environment, what is the primary role of the search head?", o:["It dispatches the search to indexers (search peers) and merges the results they return","It stores a local replicated copy of indexed data to speed up searches","It forwards raw incoming data to the indexers for storage","It permanently stores the merged results back onto the indexers"], a:[0], e:"A <b>search head</b> coordinates searches: it dispatches the search to <b>indexers (search peers)</b>, which run it against their local data, then <b>merges</b> the returned results. It does not store indexed data itself; multiple search heads can form a <b>search head cluster</b> for scale.", d:"https://docs.splunk.com/Documentation/Splunk/latest/DistSearch/Whatisdistributedsearch"},
 {exam:"admin", cat:"deploy", q:"In an indexer cluster, which node coordinates bucket replication, tracks peer state, and tells the peer nodes how to behave?", o:["The manager node (cluster manager)","The deployer","A designated primary peer node","The license manager"], a:[0], e:"The <b>manager node</b> (cluster manager, formerly called the master node) coordinates the indexer cluster - it manages replication, tracks peer state, and directs the <b>peer nodes</b>, without indexing data itself. The <b>deployer</b> serves search head clusters, not indexer clusters.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"deploy", q:"Which tier collects data at the edge and forwards it, typically <b>without</b> indexing it locally?", o:["The forwarding (data-collection) tier","The indexing tier","The search-management tier","The license-management tier"], a:[0], e:"The <b>forwarding / data-collection tier</b> (usually universal forwarders) gathers data at the source and ships it onward, generally without indexing it. The <b>indexing tier</b> parses and stores data, and the <b>search tier</b> searches it.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Deploy/Datapipeline"},
 {exam:"admin", cat:"license", q:"Under an Enterprise Trial (or Dev/Test) license, how many warnings within a rolling 30-day window create a license violation?", o:["3","5","10","1"], a:[1], e:"For an <b>Enterprise Trial</b> / Dev/Test license, <b>5 or more</b> license warnings in a rolling <b>30-day</b> period create a <b>violation</b> - the 5th warning is the tipping point. Note the production Enterprise license differs: stacks under 100 GB/day allow <b>45 warnings in 60 days</b>, and stacks at 100 GB/day or more issue warnings but no longer block search. (Free = 3 or more in 30 days.)", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/HowSplunklicensingworks"},
 {exam:"admin", cat:"license", q:"In a distributed deployment, which role centrally tracks daily indexing volume for all indexers against the license?", o:["License peer","The license manager (license master)","Deployment server","Cluster manager"], a:[1], e:"The <b>license manager</b> (formerly license master) holds the license and meters usage. Indexers are configured as <b>license peers</b> that report their daily volume to it.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/HowSplunklicensingworks"},
 {exam:"admin", cat:"license", q:"What is the maximum daily indexing volume permitted by the <b>Free</b> Splunk Enterprise license?", o:["500 MB/day","1 GB/day","5 GB/day","10 GB/day"], a:[0], e:"The <b>Free</b> license caps indexing at <b>500 MB/day</b> and disables features such as authentication, alerting, and distributed search. When the 60-day Enterprise trial expires, it reverts to the Free license.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/HowSplunklicensingworks"},
 {exam:"admin", cat:"confs", q:"In the <b>global</b> configuration context, which directory has the <b>highest</b> precedence when the same setting appears in more than one place?", o:["$SPLUNK_HOME/etc/system/local","$SPLUNK_HOME/etc/apps/&lt;app&gt;/local","$SPLUNK_HOME/etc/apps/&lt;app&gt;/default","$SPLUNK_HOME/etc/system/default"], a:[0], e:"For the <b>global</b> context the precedence (highest to lowest) is <b>system/local</b> &gt; app local &gt; app default &gt; <b>system/default</b>. So <code>$SPLUNK_HOME/etc/system/local</code> wins. (In the app or user context, app-level local can outrank system/local - but this question asks about the global context.)", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Configurationfiledirectories"},
 {exam:"admin", cat:"confs", q:"You manually edited a .conf file on an indexer. What is generally required for the change to take effect?", o:["Nothing - changes apply instantly","A Splunk restart (some settings can be reloaded without one)","A full server reboot","Reinstalling Splunk"], a:[1], e:"Most manual <code>.conf</code> edits require a <b>Splunk restart</b> to take effect. Some settings can be reloaded via the CLI or REST endpoints, but restart is the safe default.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Aboutconfigurationfiles"},
 {exam:"admin", cat:"confs", q:"While editing <code>inputs.conf</code>, an admin wants to disable a stanza temporarily by commenting it out. Which character must begin the line for Splunk to treat it as a comment and ignore it?", o:["<code>;</code> (semicolon, as in some INI dialects)","<code>#</code> at the start of its own line","<code>//</code> at the start of the line","<code>#</code> appended to the end of the existing setting line"], a:[1], e:"Splunk <code>.conf</code> files use <b>#</b> to begin a comment, and it must be at the start of its own line - Splunk does not honor trailing inline comments appended to a setting.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Aboutconfigurationfiles"},
 {exam:"admin", cat:"confs", q:"A universal forwarder is not collecting a new log file even though the file exists. To define the monitor stanza, network ports, scripted inputs, and HEC endpoints that tell Splunk WHAT data to collect, which configuration file should the admin edit?", o:["<b>props.conf</b>","<b>outputs.conf</b>","<b>inputs.conf</b>","<b>indexes.conf</b>"], a:[2], e:"<b>inputs.conf</b> defines what data Splunk collects - monitor stanzas, network ports, scripted inputs, and HEC. <b>outputs.conf</b> defines where a forwarder sends data; <b>props.conf</b> controls parsing.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"indexes", q:"An admin needs to create a new index and set its <code>homePath</code>, <code>maxTotalDataSizeMB</code>, and <code>frozenTimePeriodInSecs</code>. In which configuration file are these index definitions placed?", o:["<b>server.conf</b>","<b>indexes.conf</b>","<b>inputs.conf</b>","<b>props.conf</b>"], a:[1], e:"<b>indexes.conf</b> defines indexes and their paths, sizes, and retention settings (e.g. <code>homePath</code>, <code>maxTotalDataSizeMB</code>, <code>frozenTimePeriodInSecs</code>).", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/HowSplunkstoresindexes"},
 {exam:"admin", cat:"indexes", q:"A retention policy requires that events older than 90 days be frozen regardless of how much disk they consume. Which index setting MOST directly enforces this age-based freezing?", o:["<b>maxTotalDataSizeMB</b>","<b>maxHotSpanSecs</b>","<b>frozenTimePeriodInSecs</b>","<b>maxWarmDBCount</b>"], a:[2], e:"<b>frozenTimePeriodInSecs</b> rolls data to frozen once it reaches a maximum <b>age</b>, independent of size. Use it for time-based retention policies.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Setaretirementandarchivingpolicy"},
 {exam:"admin", cat:"indexes", q:"An index keeps growing and the admin wants Splunk to roll the OLDEST data to frozen once the index reaches a fixed disk-size limit. Which setting caps the index by size?", o:["<b>frozenTimePeriodInSecs</b>","<b>coldToFrozenDir</b>","<b>maxTotalDataSizeMB</b>","<b>maxDataSize</b>"], a:[2], e:"<b>maxTotalDataSizeMB</b> sets the maximum index size; when exceeded, the <b>oldest</b> bucket rolls to frozen. (<code>maxDataSize</code> caps a single bucket, not the whole index.) Whichever limit - size or age - is hit first triggers freezing.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Setaretirementandarchivingpolicy"},
 {exam:"admin", cat:"indexes", q:"During indexing, which bucket state is the ONLY one that Splunk is actively writing NEW events into?", o:["<b>warm</b> (recently rolled, still searchable)","<b>cold</b> (aged out to a separate path)","<b>hot</b>","<b>frozen</b> (rolled out of the index)"], a:[2], e:"Only <b>hot</b> buckets are writable. When a hot bucket rolls to <b>warm</b> it becomes read-only (still searchable); <b>cold</b> is also searchable read-only; <b>frozen</b> leaves the index.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/HowSplunkstoresindexes"},
 {exam:"admin", cat:"users", q:"When building custom roles, which three built-in roles are the standard <b>base</b> roles you typically inherit from?", o:["<b>admin</b>, <b>power</b>, <b>user</b>","<b>admin</b>, <b>superuser</b>, <b>guest</b>","<b>super</b>, <b>power</b>, <b>standard</b>","<b>root</b>, <b>admin</b>, <b>user</b>"], a:[0], e:"The standard base roles are <b>admin</b>, <b>power</b>, and <b>user</b> — you build custom roles by inheriting (<code>importRoles</code>) from these. Splunk ships other default roles too (e.g. <code>can_delete</code>), but admin/power/user are the core trio; <code>superuser</code>, <code>root</code>, and <code>guest</code> are not Splunk roles.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"users", q:"A role can run searches but keeps returning no results from a restricted index. Which role setting MOST directly determines which indexes members of that role are permitted to search?", o:["<b>srchIndexesDefault</b>","<b>srchIndexesAllowed</b>","<b>srchJobsQuota</b>","<b>srchFilter</b>"], a:[1], e:"<b>srchIndexesAllowed</b> lists the indexes a role may search. <b>srchIndexesDefault</b> only sets which of those are searched when no index is specified; <b>srchFilter</b> restricts events, not index access.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"users", q:"An admin wants a new role to automatically gain all the capabilities and index access already granted to an existing role, without re-listing them. What is the BEST way to achieve this?", o:["Roles cannot share capabilities; each must be defined independently","Have the new role inherit (import) the existing role in its definition","Copy the existing role's password to the new role","Assign both roles the <code>admin_all_objects</code> capability"], a:[1], e:"A role can <b>inherit</b> other roles, gaining all of their capabilities and index access. This lets you layer roles instead of redefining capabilities each time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"users", q:"Which external authentication methods can Splunk integrate with for user login? (Choose all that apply.)", o:["LDAP","SAML (SSO)","Multifactor authentication (MFA)","A spreadsheet upload"], a:[0,1,2], e:"Splunk supports <b>LDAP</b>, <b>SAML</b> for SSO, and <b>MFA</b> (e.g. Duo/RSA) on top of native authentication. Users are not authenticated by uploading a spreadsheet.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"gdi", q:"An admin lists fields to explain which are default (indexed) fields versus knowledge objects. Which of the following is NOT one of Splunk's default fields?", o:["<b>source</b>","<b>sourcetype</b>","<b>eventtype</b>","<b>host</b>"], a:[2], e:"<b>host</b>, <b>source</b>, and <b>sourcetype</b> (plus <code>index</code>, <code>_time</code>, <code>linecount</code>) are default fields added at index time. <b>eventtype</b> is a <b>knowledge object</b> (a saved search-time classification), not a default field.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Aboutdefaultfields"},
 {exam:"admin", cat:"gdi", q:"Two identical log files are parsed differently - one breaks events correctly and one does not. Which property, assigned to each event, MOST directly tells Splunk the data's format and drives its line breaking, timestamping, and field extraction?", o:["the <b>source</b>","the <b>sourcetype</b>","the <b>host</b>","the <b>index</b>"], a:[1], e:"The <b>sourcetype</b> identifies the data's <b>format</b> (e.g. <code>access_combined</code>, <code>linux_secure</code>) and drives parsing rules - line breaking, timestamps, and field extractions. Two files with the same source can still get different sourcetypes.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Aboutdefaultfields"},
 {exam:"admin", cat:"gdi", q:"To keep indexing lean and storage costs low while still allowing extractions to be changed later without re-indexing, where should MOST field extractions occur by default?", o:["At <b>index time</b>, via <code>transforms.conf</code>","At <b>search time</b>","On the <b>universal forwarder</b> before sending","At <b>parse time</b> on the heavy forwarder"], a:[1], e:"Best practice is <b>search-time</b> extraction: it keeps indexing lean and lets you adjust extractions without re-indexing. Reserve index-time fields for cases that truly need them.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Aboutdefaultfields"},
 {exam:"admin", cat:"forwarders", q:"A newly configured forwarder is collecting data but nothing arrives at the indexers. Which configuration file on the forwarder specifies the receiving indexer(s) it should send data to?", o:["<b>deploymentclient.conf</b>","<b>outputs.conf</b>","<b>inputs.conf</b>","<b>props.conf</b>"], a:[1], e:"<b>outputs.conf</b> defines the receiving indexers (the <code>tcpout</code> targets) a forwarder sends to. <b>inputs.conf</b> defines what data it collects; <b>deploymentclient.conf</b> points it at a deployment server.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Enableareceiver"},
 {exam:"admin", cat:"forwarders", q:"An admin is configuring an indexer to receive data from forwarders. By convention, which TCP port is used for this Splunk-to-Splunk data receiving (not management or Splunk Web)?", o:["<b>8089</b>","<b>8000</b>","<b>9997</b>","<b>8088</b>"], a:[2], e:"<b>9997</b> is the conventional Splunk-to-Splunk receiving port. (8000 = Splunk Web, 8089 = management/REST, 8088 = HEC.)", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Enableareceiver"},
 {exam:"admin", cat:"forwarders", q:"A forwarder should automatically download apps from a central deployment server. Which configuration file on the forwarder tells it which deployment server to poll?", o:["<b>serverclass.conf</b>","<b>deploymentclient.conf</b>","<b>outputs.conf</b>","<b>server.conf</b>"], a:[1], e:"<b>deploymentclient.conf</b> points a client (forwarder) at its <b>deployment server</b>. <b>serverclass.conf</b> lives on the deployment server and maps clients to apps.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Aboutdeploymentserver"},
 {exam:"admin", cat:"forwarders", q:"On a deployment server, what groups deployment clients and maps them to the apps they should receive?", o:["A server class","An index","A search head cluster","A license pool"], a:[0], e:"A <b>server class</b> defines a group of deployment clients (by filters like hostname or machine type) and the set of <b>deployment apps</b> they should get.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Aboutdeploymentserver"},
 {exam:"admin", cat:"forwarders", q:"A universal forwarder is configured with three receiving indexers in its <code>outputs.conf</code> target group. By default, how does it MOST directly spread data across those indexers to balance the load?", o:["It performs automatic time-based load balancing, switching among the configured indexers on a timed interval","It routes each event to the indexer with the lowest reported CPU using indexer acknowledgment metrics","It relies on DNS round-robin resolution of the target hostname to pick an indexer per connection","It requires an external hardware or software load balancer placed in front of the indexers"], a:[0], e:"A UF performs <b>automatic load balancing</b>, switching among its list of receiving indexers on a time interval so data is spread evenly - no external load balancer needed. Selection is time-based by default, not driven by indexer CPU or DNS.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Enableareceiver"},
 {exam:"admin", cat:"inputs", q:"A team wants Splunk to listen directly on a <b>UDP</b> port to receive syslog traffic. Which input type MOST directly provides this capability?", o:["Monitor input","Network input","Scripted input","HTTP Event Collector"], a:[1], e:"A <b>network input</b> listens on a <b>TCP</b> or <b>UDP</b> port. UDP is common for syslog, though sending syslog to a forwarder or a dedicated syslog server and then monitoring files is often preferred for reliability. A monitor input watches files/directories, not ports; HEC uses HTTP/HTTPS.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitornetworkports"},
 {exam:"admin", cat:"inputs", q:"You need Splunk to periodically call an external API and index whatever the program returns. Which input type is designed for this?", o:["A monitor input that continuously watches a directory","A scripted input that runs a script or program on an interval and indexes its stdout","A network input that opens a raw TCP or UDP port","A one-shot upload of a single file through Splunk Web"], a:[1], e:"A <b>scripted input</b> executes a script/command on a schedule and indexes whatever it writes to <b>stdout</b> - handy for APIs, custom metrics, or command output. Monitor watches files, network inputs open ports, and one-shot handles a single file once.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"You need to index one existing log file a single time for testing, with no ongoing monitoring afterward. Which CLI command MOST directly accomplishes this?", o:["splunk add monitor","splunk add oneshot","splunk add forward-server","splunk add tcp"], a:[1], e:"<b>splunk add oneshot &lt;file&gt;</b> indexes a file <b>once</b> with no continuous monitoring. <code>add monitor</code> sets up ongoing monitoring; <code>add tcp</code> creates a network input; <code>add forward-server</code> configures forwarding to an indexer.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"In <code>inputs.conf</code>, how is the file monitor stanza header written to monitor the absolute path <code>/var/log</code>?", o:["[monitor:///var/log]","[monitor://var/log]","[monitor:/var/log]","[monitor://./var/log]"], a:[0], e:"Monitor stanzas use <code>[monitor://&lt;path&gt;]</code>. For an absolute path like <code>/var/log</code> that becomes <code>[monitor:///var/log]</code> - two slashes from the scheme separator plus the leading slash of the absolute path, giving three total.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"An application is sending events to the HTTP Event Collector. How does HEC authenticate each incoming request by default?", o:["A username and password supplied via HTTP basic auth","A token included in the request","A mutual TLS client certificate","The forwarder's outputs.conf credentials"], a:[1], e:"The <b>HTTP Event Collector</b> authenticates each request with a <b>token</b>. You enable HEC, create tokens, and applications include the token in the <code>Authorization</code> header. HEC does not use username/password or the forwarder's outputs.conf.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/UsetheHTTPEventCollector"},
 {exam:"admin", cat:"parsing", q:"Which feature lets admins filter, mask, and route incoming data through a Splunk Web UI using rulesets - without hand-editing props.conf and transforms.conf?", o:["SEDCMD","Ingest Actions","Data models","Field aliases"], a:[1], e:"<b>Ingest Actions</b> provides a UI to build <b>rulesets</b> that filter, mask, and route data at ingest (including to remote storage like S3). It generates the underlying props/transforms for you.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/DataIngest"},
 {exam:"admin", cat:"parsing", q:"How do you drop (filter out) unwanted events at index time using props.conf and transforms.conf?", o:["Route the events to the nullQueue","Delete them later with | delete","Lower the license quota","Set SHOULD_LINEMERGE=true"], a:[0], e:"Filtering at index time routes matching events to the <b>nullQueue</b> (a transform with <code>DEST_KEY=queue</code> and <code>FORMAT=nullQueue</code>, referenced from props.conf). The <code>| delete</code> command only hides events from search, it doesn't reclaim storage.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Routeandfilterdatad"},
 {exam:"admin", cat:"parsing", q:"A multi-line source is being indexed as one giant event. Which <code>props.conf</code> setting MOST directly defines where Splunk breaks the incoming stream into separate events?", o:["TIME_FORMAT","LINE_BREAKER","BREAK_ONLY_BEFORE","MUST_BREAK_AFTER"], a:[1], e:"<b>LINE_BREAKER</b> (typically with <code>SHOULD_LINEMERGE=false</code>) defines the regex boundary Splunk uses to split raw data into individual events during parsing. <code>BREAK_ONLY_BEFORE</code> and <code>MUST_BREAK_AFTER</code> only apply during line merging (<code>SHOULD_LINEMERGE=true</code>); <code>TIME_FORMAT</code> governs timestamps.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Deploy/Datapipeline"},
 {exam:"admin", cat:"parsing", q:"On which components does the parsing phase occur? (Choose all that apply.)", o:["Universal forwarder","Heavy forwarder","Indexer","License manager"], a:[1,2], e:"Parsing happens on the <b>heavy forwarder</b> and the <b>indexer</b>. A <b>universal forwarder</b> forwards mostly unparsed data (parsing is offloaded downstream); the license manager plays no part in parsing.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Deploy/Datapipeline"},
 {exam:"admin", cat:"dsearch", q:"In a search head cluster, which member coordinates the cluster - scheduling jobs and replicating knowledge objects?", o:["The captain","The manager node (master)","The deployer","The deployment server"], a:[0], e:"A search head cluster elects a <b>captain</b> that coordinates the members - scheduling searches, replicating knowledge objects, and pushing the configuration bundle. The <b>deployer</b> distributes apps to SHC members but does not coordinate the cluster; the <b>manager node</b> coordinates an indexer cluster.", d:"https://docs.splunk.com/Documentation/Splunk/latest/DistSearch/AboutSHC"},
 {exam:"admin", cat:"dsearch", q:"In an indexer cluster, what does the <b>replication factor</b> MOST directly determine?", o:["How many searchable copies of each bucket exist","How many total copies of each bucket are maintained across peers","How many peer nodes are allowed to join the cluster","How many days of data are retained before freezing"], a:[1], e:"The <b>replication factor</b> is the number of <b>total copies</b> of each bucket the cluster keeps across peer nodes - it governs failure tolerance (how many peers can go down without data loss). The number of <b>searchable</b> copies is the separate <b>search factor</b>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"dsearch", q:"In an indexer cluster, what does the <b>search factor</b> determine, and how does it relate to the replication factor?", o:["The number of SEARCHABLE copies of each bucket; it must be less than or equal to the replication factor","The total number of copies of each bucket; it must be greater than the replication factor","The number of concurrent searches allowed per peer; it is independent of the replication factor","The number of forwarders that can send to the cluster; it equals the replication factor"], a:[0], e:"The <b>search factor</b> is the number of <b>searchable</b> copies of each bucket (copies that include the index/tsidx files, not just raw data). It must be <b>less than or equal to</b> the replication factor; the default is 2.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"deploy", q:"A new admin sets up a deployment server and assumes it will receive, index, and store the data that forwarders send. Why is that assumption wrong?", o:["It is correct - the deployment server indexes forwarder data","The deployment server only distributes configuration (apps) to clients; the indexer is what receives, parses, indexes, and stores the data","Forwarders index their own data, so no indexer is involved","The search head receives and stores the forwarded data"], a:[1], e:"The <b>deployment server</b> only pushes <b>apps/configuration</b> to deployment clients. Receiving, parsing, indexing, and storing forwarded data is the <b>indexer's</b> job. Mixing these roles up is a classic exam trap.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Aboutdeploymentserver"},
 {exam:"admin", cat:"license", q:"A 60-day Enterprise trial expires and the instance reverts to the Free license. Which symptoms should you expect? (Choose all that apply.)", o:["Scheduled alerts stop firing","Login authentication (users/roles, LDAP) is disabled","Daily indexing is capped at 500 MB","All previously indexed data is deleted"], a:[0,1,2], e:"The <b>Free</b> license disables <b>alerting</b>, <b>authentication</b> (no logins/roles), distributed search, clustering, and summarization, and caps indexing at <b>500 MB/day</b>. It does <b>not</b> delete already-indexed data.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/HowSplunklicensingworks"},
 {exam:"admin", cat:"inputs", q:"When configuring a TCP or UDP network input, which options are valid for setting the value of the <code>host</code> field? (Choose all that apply.)", o:["The IP address of the sender","A reverse DNS lookup of the sender","A custom (explicit) value you specify","The contents of a binary file"], a:[0,1,2], e:"For a network input, <b>host</b> can be derived from the sender's <b>IP</b>, a <b>DNS</b> (reverse) lookup, or set to a <b>custom</b> explicit value. A binary file is not a valid host option.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitornetworkports"},
 {exam:"admin", cat:"confs", q:"In which directory does Splunk install apps and add-ons, each in its own subfolder containing default/ and local/ configuration directories?", o:["$SPLUNK_HOME/etc/apps","$SPLUNK_HOME/etc/system/default","$SPLUNK_HOME/var/lib/splunk","$SPLUNK_HOME/bin"], a:[0], e:"Apps live under <code>$SPLUNK_HOME/etc/apps/&lt;app&gt;</code>, each with its own <b>default</b> (shipped) and <b>local</b> (your edits) directories. <code>var/lib/splunk</code> holds indexed data, not apps.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Configurationfiledirectories"},
 {exam:"admin", cat:"deploy", q:"Which built-in feature gives an administrator a centralized, pre-built view of the deployment's health and performance (indexing rate, search load, resource usage)?", o:["The Monitoring Console","The Job Inspector","btool","The deployment server"], a:[0], e:"The <b>Monitoring Console</b> (formerly the DMC) provides ready-made dashboards for overall deployment health and performance. The Job Inspector examines a single search, <b>btool</b> checks configuration, and the deployment server distributes apps.", d:"https://docs.splunk.com/Documentation/Splunk/latest/DMC/DMCoverview"},
 {exam:"admin", cat:"inputs", q:"After restarting Splunk on a forwarder, a monitored file is NOT re-indexed from the top. Which component MOST directly makes this behavior possible?", o:["The fishbucket, which tracks read position (seek pointers and CRCs) per monitored file","The frozen bucket path, which archives data before deletion","The license usage database, which records ingested volume","The dispatch directory, which caches search results for reuse"], a:[0], e:"The <b>fishbucket</b> stores read <b>seek pointers and CRCs</b> for monitored files, so when a file grows or Splunk restarts it resumes where it left off rather than <b>re-indexing</b> from the top. It is unrelated to freezing, licensing, or the dispatch directory.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"parsing", q:"What best describes a <b>pretrained</b> sourcetype in Splunk?", o:["A sourcetype Splunk ships with built-in parsing rules for common formats (for example, access_combined, linux_secure)","A sourcetype whose field extractions are generated automatically by machine learning during indexing","Any sourcetype a user manually defines in Splunk Web","A sourcetype that only works after training a model in the Machine Learning Toolkit"], a:[0], e:"<b>Pretrained sourcetypes</b> come with Splunk and already have correct line breaking, timestamp, and field settings for well-known data. Assigning one means you don't have to configure parsing yourself. Despite the name, no ML training is involved.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Listofpretrainedsourcetypes"},
 {exam:"admin", cat:"forwarders", q:"In Splunk Web, what is <b>Forwarder Management</b> MOST directly used for?", o:["A graphical interface to the deployment server for creating server classes and mapping deployment apps to forwarders","Remotely installing the universal forwarder software package onto new hosts","Hand-editing each forwarder's outputs.conf from a central console","Monitoring per-forwarder daily license usage and violations"], a:[0], e:"<b>Forwarder Management</b> is the deployment server's UI: you define <b>server classes</b> (groups of clients) and assign <b>deployment apps</b>, then the server pushes those apps to the forwarders (deployment clients) automatically. It does not install UF software or track license usage.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Forwardermanagementoverview"},
 {exam:"admin", cat:"parsing", q:"Which pair of configuration files most commonly work together to customize the input parsing process (for example, custom line breaking that then masks or routes events)?", o:["props.conf and transforms.conf","inputs.conf and outputs.conf","indexes.conf and server.conf","authentication.conf and authorize.conf"], a:[0], e:"<b>props.conf</b> applies parsing settings by source/sourcetype/host (line breaking, timestamps, and <code>TRANSFORMS</code> references) and points to <b>transforms.conf</b>, which defines the regex-based transforms (routing to nullQueue, index/host overrides, masking).", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Routeandfilterdatad"},
 {exam:"admin", cat:"inputs", q:"You must collect Windows Event Logs (Application, System, Security) from several Windows servers <b>without</b> installing an agent on each server. Which collection method is designed for this agentless scenario?", o:["A WMI (Windows Management Instrumentation) input configured on a Splunk instance running on Windows","A universal forwarder installed on every server","An HTTP Event Collector token","A syslog UDP input"], a:[0], e:"<b>WMI</b> inputs let a Windows-based Splunk instance pull event logs and performance data <b>remotely</b> (agentless). Installing a universal forwarder is the more scalable/reliable option, but it is <b>not</b> agentless. HEC and syslog are not used for native Windows Event Log collection.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/MonitorWMIdata"},
 {exam:"admin", cat:"inputs", q:"On a Windows host, which <code>inputs.conf</code> stanza collects the local <b>Security</b> event log channel?", o:["[WinEventLog://Security]","[monitor://Security]","[WinEventLog:Security]","[perfmon://Security]"], a:[0], e:"The Windows Event Log input uses the <code>[WinEventLog://&lt;channel&gt;]</code> stanza, so the Security channel is <code>[WinEventLog://Security]</code>. Note the two slashes after the scheme. <code>perfmon</code> collects performance counters, and <code>monitor</code> watches files - neither reads event log channels.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/MonitorWindowseventlogdata"},
 {exam:"admin", cat:"parsing", q:"Events for sourcetype <code>apache_access_logs</code> show a <code>_time</code> that is several hours off, even though the raw event contains a full timestamp with a zone offset (e.g. <code>[25/May/2027:10:30:00 -0700]</code>). Which props.conf settings/checks are most likely to fix the timestamping? (Choose all that apply.)", o:["Set <code>TZ</code> for the sourcetype so Splunk interprets the zone correctly","Set a correct <code>TIME_FORMAT</code> (and <code>TIME_PREFIX</code>) so the right timestamp is parsed","Verify the timezone/clock of the indexer/forwarder doing the parsing","Increase the index's <code>maxTotalDataSizeMB</code>"], a:[0,1,2], e:"Timestamp/zone problems are solved in <b>props.conf</b>: <code>TZ</code> sets the timezone, <code>TIME_FORMAT</code>/<code>TIME_PREFIX</code> ensure the correct timestamp is extracted, and the <b>parsing host's own clock/zone</b> matters. Index size settings have nothing to do with timestamps.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Applytimezoneoffsetstotimestamps"},
 {exam:"admin", cat:"parsing", q:"Which props.conf attribute explicitly sets the timezone Splunk uses to interpret a sourcetype's timestamps?", o:["TZ","TIME_FORMAT","DATETIME_CONFIG","LINE_BREAKER"], a:[0], e:"<b>TZ</b> tells Splunk which timezone the events are in (e.g. <code>TZ = US/Pacific</code>), which is critical when the data has no offset or the parsing host is in a different zone.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Applytimezoneoffsetstotimestamps"},
 {exam:"admin", cat:"parsing", q:"Which props.conf setting tells Splunk the text pattern that immediately <b>precedes</b> the timestamp in an event?", o:["TIME_PREFIX","TIME_FORMAT","MAX_TIMESTAMP_LOOKAHEAD","SHOULD_LINEMERGE"], a:[0], e:"<b>TIME_PREFIX</b> is a regex that matches the text right before the timestamp; Splunk starts looking for the timestamp after that match. Pair it with <code>TIME_FORMAT</code> (strptime) for reliable extraction.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Configuretimestamprecognition"},
 {exam:"admin", cat:"parsing", q:"Timestamps are being pulled from the wrong part of long events. Which <code>props.conf</code> setting MOST directly controls how far into the raw event Splunk scans looking for the timestamp?", o:["MAX_TIMESTAMP_LOOKAHEAD","MAX_EVENTS","TIME_PREFIX","MAX_DAYS_AGO"], a:[0], e:"<b>MAX_TIMESTAMP_LOOKAHEAD</b> limits how far (in characters) into the raw event Splunk looks for a timestamp. <code>TIME_PREFIX</code> tells Splunk where to start looking but not how far to scan; <code>MAX_DAYS_AGO</code> bounds acceptable timestamp age; <code>MAX_EVENTS</code> caps lines per event.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Configuretimestamprecognition"},
 {exam:"admin", cat:"confs", q:"Which CLI command reports whether splunkd and its helper processes are currently running on a Linux host?", o:["splunk status","splunk health","splunk ps","splunk running"], a:[0], e:"<code>$SPLUNK_HOME/bin/splunk status</code> reports whether <b>splunkd</b> (and web) are running. If Splunk is configured with boot-start via systemd, <code>systemctl status</code> on the unit also works.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/CLIadmincommands"},
 {exam:"admin", cat:"confs", q:"Which CLI command checks configuration files for problems (typos, invalid stanzas) without restarting Splunk?", o:["splunk btool check","splunk config test","splunk lint","splunk verify"], a:[0], e:"<code>splunk btool check</code> validates the merged configuration for errors. <code>btool ... list --debug</code> additionally shows the effective settings and the file each came from.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/CLIadmincommands"},
 {exam:"admin", cat:"forwarders", q:"You updated an app on the deployment server and need the change pushed to clients. Which command makes the deployment server re-read its apps and serverclass config so clients pick up the update on next phone-home?", o:["splunk reload deploy-server","splunk push apps","splunk deploy now","splunk sync clients"], a:[0], e:"<code>splunk reload deploy-server</code> makes the deployment server re-read <code>$SPLUNK_HOME/etc/deployment-apps</code> and <code>serverclass.conf</code>. Clients then receive the updated app on their next <b>phone-home</b> interval.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Updateconfigurations"},
 {exam:"admin", cat:"forwarders", q:"To distribute an updated app to universal forwarders via the deployment server, which two steps are required? (Choose all that apply.)", o:["Place the updated app under <code>$SPLUNK_HOME/etc/deployment-apps</code> on the deployment server","Run <code>splunk reload deploy-server</code> (or restart) so the change is picked up","Manually copy the app to each forwarder with scp","Re-license every forwarder"], a:[0,1], e:"Deployment apps live in <code>etc/deployment-apps</code> on the server; after updating one you <b>reload the deploy-server</b> so it re-reads apps and server classes. Clients then pull the app automatically - no manual copying or re-licensing.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Deploymentserverarchitecture"},
 {exam:"admin", cat:"indexes", q:"Which internal index stores Splunk's own operational logs and performance metrics (e.g. <code>splunkd.log</code>, <code>metrics.log</code>) - ideal for monitoring indexing rate, search concurrency, and resource use?", o:["_internal","_audit","main","summary"], a:[0], e:"<b>_internal</b> holds Splunk's own logs and <code>metrics.log</code> data - the go-to index for diagnosing the platform itself (often via the Monitoring Console). <b>_audit</b> records audit trail events, not performance.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutmanagingindexes"},
 {exam:"admin", cat:"indexes", q:"Which internal index records audit-trail events such as searches run, configuration changes, and logins?", o:["_audit","_internal","_introspection","history"], a:[0], e:"The <b>_audit</b> index stores audit events - who ran what search, config changes, and authentication activity. <b>_introspection</b> holds resource-usage data; <b>_internal</b> holds Splunk's logs/metrics.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutmanagingindexes"},
 {exam:"admin", cat:"indexes", q:"An admin is planning new indexes and must set the correct <code>datatype</code> in <code>indexes.conf</code>. Which of the following does NOT correspond to a real index in Splunk Enterprise?", o:["An <b>events</b> index (the default datatype for raw event data)","A <b>metrics</b> index (datatype optimized for numeric time-series)","A <b>summary</b> index (a normal events index used to store summary-indexing results)","A <b>relational</b> index"], a:[3], e:"An index's <code>datatype</code> is either <b>event</b> (default) or <b>metric</b>. A <b>summary</b> index is not a separate datatype - it is an ordinary <b>events</b> index that happens to store the output of summary-indexing searches, so it is still a real, valid index. A <b>relational</b> index does not exist; Splunk is not a relational database.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutmanagingindexes"},
 {exam:"admin", cat:"indexes", q:"Which index type is purpose-built to store high-volume numeric time-series measurements at low cost?", o:["A metrics index","An events index","A summary index","A frozen index"], a:[0], e:"A <b>metrics index</b> uses a compact format for <b>metric</b> data points (metric_name, value, dimensions), giving far better performance and storage efficiency than putting the same numbers in an events index.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Metrics/Overview"},
 {exam:"admin", cat:"deploy", q:"Which statements about Splunk's default ports are correct? (Choose all that apply.)", o:["8000 is the default Splunk Web (UI) port","8089 is the default management/REST port","9997 is the conventional forwarder-to-indexer receiving port","443 is splunkd's default inter-process bus"], a:[0,1,2], e:"Defaults: <b>8000</b> Splunk Web, <b>8089</b> management/REST, <b>9997</b> the conventional S2S receiving port (also 8191 KV store, 8065 app server). 443 is standard HTTPS, not a Splunk default.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/CLIadmincommands"},
 {exam:"admin", cat:"license", q:"Your deployment is consistently exceeding its daily license quota. Which strategies effectively reduce license consumption or mitigate violations? (Choose all that apply.)", o:["Filter out unnecessary events at ingest (e.g. route noise to the nullQueue or use Ingest Actions)","Add license capacity (a larger license or additional stack/pool)","Reduce or tune noisy data sources so less volume is indexed","Delete already-indexed data to lower today's indexed volume"], a:[0,1,2], e:"License is measured on <b>data indexed per day</b>. You lower it by <b>filtering at ingest</b>, <b>tuning noisy sources</b>, or <b>adding license capacity</b>. Deleting already-indexed data does <b>not</b> reduce the volume you already counted today.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/HowSplunklicensingworks"},
 {exam:"admin", cat:"inputs", q:"Forwarders are actively sending data, but recent events are not appearing in searches. Which are the most likely indexer-side causes? (Choose all that apply.)", o:["The indexer's receiving port is not enabled or is blocked by a firewall","Event timestamps are being parsed wrong, placing events outside the searched time range","The target index is disabled, full, or the user lacks access to it","The universal forwarder is missing a Splunk Web UI"], a:[0,1,2], e:"Common causes: <b>receiving not enabled</b>/firewalled on the indexer, <b>timestamp parsing</b> putting events in the future/past (so they fall outside 'Last 15 minutes'), or the <b>index being disabled/full or not searchable</b> by that role. A UF never has a web UI - that is normal, not a fault.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Enableareceiver"},
 {exam:"admin", cat:"dsearch", q:"The Cluster Manager UI shows 'replication factor not met' with <code>idx-peer-02</code> repeatedly failing to replicate buckets. Which are appropriate diagnostic/remedial steps? (Choose all that apply.)", o:["Check idx-peer-02's health - disk space, splunkd status, and CPU/memory","Review <code>_internal</code> logs on the Cluster Manager and idx-peer-02 for replication errors","Verify network connectivity between peers on the replication port","Immediately lower the cluster's replication factor to 1 to clear the warning"], a:[0,1,2], e:"Investigate the failing peer: <b>disk/health</b>, its <b>_internal</b> logs, and <b>network</b> between peers. Dropping the replication factor to 1 is not a remedy - it removes redundancy and risks data loss; the cluster normally self-heals once the peer is fixed.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"dsearch", q:"A specific report search over 30 days with several transforming commands is consistently slow. What is the most effective <b>initial</b> step to diagnose why?", o:["Open the Job Inspector to review execution costs and see which phases/commands dominate the runtime","Immediately add more indexers","Restart the search head","Raise the license quota"], a:[0], e:"The <b>Job Inspector</b> breaks down where a search spends its time (command durations, scan counts, whether work is pushed to indexers). It is the correct first diagnostic before making infrastructure changes.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Search/ViewsearchjobpropertieswiththeJobInspector"},
 {exam:"admin", cat:"dsearch", q:"In an indexer cluster, which statement <b>MOST</b> accurately describes the primary role of the manager node (cluster manager)?", o:["It replicates and searches bucket copies alongside the peers so it can help satisfy the search factor","It orchestrates the peer nodes - directing where bucket copies are streamed, tracking the state of every bucket, and driving remedial <b>fixup</b> to meet the replication and search factors","It acts as the elected captain that schedules and runs users' searches across the peers","It serves as the license manager that meters and enforces the license for all peers"], a:[1], e:"The <b>manager node</b> (cluster manager) <b>coordinates</b> the cluster: it tells <b>peer nodes</b> where to stream and store bucket copies, tracks the state of every bucket, and drives remedial <b>bucket fixup</b> to keep the replication/search factors met. It does <b>not</b> index external data, run searches, or act as a captain (that is a search head cluster role), and the license manager is a separate role.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"dsearch", q:"A search head cluster is misbehaving after someone installed an app directly on a member. Which statement correctly distinguishes the <b>deployer</b> from the <b>captain</b>?", o:["The deployer is an elected member that replicates knowledge objects, while the captain is the standalone node that distributes the configuration bundle","The deployer is a standalone instance <b>outside</b> the cluster that distributes apps and the configuration bundle to members; the captain is an <b>elected member</b> that coordinates runtime activity","The deployer pushes the configuration bundle and also serves as the fallback captain if a captain election fails","The deployer and captain are both elected member roles that rotate among the members on each restart"], a:[1], e:"The <b>deployer</b> is a standalone instance <b>outside</b> the search head cluster that pushes apps and non-runtime config (the <b>configuration bundle</b>) to members. The <b>captain</b> is an <b>elected member</b> that handles runtime coordination - scheduling searches, replicating knowledge objects. They are different roles; the deployer is never a member and never becomes captain, and apps should be pushed via the deployer, not installed directly on a member.", d:"https://docs.splunk.com/Documentation/Splunk/latest/DistSearch/AboutSHC"},
 {exam:"admin", cat:"dsearch", q:"On a deployment server, what does a <b>server class</b> define?", o:["A grouping of <b>deployment clients</b> (selected with whitelist/blacklist filters) mapped to the <b>apps</b> the deployment server should deploy to them","A grouping of forwarders by hardware class that determines their maximum indexing throughput","A mapping of indexer <b>peer nodes</b> to the buckets each must replicate","A named set of apps the deployer distributes to search head cluster members"], a:[0], e:"A <b>server class</b> groups <b>deployment clients</b> - selected with whitelist/blacklist filters on clientName, host, IP, or DNS - and maps them to the <b>apps</b> the deployment server pushes to that group. Defined in <code>serverclass.conf</code> or via Forwarder Management. It has nothing to do with hardware, bucket replication (a cluster manager concern), or the deployer/SHC configuration bundle.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Updating/Forwardermanagementoverview"},
 {exam:"admin", cat:"dsearch", q:"In a <b>multisite</b> indexer cluster, what do <code>site_replication_factor</code> and <code>site_search_factor</code> control?", o:["They specify how total (replication) and searchable (search) bucket copies are distributed <b>per site</b>, so the cluster can survive losing an entire site","They set only the cluster-wide total number of copies, overriding <code>replication_factor</code> and <code>search_factor</code>","They define how many search heads and forwarders each site must maintain for failover","They cap the daily license volume that each individual site is allowed to index"], a:[0], e:"In a <b>multisite</b> cluster, <b>site_replication_factor</b> and <b>site_search_factor</b> specify how many total and searchable copies are kept <b>per site</b> (for example <code>origin:2,total:3</code>), so the cluster survives the loss of an entire site - not just individual peers. They complement, not replace, the base factors and have nothing to do with search-head counts or licensing.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"dsearch", q:"In distributed search, how do search peers (indexers) get the knowledge objects needed to run a search head's searches?", o:["Each peer is configured manually","The search head replicates its <b>knowledge bundle</b> (apps, lookups, and knowledge objects) to the search peers","The deployment server pushes them","They are stored in the license"], a:[1], e:"The search head packages its apps and knowledge objects into a <b>knowledge bundle</b> and <b>replicates</b> it to the <b>search peers</b>, so they apply the correct field extractions, lookups, and definitions when running the search. Large bundles can be trimmed to speed replication.", d:"https://docs.splunk.com/Documentation/Splunk/latest/DistSearch/Whatisdistributedsearch"},
 {exam:"admin", cat:"dsearch", q:"In a clustered environment, which capability does <b>indexer discovery</b> MOST directly provide to forwarders?", o:["It lets forwarders auto-detect new sourcetypes and inputs on the hosts they monitor","It lets forwarders poll the <b>cluster manager</b> for the current list of <b>peer nodes</b> and load-balance across them, instead of a hard-coded <code>outputs.conf</code> server list","It lets the cluster manager push already-indexed data back to forwarders for local caching","It lets peer nodes discover each other in order to elect the cluster manager automatically"], a:[1], e:"With <b>indexer discovery</b>, forwarders query the <b>cluster manager</b> for the live list of <b>peer nodes</b> and load-balance across them - so you don't hard-code indexer addresses in <code>outputs.conf</code>, and the list updates automatically as peers join or leave. It is about the outbound target list, not input detection, data caching, or manager election.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutclusters"},
 {exam:"admin", cat:"indexes", q:"You need <code>web_access</code> data automatically deleted 120 days after it is ingested. Which indexes.conf attribute most directly enforces that age-based deletion?", o:["frozenTimePeriodInSecs = 10368000","coldToFrozenDir = /archive","maxTotalDataSizeMB = 500000","homePath.maxDataSizeMB = 1000"], a:[0], e:"<b>frozenTimePeriodInSecs</b> rolls (and, with no archive path, deletes) buckets once their data reaches the given age - 120 days = 10,368,000 seconds. <code>coldToFrozenDir</code> would <b>archive</b> instead of delete; the size settings cap size, not age.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Setaretirementandarchivingpolicy"},
 {exam:"admin", cat:"confs", q:"A custom app contains <code>inputs.conf</code> (data collection), <code>props.conf</code>/<code>transforms.conf</code> (parsing), and dashboards. In a distributed deployment, where should each part typically live?", o:["inputs on the data-collecting forwarders; parsing (props/transforms) on the indexers (or heavy forwarders); dashboards/search-time settings on the search heads","All parts on the indexers only","All parts on the search heads only","inputs on the search heads; dashboards on the forwarders"], a:[0], e:"Deploy config where it takes effect: <b>inputs</b> where data is collected (forwarders), <b>index-time parsing</b> where parsing happens (indexers/heavy forwarders), and <b>dashboards / search-time knowledge</b> on the search heads.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Aboutconfigurationfiles"},
 {exam:"admin", cat:"confs", q:"Which capability/feature lets an admin run a saved search on a cron schedule and store or alert on its results?", o:["A scheduled report/saved search (savedsearches.conf)","A monitor input","A deployment app","A metrics index"], a:[0], e:"<b>Saved searches</b> (scheduled reports/alerts, stored in <code>savedsearches.conf</code>) run on a cron schedule and can save results, populate summary indexes, or trigger alert actions.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Report/Schedulereports"},
 {exam:"admin", cat:"parsing", q:"For an automatic (field-based) lookup, which configuration file defines the lookup <b>transform</b> - the lookup table plus its input/output fields - that props.conf then references?", o:["transforms.conf","inputs.conf","indexes.conf","outputs.conf"], a:[0], e:"The lookup definition (table file, input/output fields, matching type) lives in <b>transforms.conf</b>; <b>props.conf</b> uses a <code>LOOKUP-&lt;name&gt;</code> stanza to apply it automatically at search time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Knowledge/Aboutlookupsandfieldactions"},
 {exam:"admin", cat:"users", q:"A new person needs a limited admin role: manage data inputs and users, but must NOT create/modify indexes or see sensitive security data. What is the best-practice starting point?", o:["Create a custom role that inherits a low-privilege role (e.g. user) and grant only the specific capabilities and index access needed","Assign the built-in admin role as-is","Give them the power role unchanged","Add the capabilities directly to the individual user account"], a:[0], e:"Follow <b>least privilege</b>: build a <b>custom role</b> (inheriting a minimal role) and grant only the needed capabilities and <code>srchIndexesAllowed</code> entries. Handing out full <b>admin</b> over-provisions, and capabilities are granted via <b>roles</b>, not directly to users.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"users", q:"A security analyst must search only the <code>web_logs</code> and <code>firewall</code> indexes and build their own private reports, but must not change system config, create indexes, administer users, or share objects globally. Which steps fit best practice? (Choose all that apply.)", o:["Create a custom role and set <code>srchIndexesAllowed</code> to web_logs and firewall","Grant only search/report capabilities, not admin capabilities","Leave object sharing at the private (owner) level rather than global","Give the analyst the admin role so they can self-serve"], a:[0,1,2], e:"Scope index access with <b>srchIndexesAllowed</b>, grant only the needed <b>capabilities</b> (no admin), and keep their knowledge objects <b>private</b>. Granting admin would violate least privilege and let them do everything they must not.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"users", q:"Which steps are required to enable LDAP authentication in Splunk? (Choose all that apply.)", o:["Define an LDAP strategy (server host/port, bind DN and credentials, user/group base DNs)","Map LDAP groups to Splunk roles","Set the authentication type to LDAP","Disable the indexer's receiving port"], a:[0,1,2], e:"LDAP setup: create an <b>LDAP strategy</b> (connection + bind + search base), <b>map LDAP groups to Splunk roles</b>, and switch the <b>authentication type</b> to LDAP (via Settings &gt; Access Controls or authentication.conf). Receiving ports are unrelated to auth.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"parsing", q:"A file is line-breaking and timestamping incorrectly for one sourcetype. Which configuration file is the <b>primary</b> place to fix this parsing behavior?", o:["<b>props.conf</b> - it applies parsing and search-time settings keyed by <b>source, sourcetype, or host</b> (line breaking, timestamp rules, extractions, and <code>TRANSFORMS</code>/<code>LOOKUP</code> references)","<b>transforms.conf</b> - it holds the <code>REGEX</code>/<code>FORMAT</code>/<code>DEST_KEY</code> stanzas that define index-time routing and field creation","<b>outputs.conf</b> - it specifies which indexers a forwarder sends data to and the load-balancing behavior","<b>indexes.conf</b> - it configures index storage paths, sizes, and bucket retention"], a:[0], e:"<b>props.conf</b> is where you control how data is interpreted for a given <b>source/sourcetype/host</b>: event line breaking, timestamp recognition (<code>TIME_FORMAT</code>, <code>TZ</code>), field extractions, and <code>TRANSFORMS</code>/<code>LOOKUP</code> references. <b>transforms.conf</b> only holds the regex stanzas that props.conf <b>references</b>; outputs.conf and indexes.conf handle forwarding targets and storage, not parsing.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/HowSplunkextractstimestamps"},
 {exam:"admin", cat:"inputs", q:"On a <code>[monitor://...]</code> input, what do the <code>whitelist</code> and <code>blacklist</code> settings do, and which wins on a conflict?", o:["<b>whitelist</b> indexes only files whose path matches its regex; <b>blacklist</b> excludes files matching its regex (same regex syntax), and <b>blacklist</b> wins when both match","Both use glob patterns rather than regex, and <b>whitelist</b> overrides <b>blacklist</b> when a file matches both","They restrict which roles and users are permitted to search the resulting events","<b>whitelist</b> sets the sourcetype and <b>blacklist</b> sets the index for the matched files"], a:[0], e:"On a <code>[monitor://...]</code> stanza, <b>whitelist</b> (include) indexes only files whose path matches the regex, and <b>blacklist</b> (exclude) skips matching files. Both take a <b>regular expression</b> (not a glob) with identical syntax, and <b>blacklist wins</b> when a file matches both. They do not control access, sourcetype, or index assignment.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Specifyinputpathswithwildcards"},
 {exam:"admin", cat:"inputs", q:"Which monitor input setting tells Splunk to skip files whose modification time is older than a time window - and keep ignoring them even if they are updated later?", o:["followTail","ignoreOlderThan","crcSalt","recursive"], a:[1], e:"<code>ignoreOlderThan = 7d</code> makes Splunk ignore files whose <b>modification time</b> is outside the window. Such files are ignored even if later updated, so use it carefully for backfill scenarios.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"A monitor input is set with <code>followTail = 1</code> on a large, existing log file. What is the effect the first time monitoring starts?", o:["Splunk indexes the file from the beginning, then continues tailing newly appended data","Splunk ignores the file's current contents and indexes only data <b>appended after</b> monitoring begins","Splunk re-reads the entire file on every change to capture late edits","Splunk follows the file through log rotation by tracking its inode"], a:[1], e:"<b>followTail = 1</b> makes Splunk skip a file's current contents and index only <b>new</b> data as it arrives after monitoring starts. It should <b>not</b> be left enabled indefinitely - once the file is caught up you normally remove it. It does not read from the beginning, re-read the whole file, or manage rotation tracking.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"A monitor input uses <code>[monitor:///var/log/]</code> with <code>host_segment = 3</code>. For the file <code>/var/log/www3/app.log</code>, how is the host determined?", o:["The host is set to the value of the <b>3rd segment of the file path</b> (<code>www3</code>)","The host is set to the 3rd segment counted from the <b>end</b> of the path","The host is set to <code>var</code>, the directory being monitored","The host defaults to the forwarder's hostname, because <code>host_segment</code> applies only to network inputs"], a:[0], e:"<code>host_segment = &lt;n&gt;</code> sets the host from the <b>nth segment of the file path</b>, counting from the start. For <code>/var/log/www3/app.log</code> with <code>host_segment=3</code>, the segments are <code>var</code>(1), <code>log</code>(2), <code>www3</code>(3), so the host becomes <b>www3</b> - handy when the directory name identifies the source host.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"Which are valid ways to set the <code>host</code> field value for a file/directory input? (Choose all that apply.)", o:["A static value with <code>host = &lt;name&gt;</code>","From a path segment with <code>host_segment = &lt;n&gt;</code>","With a regex using <code>host_regex</code>","From the license manager"], a:[0,1,2], e:"Host can be set <b>statically</b> (<code>host=</code>), from a <b>path segment</b> (<code>host_segment</code>), or via a <b>regex</b> on the source path (<code>host_regex</code>). The license manager has nothing to do with host assignment.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"inputs", q:"In a monitor input path, which wildcard matches across <b>multiple</b> directory levels (recursively)?", o:["<code>*</code> - a single asterisk, which by itself spans any number of directory levels","<code>...</code> - three dots (ellipsis)","<code>**</code> - a double asterisk","<code>*/</code> - an asterisk followed by a slash"], a:[1], e:"<b>...</b> (ellipsis) recurses through <b>multiple</b> directory levels, while a single <b>*</b> matches only within a <b>single</b> path segment (anything except the path separator). <code>**</code> is not valid Splunk monitor syntax. Example: <code>[monitor:///var/log/.../*.log]</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Specifyinputpathswithwildcards"},
 {exam:"admin", cat:"parsing", q:"By default, Splunk sets incoming input data to which character encoding, and how do you override it?", o:["ASCII; override with ENCODING","UTF-8; override per source/sourcetype/host with CHARSET (e.g. CHARSET = EUC-KR, or CHARSET = AUTO)","Latin-1; it cannot be changed","UTF-16; override with LANG"], a:[1], e:"During the input phase Splunk encodes data as <b>UTF-8</b> by default. Override with the <code>CHARSET</code> attribute in props.conf (e.g. <code>CHARSET = EUC-KR</code>), or use <code>CHARSET = AUTO</code> to detect the encoding automatically.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Configurecharactersetencoding"},
 {exam:"admin", cat:"parsing", q:"For structured data (CSV, TSV, JSON, W3C), which props.conf setting extracts fields at <b>index time</b>?", o:["EXTRACT","INDEXED_EXTRACTIONS","REPORT","KV_MODE"], a:[1], e:"<code>INDEXED_EXTRACTIONS = &lt;csv|tsv|json|w3c&gt;</code> parses structured files and extracts their fields at <b>index time</b>. Companions like <code>HEADER_FIELD_LINE_NUMBER</code> and <code>TIMESTAMP_FIELDS</code> tell Splunk where the header and timestamp live.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Extractfieldsfromfileswithstructureddata"},
 {exam:"admin", cat:"parsing", q:"props.conf stanzas can target <code>[&lt;sourcetype&gt;]</code>, <code>[source::...]</code>, and <code>[host::...]</code>. When more than one matches an event, which type has the HIGHEST precedence?", o:["[&lt;sourcetype&gt;]","[host::...]","[source::...]","They are equal"], a:[2], e:"For the same setting, precedence is <b>source &gt; host &gt; sourcetype</b> - the pattern-matching <code>[source::...]</code> stanza wins, then <code>[host::...]</code>, then the plain <code>[sourcetype]</code> stanza.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/Aboutconfigurationfiles"},
 {exam:"admin", cat:"inputs", q:"Which Windows input type collects performance metrics such as CPU, memory, and disk utilization?", o:["[WinEventLog://...]","[perfmon://...]","[monitor://...]","[script://...]"], a:[1], e:"The <b>perfmon</b> input (<code>[perfmon://&lt;object&gt;]</code>) collects Windows performance counters (CPU, memory, disk, network). <code>WinEventLog</code> collects event logs; both ship with the Splunk Add-on for Windows.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/MonitorWindowseventlogdata"},
 {exam:"admin", cat:"inputs", q:"What is the recommended way to collect OS metrics and logs from many Linux hosts (CPU, memory, /var/log, etc.)?", o:["A universal forwarder plus the Splunk Add-on for Unix and Linux (scripted/monitor inputs)","Open a UDP port on each indexer","Enable HEC on each Linux host","Use a heavy forwarder on the search head"], a:[0], e:"Deploy a <b>universal forwarder</b> on each Linux host and install the <b>Splunk Add-on for Unix and Linux</b>, which provides the scripted and monitor inputs (and sourcetypes) for OS metrics and logs.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"parsing", q:"When you preview structured data and see a timestamp warning, what should you do?", o:["Ignore it - timestamps are optional","Specify which field holds the timestamp (e.g. TIMESTAMP_FIELDS) so Splunk assigns _time correctly","Delete the header row","Switch the input to a network input"], a:[1], e:"For structured (indexed-extraction) data, tell Splunk where the timestamp is with <code>TIMESTAMP_FIELDS = &lt;field(s)&gt;</code> (and <code>HEADER_FIELD_LINE_NUMBER</code> for the header). Otherwise events may get the file-modification or current time.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Extractfieldsfromfileswithstructureddata"},
 {exam:"admin", cat:"gdi", q:"In Splunk Web, which menu path launches the guided <b>Add Data</b> wizard to onboard a file or directory?", o:["<b>Settings &gt; Add Data</b>","<b>Settings &gt; Data inputs</b>","<b>Apps &gt; Add Data</b>","<b>Search &amp; Reporting &gt; Add Data</b>"], a:[0], e:"<b>Settings &gt; Add Data</b> opens the guided wizard (Select Source → Set Source Type → Input Settings → Review → Submit). <b>Settings &gt; Data inputs</b> is a different page for managing existing input stanzas by type, not the guided onboarding wizard.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Aboutdefaultfields"},
 {exam:"admin", cat:"gdi", q:"The Add Data wizard offers three top-level ways to get data in. Which set is correct?", o:["<b>Upload</b>, <b>Monitor</b>, and <b>Forward</b>","<b>Upload</b>, <b>Monitor</b>, and <b>Index</b>","<b>Oneshot</b>, <b>Monitor</b>, and <b>Forward</b>","<b>Upload</b>, <b>Tail</b>, and <b>Receive</b>"], a:[0], e:"The three choices are <b>Upload</b> (index a file once, like a oneshot), <b>Monitor</b> (continuously watch local files/ports/scripts), and <b>Forward</b> (receive from forwarders). Upload runs on the instance you are logged into. <code>oneshot</code> and <code>tail</code> are CLI/concept terms, not the wizard's labels.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Aboutdefaultfields"},
 {exam:"admin", cat:"inputs", q:"After you finish the Add Data wizard for a continuously monitored file, what does Splunk create behind the scenes?", o:["A [monitor://...] stanza in inputs.conf","A saved search","A new index automatically","A transforms.conf lookup"], a:[0], e:"The wizard writes a <code>[monitor://&lt;path&gt;]</code> stanza to <b>inputs.conf</b> (in the current app context), with your chosen index, sourcetype, and host - exactly what the CLI <code>splunk add monitor</code> would produce.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Data/Monitorfilesanddirectories"},
 {exam:"admin", cat:"indexes", q:"Where in Splunk Web do you create a new index?", o:["Settings &gt; Indexes &gt; New Index","Settings &gt; Data Inputs &gt; New","Search &gt; Create Index","Settings &gt; Server settings"], a:[0], e:"<b>Settings &gt; Indexes &gt; New Index</b>. You choose the index name, data type (Events or Metrics), and optional size/retention - written to indexes.conf.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Indexer/Aboutmanagingindexes"},
 {exam:"admin", cat:"forwarders", q:"To make an indexer receive data from forwarders using Splunk Web, where do you go?", o:["Settings &gt; Forwarding and receiving &gt; Configure receiving","Settings &gt; Data Inputs &gt; TCP","Settings &gt; Distributed search","Settings &gt; Server controls"], a:[0], e:"<b>Settings &gt; Forwarding and receiving &gt; Configure receiving &gt; New Receiving Port</b> (e.g. 9997). The CLI equivalent is <code>splunk enable listen 9997</code>.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Forwarding/Enableareceiver"},
 {exam:"admin", cat:"deploy", q:"Where in Splunk Web is the <b>Monitoring Console</b> accessed?", o:["<b>Settings &gt; Monitoring Console</b>","<b>Settings &gt; Distributed Management Console</b>","<b>Apps &gt; Monitoring Console</b>","<b>Settings &gt; Server settings &gt; Health report manager</b>"], a:[0], e:"<b>Settings &gt; Monitoring Console</b>. It runs in <b>standalone</b> or <b>distributed</b> mode and shows deployment health - indexing rate, search load, and resource usage. <b>Distributed Management Console</b> is the old (pre-6.5) name and is no longer the menu path, and <b>Health report manager</b> configures the feature-health indicator, not the Monitoring Console.", d:"https://docs.splunk.com/Documentation/Splunk/latest/DMC/DMCoverview"},
 {exam:"admin", cat:"deploy", q:"You renamed the server under Settings &gt; Server settings &gt; General settings. What is required for the change to take effect?", o:["Nothing - it's immediate","A restart of Splunk (via Settings &gt; Server controls or the Messages menu)","A re-index of all data","A new license"], a:[1], e:"Server name / general settings changes require a <b>restart</b>. Splunk prompts you; restart from <b>Settings &gt; Server controls &gt; Restart Splunk</b> (or the Messages menu).", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/StartSplunk"},
 {exam:"admin", cat:"users", q:"A user reports that their <b>Settings</b> menu shows only an abridged list of options. What does this most likely indicate?", o:["Splunk Web is broken","They have a non-admin role (e.g. power/user) with limited capabilities - admins see the full Settings list","Their license expired","They are on a forwarder"], a:[1], e:"The <b>Settings</b> menu reflects the user's <b>role/capabilities</b>. A <b>power</b> or <b>user</b> role sees fewer options; the full administrative list appears only for the <b>admin</b> role.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"users", q:"In Splunk Web, where do you create users and roles?", o:["Settings &gt; Users and authentication (Access Controls) &gt; Roles / Users","Settings &gt; Server settings","Settings &gt; Data Inputs","Apps &gt; Permissions"], a:[0], e:"Under <b>Settings &gt; Users and authentication</b> (Access Controls) you manage <b>Roles</b> (capabilities + <code>srchIndexesAllowed</code>) and <b>Users</b> (assigned roles), plus authentication methods.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Security/Aboutusersandroles"},
 {exam:"admin", cat:"deploy", q:"How do you display a colored <b>global banner</b> in Splunk Web (e.g. to mark which instance you're on)?", o:["Settings &gt; Server settings &gt; Global banner","Settings &gt; Monitoring Console","edit web.conf only","Search &gt; Banner"], a:[0], e:"<b>Settings &gt; Server settings &gt; Global banner</b> lets you turn on a banner, set its background color, and message - a common way to distinguish prod vs. lab instances.", d:"https://docs.splunk.com/Documentation/Splunk/latest/Admin/StartSplunk"},
 /* --- Infrastructure & Sizing: out-of-guide operational facts (doc-verified against Splunk reference hardware, ulimit, and THP docs) --- */
 {exam:"admin", cat:"infra", q:"An indexer's <b>hot and warm</b> buckets require which storage type for acceptable performance?", o:["A 7200-RPM HDD","<b>SSD</b> (local high-performance)","A NAS/NFS network share","Tape or object storage"], a:[1], e:"Hot/warm bucket storage (and data model acceleration) demands <b>local SSD</b>. Cold and frozen buckets can go on cheaper HDD/SAN/NAS/NFS, but hot/warm must <b>never</b> sit on network volumes — latency cripples indexing. This exact 'what storage for an indexer' question blindsides people because it isn't in the exam guide.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"For <b>SmartStore</b>, what local storage does Splunk recommend for the cache tier alongside the remote object store?", o:["<b>NVMe or SSD</b>","7200-RPM HDD","Tape","A RAM disk only"], a:[0], e:"SmartStore keeps a high-performance local cache (<b>NVMe or SSD</b>) for recent reads/writes and fetches older buckets on demand from a remote object store (e.g. S3). The local cache is not optional — it's where active searches actually run.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"The storage volume where Splunk is installed should provide <b>no fewer than</b> how many sustained IOPS?", o:["50 IOPS","100 IOPS","<b>800 IOPS</b>","5 IOPS"], a:[2], e:"Splunk requires <b>≥ 800 sustained IOPS</b> (an HDD-based search head likewise ≥ 800). Insufficient storage I/O is the single most common Splunk infrastructure bottleneck — an SSD-level indexer is often sized nearer ~4000 IOPS.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"What is the <b>minimum</b> reference-hardware CPU spec for a Splunk Enterprise <b>indexer</b>?", o:["4 physical cores","<b>12 physical cores</b> (or 24 vCPU) at ≥ 2 GHz","48 physical cores","2 vCPU"], a:[1], e:"Reference indexer = <b>12 physical CPU cores</b> (or 24 vCPU) + 12 GB RAM. Mid-range = 24 cores/64 GB RAM; high-performance = 48 cores/128 GB RAM.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"In Splunk's reference hardware, how does a <b>search head's</b> minimum CPU core count compare to an <b>indexer's</b>?", o:["Lower — 8 vs 12","Identical at 12","<b>Higher — 16 physical cores vs the indexer's 12</b>","Search heads have no CPU spec"], a:[2], e:"A search head's minimum is <b>16 physical cores</b> (32 vCPU) vs the indexer's 12 — because each active search consumes up to a full CPU core, and scheduled plus ad-hoc searches stack up. Easy trap: people assume the indexer needs more.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"How much CPU does a <b>single active search</b> consume on a search head?", o:["Half a core","<b>Up to 1 full CPU core</b> for the duration of the search","Up to 4 cores","No measurable CPU"], a:[1], e:"Each running search uses <b>up to one CPU core</b> while active. This is why search-head sizing scales with concurrent (scheduled + ad-hoc) search load, not with data volume.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"By default, what happens when the disk volume holding an index drops below <b>5 GB</b> of free space?", o:["Oldest data auto-deletes to make room","<b>Indexing stops (pauses)</b> until space is freed","Splunk moves the data to cold","Nothing happens"], a:[1], e:"The default <code>minFreeSpace</code> is 5000 MB; when free space falls below it, Splunk <b>stops indexing</b> to protect the volume — it does <b>not</b> auto-delete data. Monitoring indexer free space is an admin responsibility.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"On Linux, Splunk recommends raising the <b>open files</b> (<code>nofile</code>) ulimit to at least what, up from the common default of 1024?", o:["2048","<b>64000</b>","1024","10"], a:[1], e:"Splunk recommends <code>nofile</code> (open files) <b>≥ 64000</b> and <code>nproc</code> (user processes) ≥ 16000, with file size unlimited. The default 1024 open files is far too low and logs <code>ulimit</code> errors in <code>splunkd.log</code>.", d:AD_ULIMIT, hard:true},
 {exam:"admin", cat:"infra", q:"What minimum <b>max user processes</b> (<code>nproc</code>) ulimit does Splunk recommend on *nix?", o:["256","1024","<b>16000</b>","64000"], a:[2], e:"Recommended <code>nproc</code> <b>≥ 16000</b> (with open files ≥ 64000 and file size unlimited). Low ulimits cause instability and crashes that surface as <code>ulimit</code> errors in <code>splunkd.log</code>.", d:AD_ULIMIT, hard:true},
 {exam:"admin", cat:"infra", q:"Before running Splunk on Linux, Splunk recommends <b>disabling</b> which OS feature to avoid a significant performance hit?", o:["SELinux entirely","IPv6","Swap","<b>Transparent Huge Pages (THP)</b>"], a:[3], e:"<b>Transparent Huge Pages (THP)</b> degrade Splunk performance; disabling THP can improve indexing and search performance by roughly <b>30%</b>. It's a required pre-install step people routinely miss.", d:AD_THP, hard:true},
 {exam:"admin", cat:"infra", q:"With <code>maxDataSize = auto</code>, how large can a <b>hot bucket</b> grow before it rolls to warm?", o:["<b>750 MB</b>","10 GB","100 MB","Unlimited"], a:[0], e:"<code>auto</code> ≈ <b>750 MB</b>. For high-volume indexes (like <code>main</code>) use <code>auto_high_volume</code>, which is <b>10 GB on 64-bit</b> systems (1 GB on 32-bit).", d:AD_IDX, hard:true},
 {exam:"admin", cat:"infra", q:"For a high-volume index such as <code>main</code>, which <code>maxDataSize</code> is recommended, and how big is it on 64-bit?", o:["<code>auto</code> — 750 MB","<b><code>auto_high_volume</code> — 10 GB</b>","<code>max</code> — 100 GB","<code>small</code> — 100 MB"], a:[1], e:"<code>auto_high_volume</code> rolls a hot bucket to warm at <b>10 GB on 64-bit</b> (1 GB on 32-bit). Use it for high-volume indexes; use <code>auto</code> (750 MB) for everything else.", d:AD_IDX, hard:true},
 {exam:"admin", cat:"infra", q:"Which storage is acceptable for <b>cold</b> index buckets but <b>not</b> for hot/warm?", o:["Only SSD","<b>NAS/NFS or other network file systems</b>","RAM","Only NVMe"], a:[1], e:"<b>Cold</b> (and frozen) buckets may live on slower, cheaper HDD, SAN, NAS, or NFS. <b>Hot/warm</b> buckets must never sit on network volumes — network latency dramatically slows indexing.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"Splunk recommends network latency between <b>indexer cluster</b> nodes not exceed what?", o:["<b>100 ms</b>","1000 ms","10 ms","5 seconds"], a:[0], e:"Indexer cluster nodes: <b>≤ 100 ms</b> latency (search head clusters ≤ 200 ms). Higher latency badly slows indexing and cluster recovery / captain election — a real multi-site design constraint.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"Running an indexer on a <b>virtual machine</b> instead of bare metal typically has what effect on data ingest?", o:["No difference","<b>~10–15% slower ingest</b>","About 2× faster","Ingest becomes impossible"], a:[1], e:"A virtualized indexer can consume data about <b>10–15% slower</b> than bare metal (search performance is roughly similar). The hypervisor must <b>reserve</b> resources meeting the reference spec.", d:AD_REFHW, hard:true},
 {exam:"admin", cat:"infra", q:"Which CPU instruction-set support does Splunk's App <b>Key Value Store</b> (KV Store) require?", o:["Only AVX-512","<b>AVX, SSE4.2, and AES-NI</b>","ARM NEON","None — any 32-bit CPU works"], a:[1], e:"The reference architecture requires <b>x86-64</b> CPUs (Intel Sandy Bridge+ / AMD Bulldozer 15h GEN3+) with <b>AVX, SSE4.2, and AES-NI</b> — these are needed by the KV Store.", d:AD_REFHW, hard:true}
];

