Object.assign(CATEGORIES, {
  c1over:     {name:"Splunk Cloud Overview", weight:5, doc:CL_EXP, blurb:"Shared responsibility, Victoria versus Classic, no CLI or filesystem access, and what Splunk operates versus what you own."},
  c2index:    {name:"Index Management", weight:5, doc:CL_MANIDX, blurb:"Creating indexes in Web and ACS, searchable versus archived retention, DDSS and DDAA, and why delete does not reclaim disk."},
  c3auth:     {name:"User Authentication & Roles", weight:5, doc:CL_AUTH, blurb:"sc_admin, role inheritance and capabilities, SAML and LDAP on Cloud, and index-level access control."},
  c4conf:     {name:"Configuration Files", weight:5, doc:CL_ACS, blurb:"Layer precedence, app and user context, btool, and which settings ACS exposes when there is no filesystem."},
  c5gdi:      {name:"Getting Data In", weight:15, doc:CL_FWD, blurb:"The credentials package, UF versus HF, load balancing versus data cloning, indexer acknowledgment, and the IDM."},
  c6fwdmgmt:  {name:"Forwarder Management", weight:5, doc:AD_FWDMGMT, blurb:"The customer-hosted deployment server, serverclass targeting, app reload behaviour, and confirming forwarders are alive."},
  c7monitor:  {name:"Monitor Inputs", weight:15, doc:CL_MONITOR, blurb:"Wildcards and recursion, allow and deny lists, CRC fingerprinting and log rotation, host_segment, and batch versus monitor."},
  c8network:  {name:"Network & Other Inputs", weight:10, doc:CL_NET, blurb:"TCP and UDP stanzas, persistent queues, scripted inputs, Windows and WMI collection, and HEC on Cloud."},
  c9finetune: {name:"Fine-tuning Inputs", weight:5, doc:CL_SRCTYPE, blurb:"Input phase versus parsing phase, source type precedence, CHARSET, and what the queue setting bypasses."},
  c10parse:   {name:"Parsing & Data Preview", weight:10, doc:CL_LINEBRK, blurb:"LINE_BREAKER versus line merging, TRUNCATE, timestamp and time zone precedence, and what Data Preview cannot prove."},
  c11rawdata: {name:"Manipulating Raw Data", weight:10, doc:CL_SEDCMD, blurb:"SEDCMD, index-time transforms, routing and filtering to nullQueue, and masking sensitive fields before indexing."},
  c12apps:    {name:"Apps", weight:5, doc:CL_PRIVAPP, blurb:"Self-service install, AppInspect vetting, private apps, and premium apps that require Support."},
  c13support: {name:"Cloud Support", weight:5, doc:CL_SUPPORT, blurb:"Self-triage with the CMC, authorized support contacts, severity tiers, and what genuinely needs a case."},
});
const CLOUD_CAT_ORDER = ['c1over','c2index','c3auth','c4conf','c5gdi','c6fwdmgmt','c7monitor','c8network','c9finetune','c10parse','c11rawdata','c12apps','c13support'];

const CLOUD_QUESTIONS = [
 /* --- Splunk Cloud Overview --- */
 {exam:"cloudadmin",cat:"c1over",q:"Your Splunk Cloud Platform stack is being migrated from Classic Experience to Victoria Experience. A cloud add-on with a modular input currently runs on your Inputs Data Manager (IDM). What happens to that input after the migration completes?",o:["The IDM remains in the stack, and the modular input keeps running there unchanged after migration.","The modular input is disabled until Support reinstalls the add-on on a heavy forwarder you host.","Splunk migrates the IDM apps and configs to the search tier and removes the IDM from the stack.","The add-on is moved to the indexer tier, where Victoria Experience runs all scripted inputs."],a:[2],e:"Victoria Experience does not require an IDM. Splunk docs state that on upgrade from Classic to Victoria, Splunk <b>migrates all apps, customizations, and configs from the IDM to the primary search head or search head cluster, and removes the IDM</b> — modular and scripted inputs then run directly on the search tier. The trap is option 0: on Classic the IDM is exactly where that input must live, so keeping it feels right. The exam is testing that the IDM is a Classic-only tier. Practical follow-on the docs call out: if your IDM had special IP allowlisting, you must move that allowlisting to the search head IPs (all SHC member IPs if clustered), because the inputs now originate there.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/get-started-managing-splunk-cloud-platform/determine-your-splunk-cloud-platform-experience",hard:true},
 {exam:"cloudadmin",cat:"c1over",q:"A new Splunk Cloud Platform administrator asks why they cannot SSH to the indexers to run <code>btool</code> or hand-edit <code>props.conf</code>. Which statement correctly describes the Splunk Cloud Platform operating model?",o:["No CLI or file system access is provided, so those tasks use self-service or a support case.","CLI access is granted on the search tier only, using credentials from the Splunk welcome email.","CLI access is granted once Support enables the REST API and registers your IP allow list entry.","CLI access is granted on the IDM only, which is why Classic Experience stacks still have one."],a:[0],e:"The Service Description is explicit: Splunk Cloud Platform does not allow direct access to infrastructure, so there is <b>no CLI access at all</b>, and any supported task requiring it is performed either by a Splunk self-service capability (Splunk Web, ACS API/CLI) or by filing a service ticket. The Admin Manual repeats it: you cannot use CLI commands or manually edit .conf files. The closest distractor is option 2 — REST API access on port 8089 genuinely does require a Support case plus an IP allow list, so the mechanics sound familiar. But REST is an API, not shell access; enabling it never yields a command line. The exam is testing the boundary between what you self-serve and what needs a case.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/get-started-managing-splunk-cloud-platform/welcome-to-the-splunk-cloud-platform-admin-manual",hard:true},
 {exam:"cloudadmin",cat:"c1over",q:"While planning a migration from Splunk Enterprise to Splunk Cloud Platform, an architect wants forwarders to learn the current indexer list dynamically instead of hard-coding targets in <code>outputs.conf</code>. What should you tell them?",o:["Indexer Discovery works in Cloud once Support opens port 8089 outbound from your forwarder tier.","Indexer Discovery works in Cloud on Victoria Experience, but Classic Experience requires a case.","Indexer Discovery works in Cloud for S2S forwarding, but not for HTTP Event Collector clients.","Indexer Discovery is not supported in Splunk Cloud Platform, for forwarders or for HEC clients."],a:[3],e:"The Splunk Cloud Platform Service Description lists Indexer Discovery under differences from Splunk Enterprise: <b>Indexer Discovery is not supported in Splunk Cloud Platform, and this applies to both HEC and forwarders</b>. You instead deploy the Splunk Cloud forwarder credentials app, which carries the correct outputs configuration for your stack. The closest distractor is option 2 — it borrows the real pattern from indexer acknowledgement, which genuinely is supported for S2S but only for specific HEC clients such as AWS Firehose. Splitting a Cloud limitation along the S2S-versus-HEC line is the exact shape of an exam trap; here the feature is simply unavailable both ways.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:true},
 /* --- Index Management --- */
 {exam:"cloudadmin",cat:"c2index",q:"Legal requires that six weeks of records containing customer PII be permanently purged from an index on your Splunk Cloud Platform stack — not merely hidden from search results. Which approach does Splunk document for Splunk Cloud Platform?",o:["Run a search isolating the events and pipe it to delete as a user holding the can_delete role.","Stop forwarding to the index, set searchable retention to 1 day, then wait 24 to 48 hours.","Open a support case asking Splunk to run the clean command against that index from the CLI.","Switch the index to DDSS so the affected buckets are exported and then dropped from storage."],a:[1],e:"The <code>delete</code> command reference has a Splunk Cloud-specific section: because CLI access is unavailable, you permanently remove data <b>using retention policies</b> — stop forwarding to the index, set Searchable time (days) to 1 in Settings > Indexes, wait 24 to 48 hours for background processes to delete the data, then restore your original retention and resume forwarding. The trap is option 0. <code>delete</code> is real, and <code>can_delete</code> is the right role for it, but the docs are blunt: delete only marks events as unsearchable and <b>does not reclaim disk space</b>, so it does not satisfy a purge requirement. Option 2 fails because <code>clean</code> is a CLI command, and Cloud has no CLI. Option 3 is wrong because DDSS exports the data to your own bucket rather than destroying it.",d:"https://help.splunk.com/en/splunk-cloud-platform/search/search-reference/10.5.2605/search-commands/delete",hard:true},
 {exam:"cloudadmin",cat:"c2index",q:"You are creating an events index for a source that ingests roughly 10 GB per day and must remain searchable for 90 days. Which configuration follows the documented Splunk Cloud Platform best practice for retention settings?",o:["Set Max raw data size to 900 GB and Searchable retention to 90 days so the two limits align.","Set Max raw data size to 0 and Searchable retention to 0, and let Splunk size the index for you.","Set Max raw data size to 450 GB and Searchable retention to 180 days to absorb ingest bursts.","Set Max raw data size to 1800 GB and Searchable retention to 90 days, so age expires data."],a:[3],e:"Each index has two independent expiry triggers — Max raw data size and Searchable retention (days) — and whichever is hit first starts dropping the oldest buckets. Splunk's documented best practice is to set the size limit <b>significantly larger</b> than normal total ingestion so that age, not size, governs expiry. The doc uses this exact worked example: 10 GB/day over 90 days is about 900 GB, so set Max raw data size to 1800 GB (double) and Searchable retention to 90. The closest distractor is option 0, which is the intuitive-looking 'size the index to exactly what you expect' answer. It fails because any burst of unanticipated data pushes the index past 900 GB and starts deleting buckets before day 90, silently shortening your retention. Note also that both settings are per-index, and internal indexes beginning with an underscore have retention you cannot modify.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-your-indexes-and-data-in-splunk-cloud-platform/manage-splunk-cloud-platform-indexes",hard:true},
 {exam:"cloudadmin",cat:"c2index",q:"An auditor needs four days of archived data from a DDAA-enabled index brought back so it can be searched. You submit the restore from Settings > Indexes. What should you expect once the job succeeds?",o:["Restored data is searchable for 30 days, sits outside index retention, and uses no license.","Restored data is searchable until you clear it, and it counts toward the index max raw size.","Restored data is searchable for 90 days and is re-indexed, so it consumes daily ingest volume.","Restored data replaces the archived copy, so you must re-archive it when the audit finishes."],a:[0],e:"DDAA restores are temporary copies. The docs state restored data is searchable for <b>30 days</b> (a period that cannot be shortened or extended), that it <b>exists outside the constraints of retention periods and size limits</b> for the index, and that restoring archived data <b>does not count against the indexing license volume</b>. Restores typically complete within 24 hours. The closest distractor is option 1: you genuinely can and should clear restored data manually when finished, so half of it is true — but the 30-day auto-expiry still applies, and restored data does not count toward the index's max raw data size. Option 3 is wrong because Splunk never moves or deletes the original archived copy, which is what makes an accidental delete impossible.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-your-indexes-and-data-in-splunk-cloud-platform/store-expired-splunk-cloud-platform-data-in-a-splunk-managed-archive",hard:true},
 /* --- User Authentication & Roles --- */
 {exam:"cloudadmin",cat:"c3auth",q:"A user holds two roles: <code>restricted_ops</code>, whose allowed index list is only <code>web</code>, and <code>analyst</code>, whose allowed index list is <code>*</code>. The security team expected the narrower role to constrain them, but the user can search the <code>pci</code> index. Why?",o:["Because srchIndexesDefault on analyst silently overrides srchIndexesAllowed on restricted_ops.","Because the analyst role was assigned more recently, and the newest assignment wins a conflict.","Because roles only grant access, so the user gets the broadest access that any held role provides.","Because a wildcard index list always overrides an explicit index list, whichever role happens to hold it."],a:[2],e:"The docs state the governing principle: roles never take access away. A user holding multiple roles receives the most permissive access each role can provide, and the documented example is exactly this scenario &mdash; a narrow role limited to one index plus a broad role permitting all indexes yields access to all indexes. The remedy is to build a single custom role combining the capabilities you want with the index restriction you want, and not to assign the permissive role at all. The closest distractor is option 3: it reaches the right outcome by the wrong mechanism, implying wildcards are special. They are not &mdash; two explicit lists would union the same way. <strong>Exam trap:</strong> the one setting that <em>does</em> subtract is <code>srchIndexesDisallowed</code>, which takes precedence over <code>srchIndexesAllowed</code>, <code>srchIndexesDefault</code>, and <code>deleteIndexesAllowed</code>. Search filters also combine restrictively across roles, unlike index access.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/manage-users-and-security/10.5.2605/manage-splunk-platform-users-and-roles/about-configuring-role-based-user-access",hard:true},
 {exam:"cloudadmin",cat:"c3auth",q:"A role sets <code>srchIndexesAllowed = main;web;pci</code> and <code>srchIndexesDefault = main</code>. A user holding only this role runs <code>sourcetype=firewall</code> with no index term and sees no results from the <code>web</code> index. What explains this?",o:["srchIndexesAllowed only takes effect once srchIndexesDefault names the same index list.","srchIndexesDefault sets what is searched when no index is given, and it names only main.","srchIndexesDisallowed overrides both of the other settings, and it lists web for this role.","srchIndexesAllowed applies only to indexes named explicitly by the role's search filter term."],a:[1],e:"The two settings answer different questions. <code>srchIndexesAllowed</code> is the list of indexes the role <em>may</em> search; <code>srchIndexesDefault</code> is the list actually searched when the user supplies no index term. Here <code>web</code> is permitted but not defaulted, so <code>index=web sourcetype=firewall</code> would return results while the bare search will not. The closest distractor is option 2 &mdash; <code>srchIndexesDisallowed</code> is real and genuinely does take precedence over the other index settings, but nothing in the stem sets it. <strong>Exam trap:</strong> a user reporting \"my data is missing\" when they can in fact reach the index on demand is almost always a defaults problem, not a permissions problem. Also note the wildcard rule: <code>*</code> in these lists does not match internal indexes; use <code>_*</code> for those, and the wildcard cannot span both groups at once.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.2/configuration-file-reference/10.2.7-configuration-file-reference/authorize.conf",hard:true},
 {exam:"cloudadmin",cat:"c3auth",q:"Which authentication scheme documented for the Splunk platform is available on Splunk Enterprise but <strong>not</strong> on Splunk Cloud Platform?",o:["Security Assertion Markup Language single sign-on with a SAML 2.0 identity provider.","Lightweight Directory Access Protocol authentication against your existing directory.","Native Splunk authentication, which takes precedence over any external auth scheme.","The scripted authentication API, used to reach outside systems like RADIUS or PAM."],a:[3],e:"The platform's authentication scheme table marks Native, LDAP, and SAML as available on <em>all</em> platform types, while the scripted authentication API and multi-factor authentication (Duo, RSA) are listed as Splunk Enterprise only. The closest distractor is option 1, and it is the one people get wrong: LDAP <strong>is</strong> supported on Splunk Cloud Platform and is configured through Splunk Web. <strong>Exam trap:</strong> the real Cloud delta is not \"SAML instead of LDAP\" &mdash; it is <em>where you configure it</em>. On Splunk Enterprise you may use Splunk Web or edit <code>authentication.conf</code> directly; on Splunk Cloud Platform you must use Splunk Web (or ACS), because configurations cannot be edited outside Splunk Web. One more testable fact: native authentication always runs first, and LDAP is only attempted when the failure is due to a nonexistent local account.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/manage-users-and-security/10.5.2605/manage-splunk-platform-users-and-roles/about-user-authentication",hard:true},
 {exam:"cloudadmin",cat:"c3auth",q:"SAML SSO is configured on a Splunk Cloud stack. An sc_admin needs to grant one contractor access to a Splunk role without granting it to everyone in that contractor's identity provider group. What does the Splunk platform support here?",o:["Nothing user-level; access comes from mapping IdP groups to roles, so add them to one.","Map the individual IdP user directly to a Splunk role on the SAML Groups page in Settings.","Create a native Splunk user with the same name, which SAML then matches on at login time.","Add the user to the role's search filter, which SAML evaluates before the group mapping."],a:[0],e:"The docs are unambiguous: mapping groups on the IdP to Splunk roles is the <em>only</em> way to give IdP users access. You cannot grant access to an individual IdP user unless you create a group on the IdP for that user or add them to an existing one. So the correct move is an IdP-side group, then map it. The closest distractor is option 1, which describes the right page doing the wrong thing &mdash; the SAML Groups page maps <em>groups</em> to roles, and you can map several groups to one role, but never a bare user. <strong>Exam trap:</strong> role assignment for SSO users lives on the IdP side, not in Splunk's Users page. Two related facts worth carrying in: with Azure you must map on group ID (UUID) rather than group name, and Splunk Cloud requires an IdP that signs SAML messages with SHA-256.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/manage-users-and-security/10.5.2605/use-saml-as-an-authentication-scheme-for-single-sign-on/map-groups-on-a-saml-identity-provider-to-splunk-roles",hard:true},
 {exam:"cloudadmin",cat:"c3auth",q:"An sc_admin decides that users holding the built-in <code>power</code> role on their Splunk Cloud stack should no longer be able to schedule searches. What is the recommended way to achieve this?",o:["Edit power in Splunk Web and clear that capability from the role's capability list.","Edit authorize.conf in system/local on the search head to remove the capability.","Leave power alone and build a custom role that grants only what these users need.","Ask Splunk Support to strip it, since sc_admin cannot edit any predefined role."],a:[2],e:"Splunk's documented guidance is to never edit predefined roles to remove capabilities, and it gives the reason: the <code>sc_admin</code> role does not have enough permission to restore some capabilities once removed. Instead, create custom roles that inherit from the predefined ones and edit those. The closest distractor is option 0 &mdash; Splunk Web will physically let an sc_admin do this, which is exactly why it is dangerous rather than merely invalid. <strong>Exam trap:</strong> option 1 is the Splunk Enterprise answer and is impossible on Cloud, where you cannot edit configurations outside Splunk Web. Remember too that inheritance only adds: a custom role inheriting from <code>power</code> keeps every capability <code>power</code> has, and inherited capabilities appear greyed out and cannot be deselected &mdash; so inherit from a narrower role such as <code>user</code>, not from the role you are trying to trim.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/manage-users-and-security/10.5.2605/manage-splunk-platform-users-and-roles/create-and-manage-roles-with-splunk-web",hard:true},
 /* --- Configuration Files --- */
 {exam:"cloudadmin",cat:"c4conf",q:"On a Splunk Enterprise instance, the same index-time setting for <code>[my_sourcetype]</code> is defined in both <code>etc/system/local/props.conf</code> and <code>etc/apps/myapp/local/props.conf</code>, with different values. Which value takes effect?",o:["The system/local copy, which is the highest priority directory in the global context.","The app local copy, since app directories always override the system directories.","The system/default copy, because default directories are read last and therefore win.","Neither, because conflicting index-time settings are ignored until the conflict is fixed."],a:[0],e:"Index-time settings are evaluated in the <strong>global</strong> context, where the documented priority runs: <code>system/local</code> &rarr; app <code>local</code> directories &rarr; app <code>default</code> directories &rarr; <code>system/default</code>. Splunk merges all copies and, on a conflict, keeps the value from the highest-priority location. The closest distractor is option 1, and it is the trap: in the <strong>app/user</strong> context the order is inverted &mdash; user directories, then the current app, then other apps, and <code>system/local</code> drops near the bottom. <strong>Exam trap:</strong> <code>props.conf</code> is unusual in having <em>both</em> contexts. Splunk evaluates it globally at index time and in app/user context at search time, so the same file can resolve differently depending on which kind of setting you are asking about. Option 2 inverts the rule: <code>default</code> directories are the fallback of last resort, not the winner.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-file-precedence",hard:true},
 {exam:"cloudadmin",cat:"c4conf",q:"Two installed apps each set the same index-time setting in their own <code>local/props.conf</code>. One app directory is named <code>Alpha_TA</code>, the other <code>beta_TA</code>. The setting appears nowhere in <code>system/local</code>. Which app's value wins?",o:["beta_TA, because in the global context app directories are read in reverse order.","beta_TA, because lowercase directory names sort after uppercase ones and are read last.","Alpha_TA, because the global context reads app directories in lexicographical order.","Neither reliably, because ordering among app directories is not deterministic here."],a:[2],e:"In the <strong>global</strong> context Splunk orders app directories lexicographically, and the docs state the rule plainly: files in an apps directory named \"A\" have higher priority than one named \"B\". Because lexicographical order follows UTF-8/ASCII, every app starting with an uppercase letter outranks every app starting with a lowercase letter &mdash; \"Z\" beats \"a\". So <code>Alpha_TA</code> wins. The closest distractor is option 0, and it is a real rule applied to the wrong context: in the <strong>app/user</strong> context Splunk uses <em>reverse</em>-lexicographical order, so there <code>beta_TA</code> genuinely would win. <strong>Exam trap:</strong> one direction for global (index-time), the opposite for app/user (search-time). Also worth knowing: numbered directories sort ahead of alphabetical ones in the global context, and are compared lexicographically, so <code>myapp10</code> outranks <code>myapp2</code>.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-file-precedence",hard:true},
 {exam:"cloudadmin",cat:"c4conf",q:"Before shipping a private app, a Splunk Cloud admin wants to confirm that an <code>inputs.conf</code> file contains no invalid settings. They have no shell or filesystem access to the stack. What does Splunk Cloud Platform provide for this?",o:["The splunk btool inputs list command, run from a terminal session on the search head.","A btool REST API endpoint that validates a posted configuration file and returns errors.","A btool tab under Settings > Monitoring Console that merges and displays the conf layers.","The btool CLI, which Splunk enables for the sc_admin role on request through a support case."],a:[1],e:"Splunk Cloud Platform exposes a btool REST API as the documented alternative to the btool CLI available in Splunk Enterprise. You POST the file to <code>/services/properties/&lt;config_file&gt;?validate=true</code> and get back <code>validation_status: success</code> (HTTP 200) or <code>failed</code> (HTTP 400) with an <code>errors</code> array naming the offending stanza, line, and key. The closest distractor is option 0 &mdash; <code>splunk cmd btool &lt;conf&gt; list</code> is exactly right on Splunk Enterprise, where it simulates the merge and reports settings in precedence order. <strong>Exam trap:</strong> the SPLK-1005 blueprint still tests config-file concepts, but the Cloud delta is <em>how you inspect them</em>. No CLI, no filesystem &mdash; you use the REST API, Splunk Web, or ACS. There is no btool page in the Monitoring Console, and the CLI is not unlocked by support case.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/configure-your-splunk-cloud-platform-deployment/validating-configurations-using-the-btool-rest-api",hard:true},
 {exam:"cloudadmin",cat:"c4conf",q:"Which of the following is performed at <strong>search time</strong> rather than at index time?",o:["Assigning the source type that gets stored with each event as it is written to disk.","Breaking the incoming stream into individual events using the configured line breaker.","Extracting the timestamp from the event text and writing it into the _time field.","Adding fields to events from a lookup table as the search collects matching events."],a:[3],e:"The documented search-time list includes addition of fields from lookups, search-time field extraction, field aliasing, calculated fields, tagging, event type matching, field filters, and source type <em>renaming</em>. The index-time list includes default field extraction (host, source, sourcetype, timestamp), source type customization, event timestamping, event linebreaking, and custom index-time field extraction. The closest distractor is option 0, because of a genuinely fine distinction: source type <em>assignment</em> is index-time and cannot be changed after the fact without re-indexing, while source type <em>renaming</em> is a search-time operation. <strong>Exam trap:</strong> the practical rule is that anything baked into the event on disk is index-time; anything layered on as the search runs is search-time. Splunk's guidance is to keep knowledge-building at search time, since index-time field extraction slows both indexing and later searches.",d:"https://help.splunk.com/en/splunk-enterprise/administer/manage-indexers-and-indexer-clusters/10.4/indexing-overview/index-time-versus-search-time",hard:true},
 {exam:"cloudadmin",cat:"c4conf",q:"On a Victoria Experience stack, an sc_admin self-service installs a private app containing <code>props.conf</code>, <code>transforms.conf</code>, <code>savedsearches.conf</code>, and dashboards. Where does the app's content get deployed?",o:["Every conf file goes to search heads, while only indexing-related ones reach indexers.","Every conf file goes to indexers, while only search-time ones also go to the search heads.","Only props.conf and transforms.conf are installed, and those go only to the indexing tier.","Files go only to search heads, so index-time settings need a separate support request."],a:[0],e:"The docs state it directly: all app configuration files are installed on search heads, while only configuration files with indexing-related functionality are installed on indexers &mdash; specifically naming <code>indexes.conf</code>, <code>props.conf</code>, and <code>transforms.conf</code>. This matters because index-time work (masking, <code>nullQueue</code> filtering, index routing) only takes effect on the tier that parses the data. The closest distractor is option 3, which describes the older, more restrictive reality some admins still assume &mdash; but self-service private app install on Victoria reaches the indexers without a support case. <strong>Exam trap:</strong> the app must pass AppInspect with 0 Failures, 0 Errors, and 0 Manual Checks before self-service install is allowed; any Manual Checks send you to Splunk Support. Note also that on Victoria all app files land on <em>all</em> search heads, which is why globally shared assets need unique names.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/manage-private-apps-on-your-splunk-cloud-platform-deployment",hard:true},
 /* --- Getting Data In --- */
 {exam:"cloudadmin",cat:"c5gdi",q:"A team must discard debug-level events and route the remainder to different destinations based on field values inside each event, before any of it reaches Splunk Cloud Platform. The collection host currently runs a universal forwarder. What has to change?",o:["Deploy a heavy forwarder, because per-event filtering and event routing need a parsing forwarder","Enable indexAndForward on the universal forwarder so that it parses each event before sending it on","Set sendCookedData to false on the universal forwarder so that events are examined before sending","Add a props.conf transform to the universal forwarder so it breaks and evaluates each event locally"],a:[0],e:"The forwarder comparison table is explicit: per-event filtering and event routing are both No for the universal forwarder and Yes for the heavy forwarder, because the universal forwarder does not parse data except in limited cases and therefore cannot make decisions based on event contents. The closest distractor is <code>indexAndForward</code>, a genuine outputs.conf setting that is heavy-forwarder-only, but it controls local indexing, not parsing or routing. <code>sendCookedData = false</code> moves in the wrong direction entirely: it sends raw, unaltered bytes, which strips structure rather than adding it. The trap is assuming that any forwarder can filter if you just give it the right conf file.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/introduction-to-forwarding/types-of-forwarders",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"An admin installs a universal forwarder on a Linux host and downloads <code>splunkclouduf.spl</code> from Apps &gt; Universal Forwarder in Splunk Cloud Platform. What is the documented way to put that package into service on the forwarder?",o:["Copy it into $SPLUNK_HOME/etc/apps and run splunk reload deploy-server, then confirm it with btool","Extract it into $SPLUNK_HOME/etc/system/local so its outputs.conf merges into the system layer","Run splunk install app /tmp/splunkclouduf.spl, supply the credentials, then restart the forwarder","Import it from Settings then Forwarding and receiving in Splunk Web on the forwarder, and restart"],a:[2],e:"The documented procedure is to copy the file to a temporary directory and run <code>$SPLUNK_HOME/bin/splunk install app /tmp/splunkclouduf.spl</code>. When prompted, you supply the forwarder user name and password, look for the message that the app installed, and then run <code>./splunk restart</code>. The closest distractor untars the package into <code>etc/system/local</code>, which is a common instinct because the package contains an outputs.conf, but the credentials package is an app and must be installed as one. The last option is impossible for a different reason worth remembering: the universal forwarder does not expose Splunk Web at all.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/universal-forwarder-manual/10.4/configure-the-universal-forwarder/enable-a-receiver-for-the-splunk-cloud-platform",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"An admin has to get the Splunk Cloud forwarder credentials onto 400 universal forwarders. Following the documented deployment server method, where is the credentials package placed before it is unpacked and installed?",o:["$SPLUNK_HOME/etc/deployment-apps/ on the deployment server, which then distributes it to its clients","$SPLUNK_HOME/etc/apps/ on each individual universal forwarder, copied out by a file management tool","$SPLUNK_HOME/etc/master-apps/ on the deployment server, which then pushes the bundle to its clients","$SPLUNK_HOME/etc/shcluster/apps/ on the deployment server, which then replicates it to all its clients"],a:[0],e:"The documented flow is: download the package, copy it to a temporary folder, move <code>splunkclouduf.spl</code> to <code>$SPLUNK_HOME/etc/deployment-apps/</code> on the deployment server, unpack it with <code>tar xvf splunkclouduf.spl</code>, install it with <code>splunk install app</code>, and restart the deployment server. The distractors are all real Splunk directories used by other tiers, which is what makes them plausible: <code>master-apps</code> is where a cluster manager stages the indexer cluster bundle, and <code>shcluster/apps</code> is the deployer location for a search head cluster. The trap is knowing the file name but not which management tier owns the directory.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/universal-forwarder-manual/10.4/configure-the-universal-forwarder/enable-a-receiver-for-the-splunk-cloud-platform",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"In outputs.conf, at which stanza level must <code>indexAndForward</code> be configured, and on which kind of forwarder does it actually do anything?",o:["In a target group stanza, and only on a universal forwarder that has a local index already defined","In the global [tcpout] stanza, and only on a heavy forwarder, as a universal forwarder cannot index","In a [tcpout-server://] stanza, and on any forwarder that has also opened a receiving port of its own","In the global [tcpout] stanza, and on any forwarder, since every forwarder keeps a local copy of data"],a:[1],e:"The documentation states that several attributes can be set only at the global level, and names <code>defaultGroup</code> and <code>indexAndForward</code> specifically. Its default is false, and the attribute table adds the note that it is only available for heavy forwarders because a universal forwarder cannot index locally. The closest distractor gets the stanza level right but the forwarder type wrong, which is the harder half of the question. Local indexing on a heavy forwarder is off by default and must be deliberately enabled, either through Forwarding defaults in Splunk Web or in outputs.conf.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/configure-forwarders/configure-forwarding-with-outputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"An outputs.conf contains <code>[tcpout] defaultGroup=g1,g2</code>, then <code>[tcpout:g1] server=a:9997,b:9997</code>, then <code>[tcpout:g2] server=c:9997</code>. What does this forwarder actually do with its events?",o:["It sends every event to a, b, and c, because any server named anywhere receives the whole stream","It load balances across a, b, and c as one pool, because the two groups are merged at run time","It sends a full copy to g1 and another full copy to g2, load balancing inside g1 across a and b","It sends only to g1, and fails over to g2 once every receiver listed inside g1 becomes unreachable"],a:[2],e:"Two different topologies are in play. Multiple receivers inside one target group means automatic load balancing: at a specified interval the forwarder switches the data stream to another indexer in that group at random, and if one indexer is down it immediately switches to another. Multiple target groups named in <code>defaultGroup</code> means data cloning, where the forwarder sends a full duplicate stream to each group. The closest distractor describes failover between groups, which is intuitive but wrong: every group listed in <code>defaultGroup</code> receives its own complete copy, so this configuration doubles the ingest volume. The trap is that the group boundary, not the server list, decides cloning versus balancing. Worth knowing for the exam: there is no <code>autoLB</code> on/off setting, because the spec states that automatic load balancing is the only way to forward data and round-robin is no longer supported. What you tune is <code>autoLBFrequency</code>, which defaults to 30 seconds, and <code>autoLBVolume</code>, which defaults to 0 and takes priority when it is reached first. The docs also warn against putting an external load balancer between forwarders and receivers.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/configure-forwarders/configure-forwarding-with-outputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"A load-balanced forwarder has <code>useACK = true</code> in its tcpout stanza. One receiving indexer stops responding and never acknowledges a block of data that the forwarder already sent. What does the forwarder do?",o:["It discards the unacknowledged block once the write timeout passes and logs a dropped event warning","It holds that block in memory indefinitely, because an unacknowledged block can never be released","It spools the block into a local persistent queue on disk and replays it once the indexer returns","It closes the connection after the read timeout and resends the block to the next free indexer"],a:[3],e:"With indexer acknowledgment on, the forwarder sends data in blocks of roughly 64 KB and keeps a copy of each block in its wait queue until the receiver confirms the block was written. The documentation states that if the forwarder does not get acknowledgment for a block within 300 seconds by default it closes the connection, and that if the forwarder is set up for auto load balancing it opens a connection to the next indexer in the group and sends the data there. Each resend writes a possible-duplication warning to splunkd.log, which is why acknowledgment protects against loss but not against duplicates. Two traps live here: the wait is governed by <code>readTimeout</code>, since there is no <code>ackTimeout</code> setting in outputs.conf; and <code>useACK</code> defaults to false, so turning it on raises the output queue from 500 KB to 7 MB and creates a wait queue three times that size, a change that only takes effect after a forwarder restart.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/perform-advanced-configuration/protect-against-loss-of-in-flight-data",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"An admin sets <code>autoCertRotation = true</code> on a universal forwarder whose tcpout channel reaches Splunk Cloud Platform by way of an intermediate forwarder. The certificates from the credentials package still are not renewing. What explains this?",o:["Renewal only begins once less than 10 percent of the certificate validity period is still remaining","Automatic renewal is unsupported when the output channel goes through an intermediate forwarder","The setting has to be placed in the global [tcpout] stanza rather than in a named output group stanza","The forwarder must also be running as a deployment client that is pointed at the same Cloud stack"],a:[1],e:"The prerequisites list is strict: the environment must be hosted in commercial AWS outside several named regions, Splunk Cloud Platform must be 9.2.2406 or higher, the forwarder must be 9.3.0 or higher, and there must be at least one output group sending to Splunk Cloud Platform. It then states that you must connect the forwarders directly, and that there is no support for automatic certificate rotation when you connect forwarding output channels to either intermediate forwarders or Edge Processor. The closest distractor inverts the documented stanza guidance: the setting belongs in the named tcpout stanza for the Cloud connection, and there is explicitly no support for setting it at the global [tcpout] level when the forwarder sends to multiple receivers. The 10 percent figure is wrong too, since a certificate becomes eligible once 50 percent or less of its validity period remains.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/universal-forwarder-manual/10.4/configure-the-universal-forwarder/enable-a-receiver-for-the-splunk-cloud-platform",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"A forwarder reaches Splunk Cloud Platform over a TLS connection. To save bandwidth an admin sets <code>compressed = true</code> in outputs.conf, but the throughput numbers do not change. Which statement matches current documented behavior?",o:["The compressed setting takes effect only once the same value is also configured on the receiving side","The compressed setting already defaults to true, so declaring it explicitly can never alter throughput","The compressed setting governs non-TLS forwarding; TLS compression uses useClientSSLCompression","The compressed setting applies to the wait queue alone, so it does nothing unless useACK is enabled"],a:[2],e:"The outputs.conf specification defines <code>compressed</code> as controlling compressed communication for forwarding that does not use TLS/SSL, and its default is false. The spec example is blunt about it: this setting applies to non-SSL forwarding only, and for SSL forwarding with compression Splunk software uses the <code>useClientSSLCompression</code> setting, whose default is true. Server-side compression in splunkd is already on by default, and the Splunk Cloud service details note that forwarders compress data when sending over TLS, generally between 8:1 and 12:1. The closest distractor, requiring a matching value on the receiver, was the older guidance and is now explicitly reversed: the current spec states that if you set compressed to true you do not need to also set it in inputs.conf on the receiver.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.2-configuration-file-reference/outputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"An admin opens Settings then Forwarding and receiving on a Splunk Cloud Platform search head, intending to add a receiving port on 9997 so forwarders can connect. The option does not work. What is actually true?",o:["The Splunk Cloud Platform receiving port is on by default and cannot be configured by the customer","The receiving port must be requested from Splunk Support first, after which it appears in Splunk Web","Receiving is configured per index on Splunk Cloud Platform, under Settings and then Indexes instead","Receiving has to be enabled by running splunk enable listen 9997 from the Splunk Cloud command line"],a:[0],e:"The documentation states that a Splunk Cloud Platform instance receiving port is configured and enabled by default, and that it is not possible to configure receiving on a Splunk Cloud Platform instance using Splunk Web, editing a .conf file, or using the command line. What the customer does own is the network side: the onboarding guide lists permission to open port 9997 in your firewalls as an administrator prerequisite. The closest distractor is the support-ticket answer, which is how several other Cloud tasks genuinely work, but receiving is not one of them. The trap is applying the Splunk Enterprise workflow, where enabling a receiver on the indexer really is step one.",d:"https://help.splunk.com/en/data-management/forward-data/forwarding-and-receiving-data/10.5.2605/deploy-heavy-and-light-forwarders/enable-a-receiver",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"An admin needs to confirm which of 200 universal forwarders are currently connecting to a Splunk Cloud Platform stack, and which have gone quiet. Which approach is purpose-built for that check?",o:["Run splunk btool outputs list --debug on each forwarder to confirm its merged tcpout settings","Open Settings and then Forwarder Management on the Cloud search head and review the client list","Run splunk display listen on each forwarder to confirm that its receiving port is established","Open the Cloud Monitoring Console Forwarders Deployment dashboard and filter on their status"],a:[3],e:"The Cloud Monitoring Console Forwarders: Deployment dashboard lists every forwarder with its type, version, Status, and Last Connected to Indexers, and the Status filter accepts All, Active, or Missing. The scheduled search behind it looks back 15 minutes, so a forwarder that has not connected inside that window shows as Missing, and the SIM Alert for missing forwarders runs on the same 15 minute cadence. The closest distractor is Forwarder Management, which is genuinely a forwarder-facing screen but belongs to the deployment server: it tells you which clients phoned home for configuration, not whether their data is landing in the indexers. For a single host, <code>splunk list forward-server</code> shows what that forwarder is configured to send to, and a search such as <code>index=_internal host=&lt;forwarder&gt;</code> confirms its data arrived; btool only prints merged configuration, and the docs warn its report does not necessarily represent what is loaded in memory.",d:"https://help.splunk.com/en/data-management/splunk-cloud-platform-admin-manual/10.5.2605/monitor-your-splunk-cloud-platform-deployment/use-the-forwarder-dashboards/monitor-forwarder-deployments",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"A team forwards CSV files to Splunk Cloud Platform using a source type that relies on <code>INDEXED_EXTRACTIONS</code>. Where do the parsing, extraction, and filtering settings for that source type have to be configured?",o:["On the Splunk Cloud Platform indexers, applied to the props.conf layer through a Support request","On the forwarder that collects the data, because that is the tier where the extraction is performed","On the Splunk Cloud Platform search head, since indexed extractions are resolved by SPL at search time","On the forwarder and on the indexers both, so that the two copies of the settings never drift apart"],a:[1],e:"The forwarding documentation states directly that when you forward structured data, meaning data with source types that use the INDEXED_EXTRACTIONS feature, you must perform any parsing, extraction, or filtering changes on the forwarder, not the indexer. This is also the documented exception to the rule that universal forwarders do not parse: the universal forwarder does not identify, examine, or tag individual events except when you configure it to parse files with structured data such as comma-separated value files. The closest distractor sends the settings to the indexers, which is where props.conf changes normally live in a Splunk Enterprise deployment. The trap is that structured data inverts the usual tier assignment.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/deploy-heavy-and-light-forwarders/heavy-and-light-forwarder-capabilities",hard:true},
 {exam:"cloudadmin",cat:"c5gdi",q:"A universal forwarder must feed a non-Splunk TCP listener that expects the bytes exactly as they appeared in the source file. Which change produces that, and what does the forwarder send by default?",o:["Set indexAndForward to false; by default a universal forwarder sends fully parsed cooked data","Set compressed to false; by default a universal forwarder sends raw data that has been compressed","Set useACK to false; by default a universal forwarder sends acknowledged and fully parsed data","Set sendCookedData to false; by default a universal forwarder sends unparsed but cooked data"],a:[3],e:"Forwarders transmit raw, unparsed, or parsed data. Parsed and unparsed are both called cooked, and the documentation says that by default forwarders send cooked data, with universal forwarders sending unparsed data and heavy forwarders sending parsed data. To send raw data instead, set <code>sendCookedData=false</code> in outputs.conf. With raw data the forwarder sends the bytes unaltered over a TCP stream and does not convert them into the Splunk communications format, which is exactly what a non-Splunk listener needs. The closest distractor mislabels the universal forwarder's default as fully parsed, which is the heavy forwarder's behavior; a universal forwarder never emits parsed data.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/introduction-to-forwarding/types-of-forwarders",hard:true},
 /* --- Forwarder Management --- */
 {exam:"cloudadmin",cat:"c6fwdmgmt",q:"You manage roughly 900 universal forwarders that send data to Splunk Cloud Platform, and you want one place to push app, input, and outputs changes to them. Where does the deployment server live in this architecture?",o:["On the Splunk Cloud search head tier, reached through Settings > Forwarder management in Web.","On an instance you host on premises or in your own cloud account, not inside the Cloud stack.","On the Inputs Data Manager, which Splunk provisions as the deployment server for Classic stacks.","On the Splunk Cloud indexer tier, after Support enables the deployment server role for you."],a:[1],e:"For Splunk Cloud Platform the deployment server is <b>customer-hosted</b>. The Cloud GDI docs define it as a Splunk Enterprise instance acting as a centralized configuration manager that is 'hosted on your premises or your Cloud environment (such as AWS or Azure)', and the Forward data topic states plainly that the in-product Forward data page is not available on Splunk Cloud Platform — instead you install your own deployment server. The trap is option 0: forwarder management is a real Splunk Web page, just not one that exists in your Cloud stack, so a Splunk Enterprise habit transfers incorrectly. Option 2 is the strongest distractor for Classic customers because the IDM is Splunk-hosted infrastructure, but the IDM is only for scripted and modular inputs and is never a deployment server. In practice you install the Splunk Cloud forwarder credentials app on that deployment server and deploy it out as a deployment app.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/get-data-into-splunk-cloud-platform/introduction-to-getting-data-in",hard:true},
 {exam:"cloudadmin",cat:"c6fwdmgmt",q:"A newly installed universal forwarder never appears in forwarder management. You have confirmed the deployment server is reachable from that host on port 8089. Which <code>deploymentclient.conf</code> problem is the most likely cause?",o:["The clientName setting is required and must be unique, or the server will drop the client.","The repositoryLocation setting still points to $SPLUNK_HOME/etc/apps rather than the app repo.","The targetUri in [target-broker:deploymentServer] is absent, or splunkd was not restarted.","The phoneHomeIntervalInSecs value of 60 defers the first check-in until a manual reload."],a:[2],e:"A client only phones home when it knows where to phone. The spec file requires the <code>[deployment-client]</code> stanza to exist, and the deployment server address is set as <code>targetUri = scheme://host:mgmtPort</code> under <code>[target-broker:deploymentServer]</code>. The other half of this question is the one people forget: <b>you must restart splunkd for deploymentclient.conf changes to take effect</b>, so a correct file that was never applied looks identical to a missing file. The closest distractor is option 0 — <code>clientName</code> is a genuine setting that takes precedence over DNS names for allow-list matching, but it has a default of 'deploymentClient' and is optional, so its absence never prevents registration. Option 3 inverts reality: 60 seconds is simply the default phone-home interval, and it is the client, not a server reload, that initiates contact.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.2/configuration-file-reference/10.2.7-configuration-file-reference/deploymentclient.conf",hard:true},
 {exam:"cloudadmin",cat:"c6fwdmgmt",q:"You copy a new app directory onto your deployment server and reference it from an existing server class by editing <code>serverclass.conf</code>. Clients keep phoning home but never receive the app. What did you most likely miss?",o:["The app must sit in $SPLUNK_HOME/etc/deployment-apps and you must run splunk reload deploy-server.","The app must sit in $SPLUNK_HOME/etc/apps and be enabled from the Apps page before it deploys.","The app must sit in $SPLUNK_HOME/etc/master-apps and be pushed with the apply cluster-bundle command.","The app must sit in $SPLUNK_HOME/var/run and be registered with a stateOnClient setting of noop."],a:[0],e:"Two separate requirements, and this question tests both. Deployment apps live in the repository location, whose documented default is <code>$SPLUNK_HOME/etc/deployment-apps</code> on the deployment server; a <code>[serverClass:X:app:Y]</code> stanza maps an app that must already exist there. And the serverclass.conf spec states you must <b>reload the deployment server configuration (<code>splunk reload deploy-server</code>) or restart splunkd</b> for changes to take effect. The closest distractor is option 1, which confuses the two ends of the pipeline: <code>$SPLUNK_HOME/etc/apps</code> is the <i>target</i> location on the deployment client (the <code>targetRepositoryLocation</code> default), not the staging directory on the server. Option 2 borrows real indexer-clustering mechanics — <code>master-apps</code> and <code>apply cluster-bundle</code> are legitimate, but for cluster peers, not deployment clients.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/9.4/configuration-file-reference/9.4.14-configuration-file-reference/serverclass.conf",hard:true},
 {exam:"cloudadmin",cat:"c6fwdmgmt",q:"A deployment app containing a new <code>inputs.conf</code> monitor stanza downloads successfully to your forwarders, but the files it should be watching are never read. The server class has <code>issueReload = false</code> and <code>restartSplunkd = false</code>. Why is nothing happening?",o:["stateOnClient defaults to disabled, so the app installs in a disabled state on every client.","With both settings false the client refuses the download and retries at the next phone home.","restartIfNeeded defaults to true, so the client waits for a manual restart before reloading.","With both settings false the downloaded app is never activated on the deployment client."],a:[3],e:"The serverclass.conf spec includes an explicit behavior table for these two settings. With <code>issueReload = false</code> and <code>restartSplunkd = false</code>, <b>the downloaded apps are not activated</b> — the files land on disk, but splunkd neither reloads nor restarts, so the new input never starts. The usual fix is <code>issueReload = true</code> plus <code>restartIfNeeded = true</code> for a best-effort reload that falls back to a restart. The closest distractor is option 0, and it is tempting because <code>stateOnClient</code> really does control whether an app arrives enabled or disabled — but its default is <b>enabled</b>, not disabled, so it is not what is blocking you here. Option 2 also inverts a real default: <code>restartIfNeeded</code> defaults to false, and it only does anything when <code>issueReload</code> is true.",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/9.4/configuration-file-reference/9.4.14-configuration-file-reference/serverclass.conf",hard:true},
 /* --- Monitor Inputs --- */
 {exam:"cloudadmin",cat:"c7monitor",q:"A universal forwarder uses the stanza <code>[monitor:///var/log/.../*.log]</code>. Files such as <code>/var/log/nginx/access.log</code> arrive in Splunk Cloud, but <code>/var/log/syslog.log</code>, which sits directly in <code>/var/log/</code>, never appears. Why is that one file excluded?",o:["An ellipsis followed by a path separator matches only subfolders, so top level files are skipped","The asterisk wildcard stops matching at the first period, so any name holding a dot before .log is skipped","The recursive setting defaults to false, so this input only ever reads the files in the top /var/log/ folder","Splunk turns the trailing *.log into a deny list entry, which removes every file ending in .log from input"],a:[0],e:"The ellipsis (<code>...</code>) searches recursively through subdirectories, and the docs state that when you specify a folder separator after it, it does not match the first folder level, only subfolders. The tailing logic for <code>/var/log/.../*.log</code> becomes <code>^\\/var\\/log/.*/[^/]*\\.log$</code>, so <code>/var/log/subfolder/test.log</code> matches but <code>/var/log/test.log</code> does not. The documented fix is <code>[monitor:///var/log/]</code> with <code>whitelist=\\.log$</code> and <code>recursive=true</code>. The closest distractor blames <code>recursive</code>, but <code>recursive</code> defaults to true and would only ever remove subdirectory files, which is the opposite of the symptom. The trap is assuming <code>...</code> means zero or more directory levels; it means one or more.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/specify-input-paths-with-wildcards",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A forwarder monitors <code>/opt/app/logs/</code>, where every file opens with the same 400-byte XML banner and logrotate renames the files nightly. Only one file per directory is ever indexed. Which change fixes the collision without causing rotated files to be read a second time?",o:["Set crcSalt to the literal SOURCE token so the full path of each file is folded into its CRC value","Set initCrcLength above 400 so the fingerprint is calculated on bytes that come after the shared banner","Set alwaysOpenFile = 1 so the forwarder opens each file instead of trusting its size and modification time","Set followTail = 1 so the forwarder skips past the shared banner and starts reading at the current end of file"],a:[1],e:"By default the monitor processor fingerprints only the first 256 bytes of a file, so files with identical headers produce identical CRCs and get treated as already seen. <code>initCrcLength</code> raises how many bytes are read before the file is identified; it must be longer than any static header, and its documented range is 256 to 1048576 bytes. <code>crcSalt = &lt;SOURCE&gt;</code> is the closest distractor because it also guarantees unique CRCs, but the docs explicitly caution against it for rotated or renamed logs: the renamed file gets a new path, so a new CRC, so the whole file is indexed again. The trap is that <code>crcSalt</code> and <code>initCrcLength</code> solve the same symptom by different means, and only one of them survives log rotation.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/how-the-splunk-platform-handles-log-file-rotation",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A monitor stanza contains both <code>whitelist = \\.log$</code> and <code>blacklist = archive</code>. The file <code>/var/log/archive/app.log</code> matches both regular expressions. What does the forwarder do with that file?",o:["It monitors the file, because the allow list is evaluated last and therefore overrides the deny list","It monitors the file until the next restart, when the deny list is re-evaluated and the file is dropped","It does not monitor the file, since a deny list match takes precedence over an allow list match","It refuses to load the stanza and writes a configuration error, leaving both list settings inactive"],a:[2],e:"The inputs.conf specification is explicit: if a file matches the regular expressions in both the deny list and allow list settings, the file is NOT monitored, because deny lists take precedence over allow lists. The closest distractor is the idea that evaluation order inside the stanza decides the outcome; it does not, and moving the lines around changes nothing. The trap is treating these like firewall rules where last-match-wins. Note also that <code>whitelist</code> and <code>blacklist</code> match against the file path, not just the file name.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.2/configuration-file-reference/10.2.7-configuration-file-reference/inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A monitor stanza sets <code>ignoreOlderThan = 7d</code>. A dormant log file went untouched for three weeks and was skipped. The application then resumes writing to that same file, but none of the new events reach Splunk Cloud. What explains this behavior?",o:["ignoreOlderThan is compared against index time, so the new events are written with an out-of-range timestamp","The forwarder rechecks ignored files once every 24 hours, so the new events show up after a one day delay","The file needs a fresh fingerprint before it can be read again, which only the crcSalt setting can provide","Files put on the ignore list stay there until the forwarder restarts or its inputs are reconfigured"],a:[3],e:"The specification states that files on the ignore list are not checked again until the Splunk platform restarts or the file monitoring subsystem is reconfigured, and that this is true even if the file becomes newer again at a later time. That is why the docs warn not to select a time window that files you want to read could reach in age, even temporarily. The closest distractor is the 24-hour recheck, which is a real documented behavior but a different one: it applies to a monitored path that does not exist when the forwarder starts, not to a file already on the ignore list. The trap is assuming <code>ignoreOlderThan</code> is a self-healing rolling window.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.2/configuration-file-reference/10.2.7-configuration-file-reference/inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"An admin needs a forwarder to start reading a 40 GB application log at its current end rather than ingesting all of the existing history. Which statement about <code>followTail = 1</code> is accurate?",o:["It applies only the first time the forwarder sees a file, and Splunk advises against leaving it on","It applies on every forwarder restart, so the input always resumes reading at the current end of the file","It truncates the monitored file each time the forwarder reads it, so history can never be ingested twice","It is designed for rolling log files, where the name of the file is changed by the system as the file ages"],a:[0],e:"With <code>followTail = 1</code> monitoring begins at the end of the file, much like <code>tail -f</code>, but the setting applies only to files the first time the platform attempts to monitor them; after that the platform tracks the file with its internal file position records. The spec calls this an advanced setting, says to contact Splunk Support before using it, and states plainly not to leave it enabled in an ongoing fashion. The closest distractor claims it re-applies at every restart, which would make the setting safe to leave on permanently; it does not, which is exactly why the documented workflow is enable, wait, disable, restart. The spec also says explicitly not to use it for rolling log files, which rules out the last option.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.2/configuration-file-reference/10.2.7-configuration-file-reference/inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A forwarder monitors <code>/mnt/logs/</code>, where each server writes into its own subdirectory, for example <code>/mnt/logs/server01/app.log</code>. The stanza sets <code>host_segment = 3</code>. What host value do events from that file receive?",o:["mnt, because segment counting begins with the leading forward slash of the absolute source path","logs, because the name of the file itself is always counted as the final segment of the path","app.log, because host_segment counts path segments backward from the end of the source path","server01, because it is the third forward-slash separated segment of the monitored source path"],a:[3],e:"<code>host_segment = N</code> sets the Nth forward-slash separated segment of the path as the host. The documented example uses <code>host_segment = 3</code> against <code>/logs/servers/host08/abc.txt</code> and yields <code>host08</code>, so <code>/mnt/logs/server01/app.log</code> yields <code>server01</code>. The closest distractor counts the leading slash as a segment, which is the single most common miscount. Two extra facts the exam likes: on Windows the drive letter and colon do not count as a segment, and if <code>host_regex</code> and <code>host_segment</code> are both set in the same stanza, <code>host_regex</code> is ignored.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-host-values/set-a-default-host-for-a-file-or-directory-input",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A Splunk Cloud admin must load a directory of historical archive files one time and have the forwarder remove each file from disk after it is indexed. Which stanza does this?",o:["[batch:///opt/archive/*] with the setting move_policy = sinkhole included in the stanza","[monitor:///opt/archive/*] with the setting followTail = 1 included in the stanza","[batch:///opt/archive/*] with the setting move_policy = destructive included in the stanza","[monitor:///opt/archive/*] with the setting ignoreOlderThan = 1d included in the stanza"],a:[0],e:"The batch input is a one-time, destructive input: it reads and indexes the files, then deletes them immediately. The spec states that the stanza must include <code>move_policy = sinkhole</code>, and that this setting is required so an administrator has to explicitly declare that the data should be deleted after being read. The closest distractor uses <code>move_policy = destructive</code>, which reads like the right idea but is not a valid value; <code>sinkhole</code> is the literal string the parser expects. The trap is that <code>monitor</code> never deletes anything, so no combination of monitor settings satisfies the requirement.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories-with-inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A Splunk Cloud Platform administrator is asked to ingest an entire directory of application logs from an on-premises Linux host. Working only in Splunk Web on the Cloud search head, the admin cannot find a way to configure it. What is the reason?",o:["Splunk Cloud Platform can ingest directories only through HTTP Event Collector token based inputs","Directory monitoring on Splunk Cloud Platform needs the sc_admin role plus a Splunk Support request","Monitor inputs must run on a universal or heavy forwarder; Splunk Web only uploads a single file","Splunk Web can monitor directories, but only after the destination index has been created as an event index"],a:[2],e:"The documentation states that to monitor files and directories in Splunk Cloud Platform you must use a universal or a heavy forwarder in nearly all cases: you perform the data collection on the forwarder and then send the data to the Splunk Cloud Platform instance. The one exception is the Upload option, and it handles a single file at a time. The closest distractor is the support-ticket answer, which is genuinely how some Cloud tasks work, but no ticket enables search-head-side directory monitoring. The trap is carrying over Splunk Enterprise habits, where Settings > Data Inputs > Files and Directories really can define a monitor input locally.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"On a heavy forwarder, inputs.conf sets <code>sourcetype = app:custom</code> in the monitor stanza, while props.conf on the same instance has <code>[source::/opt/app/...]</code> with <code>sourcetype = app:generic</code>. Which source type is applied to the events, and why?",o:["app:generic, because props.conf is applied during the parsing phase, which runs after the input phase","app:custom, because an explicit source type set on the data input outranks one based on the source","app:generic, because a stanza scoped to a single data source is more specific than a whole-input rule","app:custom, because props.conf source stanzas only apply to data received over a network based input"],a:[1],e:"The documented order of precedence for source type assignment is: explicit specification based on the data input, then explicit specification based on the data source, then rule-based recognition, then automatic matching, then delayed rule-based association, then automatic learning. The platform stops at the first method that produces an answer, so the inputs.conf assignment wins. The closest distractor argues from pipeline order, which sounds authoritative because props.conf really is evaluated during parsing, but the precedence list is the rule the exam tests. The trap is confusing when a setting is evaluated with how the platform ranks competing source type assignments.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-source-types/why-source-types-matter",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"A universal forwarder on a Windows IIS server is missing new lines in the W3SVC logs because Windows does not refresh the modification time while a file is held open. Which setting addresses this, and what is the documented trade-off?",o:["time_before_close = 0, which closes files immediately and can break apart multiline events at the boundary","alwaysOpenFile = 1, which opens each file to check it and can increase load and slow down indexing","followSymlink = false, which stops link traversal and can hide files that live behind mounted volumes","multiline_event_extra_waittime = true, which holds back event delimiters and can back up the input queue"],a:[1],e:"<code>alwaysOpenFile</code> makes the input open a file to check whether it has already been indexed, skipping the modification time and size checks. The spec says it is only useful for files that do not update modification time or size, that it is only known to be needed when monitoring files on Windows, mostly for Internet Information Server logs, and that setting it to 1 can increase load and slow indexing, so use it only as a last resort. Its default is 0. The closest distractor, <code>time_before_close</code>, is a real monitor setting but it governs how long the input waits after end-of-file before closing a handle, which does not help when the modification time never changes in the first place.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.2/configuration-file-reference/10.2.7-configuration-file-reference/inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"An admin adds <code>whitelist = *.log</code> to a monitor stanza intending to collect only log files. After a restart the forwarder ingests nothing at all from that directory. What is wrong with the entry?",o:["Allow lists accept only Splunk wildcards, so the asterisk has to be written as an ellipsis instead","Allow lists compare against file names only, so a pattern carrying an extension can never match a path","Allow lists must be anchored, so every pattern has to open with a caret and close with a dollar sign","Allow lists are regular expressions, so a leading asterisk is an invalid quantifier that fails"],a:[3],e:"The stanza path and the allow list use two different matching languages. Input path specifications do not use regular expressions but Splunk-specific wildcards (<code>...</code> and <code>*</code>), while allow lists and deny lists are defined with standard PCRE syntax and are matched against the file path. A correct entry here is <code>whitelist = \\.log$</code>. Splunk itself demonstrates the conversion: <code>[monitor:///foo/bar*.log]</code> is translated internally into <code>[monitor:///foo/]</code> with <code>whitelist = bar[^/]*\\.log$</code>. The closest distractor inverts the rule and claims the allow list wants wildcards, which is precisely the confusion being tested.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/specify-input-paths-with-wildcards",hard:true},
 {exam:"cloudadmin",cat:"c7monitor",q:"When the monitoring processor picks up a file it has not opened before, what does it do first to decide whether that file has already been read?",o:["It hashes the entire file and compares the result against every entry held in the tracking database","It compares the size and modification time of the file against the values recorded in splunkd.log","It reads the first 256 bytes, hashes them into a CRC, and looks that CRC up in a database","It reads the last 256 bytes of the file and compares that CRC against the stored seek address value"],a:[2],e:"The documented flow is that the monitoring processor picks up a new file, reads the first 256 bytes, and hashes that data into a beginning and ending cyclic redundancy check that acts as a fingerprint of the file content. It looks that CRC up in a database of beginning CRCs it has seen before; a hit returns the seekAddress, which is how many bytes of the known file were already read, plus the seekCRC, a fingerprint of the data at that location. The closest distractor proposes hashing the whole file, which would be correct behavior for a checksum tool but would make rolling-log detection prohibitively expensive; the 256-byte window is exactly why duplicate-CRC problems exist and why <code>initCrcLength</code> exists to fix them.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/how-the-splunk-platform-handles-log-file-rotation",hard:true},
 /* --- Network & Other Inputs --- */
 {exam:"cloudadmin",cat:"c8network",q:"A universal forwarder collects Cisco ASA syslog on a [udp://514] input. During nightly traffic bursts Splunk Cloud is missing thousands of events, and splunkd shows the input queue blocking. Which change directly addresses the loss?",o:["Raise queueSize to 10MB on the UDP stanza so the in-memory queue absorbs the whole burst","Set _rcvbuf to 0 on the UDP stanza so the operating system stops capping the receive buffer","Set persistentQueueSize on the UDP stanza so queue overflow spills to files on local disk","Set no_priority_stripping to true so the input stops discarding part of each syslog packet"],a:[2],e:"Forwarders keep a 500 KB in-memory input queue by default. When a UDP input fills it, the datagrams simply drop off the queue and are gone. persistentQueueSize writes the overflow to disk, and persistent queues are explicitly supported for TCP, UDP, FIFO, scripted, Windows Event Log and HEC token inputs. The trap is queueSize: it is a real setting, but the docs say to configure it only if you have also configured persistentQueueSize, and a bigger memory queue still drops data once it fills. _rcvbuf = 0 does not mean unlimited either; a value of 0 or negative is ignored.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/improve-the-data-input-process/use-persistent-queues-to-help-prevent-data-loss",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"You must onboard 400 network devices that emit syslog over UDP into Splunk Cloud Platform, which cannot listen on a raw network port itself. Which design matches Splunk's documented best practice?",o:["Land the syslog on a syslog server such as syslog-ng or Splunk Connect for Syslog, then forward it","Point every device straight at the Splunk Cloud stack over UDP 514 after opening the port by ticket","Send every device to one heavy forwarder UDP input and set that input to write to the index queue","Have each device post to a HEC token over UDP so that no forwarder tier is needed for the devices"],a:[0],e:"The Getting Data In manual states plainly that for syslog the best practice is to use a syslog server such as syslog-ng or Splunk Connect for Syslog, and that TCP is preferred over UDP whenever possible. Splunk Cloud accepts network data only from a universal or heavy forwarder holding the credentials package, so option 1 is impossible regardless of tickets. The closest trap is option 3: HEC is a real ingestion path and is the right answer for many questions, but it speaks HTTP and HTTPS only, never UDP.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-network-sources/get-data-from-tcp-and-udp-ports",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"An admin adds [tcp://9997] and [udp://514] to a forwarder and sets nothing else. Events from the TCP input show resolved host names, while events from the UDP input show bare IP addresses. What explains the difference?",o:["The UDP input ignores connection_host completely and always falls back to the sender IP address","TCP inputs resolve the host through the DNS cache, which UDP packets are unable to support","The tcp stanza defaults connection_host to ip, while the udp stanza defaults it to dns","The tcp stanza defaults connection_host to dns, while the udp stanza defaults it to ip"],a:[3],e:"The defaults differ by stanza type, which is exactly what this objective tests. In inputs.conf, [tcp://] defaults connection_host to dns, while [udp://] and [splunktcp://] both default it to ip. Nothing is broken here; the admin simply inherited two different defaults. The near-miss option inverts them. Note one extra wrinkle for UDP syslog: if the input carries a source type whose transform rewrites the host field, such as sourcetype=syslog, that transform takes precedence over connection_host entirely.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/9.4/configuration-file-reference/9.4.14-configuration-file-reference/inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"A scripted input defined as [script:///opt/company/collect_api.sh] never produces data and splunkd logs nothing from it, yet the script is executable and runs correctly from a shell. What is the most likely cause?",o:["The interval value must be a cron string, because plain second counts only work for modular inputs","The script sits outside the allowed directories, so the input may not launch from that path","The passAuth setting is absent, so splunkd declines to spawn any script that is not authenticated","The start_by_shell setting defaults to false on Linux, so a shell script never gets an interpreter"],a:[1],e:"A scripted input command must live in $SPLUNK_HOME/etc/system/bin, $SPLUNK_HOME/etc/apps/<app>/bin, or $SPLUNK_HOME/bin/scripts. An arbitrary path such as /opt/company is refused. If the real script must live elsewhere, use a pointer file ending in .path that sits in one of those directories and contains a single line naming the external command. The closest trap is start_by_shell, which is a genuine setting but defaults to true on nix and false only on Windows, so it would not block a Linux shell script.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-other-kinds-of-data-in/get-data-from-apis-and-other-remote-data-interfaces-through-scripted-inputs",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"A Python scripted input must call the local Splunk REST API with a session key, and it must run exactly once every time the forwarder starts. Which pair of inputs.conf settings accomplishes both requirements?",o:["passAuth names a Splunk user so a token arrives on stdin, and interval is set to -1","passAuth names a Splunk user so a token arrives on stdin, and interval is set to 0","python.version picks the runtime so a token is generated, and interval is set to -1","start_by_shell is true so the token is exported to the environment, and interval is 0"],a:[0],e:"passAuth takes a username; the platform mints an auth token for that user and hands it to the script on the stdin data stream, which is how scripted inputs authenticate to REST without embedded credentials. For scheduling, interval = -1 runs the input once at start-up, while interval = 0 is the opposite extreme, forcing the script to run continuously and restart the instant it exits. Swapping 0 and -1 is the classic trap. python.version only picks an interpreter and generates no token; start_by_shell only controls whether the OS shell wraps the command.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/9.4/configuration-file-reference/9.4.14-configuration-file-reference/inputs.conf",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"You need Windows performance counters from 30 remote servers, and corporate policy forbids installing any agent on them. Which collection method matches the documented behaviour of the Windows inputs?",o:["Define perfmon stanzas on the indexer tier and name each remote server inside the object setting","Define WinEventLog stanzas on a collector host, because that input also carries performance data","Define perfmon stanzas on a collector host and list the remote servers in the instances setting","Define WMI inputs in wmi.conf on one Windows collector host that polls the 30 servers remotely"],a:[3],e:"The inputs.conf specification is explicit that the perfmon stanza is for local systems only, and that to define performance monitor inputs for remote machines you use wmi.conf. The same local-only note applies to WinEventLog. Splunk still prefers a universal forwarder wherever code can be installed, but WMI is the documented fallback for exactly this no-agent constraint. The trap is the instances setting: it lists Performance Monitor counter instances, such as individual disks or processes, never remote hostnames.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-windows-data/considerations-for-deciding-how-to-monitor-remote-windows-data",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"A developer on a Splunk Cloud Platform stack hosted on AWS posts JSON to https://mystack.splunkcloud.com:8088/services/collector/event using a valid, enabled token, and the request never reaches HEC. What must change?",o:["Move to port 443 and switch to the services/collector/raw endpoint, which Splunk Cloud requires","Add the http-inputs- prefix to the host name and send to port 443 rather than to port 8088","Add the http-inputs- prefix to the host name but keep port 8088, which Splunk Cloud reserves","Move to port 443 and carry the token in an X-Splunk-Request-Channel header instead of the URL"],a:[1],e:"On Splunk Cloud the HEC URI is protocol://http-inputs-HOST.splunkcloud.com:PORT/ENDPOINT for AWS, and the docs warn that without that prefix the data cannot reach HEC at all. The port is 443 by default on Splunk Cloud Platform instances; 8088 is the Splunk Enterprise default and is used on Splunk Cloud only for free trials. The closest distractor keeps the prefix but keeps 8088 as well, which is why both halves of this answer matter. Stacks on GCP, Azure and AWS GovCloud use a dotted http-inputs. prefix instead. The /event endpoint was already correct for JSON.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/get-data-in/10.5.2605/get-data-with-http-event-collector/set-up-and-use-http-event-collector-in-splunk-web",hard:true},
 {exam:"cloudadmin",cat:"c8network",q:"A HEC client uses a token with indexer acknowledgment enabled. Every POST returns HTTP 200 with an ackID, but each status query to the ack endpoint comes back with the error 'Data channel is missing'. What is wrong?",o:["The client queries services/collector/event, but ack status is only served by the raw endpoint","The client reuses one ackID for every request, and each ackID must be a newly generated GUID","The client omits the X-Splunk-Request-Channel value that it used when it sent the event data","The client polls too soon, and the ack endpoint rejects any query made within 10 seconds"],a:[2],e:"With indexer acknowledgment active, the client must present a matching channel identifier both when sending data and when querying status; omitting it produces precisely this error message. The channel is a client-generated GUID, sent either as the X-Splunk-Request-Channel header or as a channel query parameter, and status is polled at /services/collector/ack. The trap is confusing the two identifiers: the channel is the GUID you invent, while the ackID is a small integer HEC returns to you. Remember also that on Splunk Cloud, HEC indexer acknowledgment is supported only for Amazon Data Firehose.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-with-http-event-collector/about-http-event-collector-indexer-acknowledgment",hard:true},
 /* --- Fine-tuning Inputs --- */
 {exam:"cloudadmin",cat:"c9finetune",q:"An admin adds LINE_BREAKER and TIME_FORMAT to props.conf on a universal forwarder that ships data to Splunk Cloud. After a restart the events break and timestamp exactly as they did before. Why?",o:["A universal forwarder never reads props.conf at all, so only inputs.conf settings are honoured","Those are parsing-phase settings, and a universal forwarder does not perform the parsing phase","SHOULD_LINEMERGE must be set to true on the forwarder before LINE_BREAKER can take any effect","Those settings apply only to monitor inputs, and this forwarder is reading a network port input"],a:[1],e:"Knowing which phase owns a setting tells you which component to configure. LINE_BREAKER, TRUNCATE, SHOULD_LINEMERGE, the line-merging family, and TIME_PREFIX, TIME_FORMAT, DATETIME_CONFIG and TZ are all parsing-phase settings, and parsing runs on an indexer or a heavy forwarder, not a universal forwarder. On Splunk Cloud the fix is to parse on a heavy forwarder or an Edge Processor. The trap is option 0, a widespread myth: a universal forwarder does read props.conf, and honours the input-phase settings there such as CHARSET, NO_BINARY_CHECK, PREFIX_SOURCETYPE and sourcetype.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-parameters-and-the-data-pipeline",hard:true},
 {exam:"cloudadmin",cat:"c9finetune",q:"On a heavy forwarder, inputs.conf sets sourcetype = weblogic on a monitor input for /var/log/app, while props.conf contains a source stanza for that same path setting sourcetype = generic_single_line. Which value wins, and why?",o:["weblogic, because explicit assignment by input is evaluated ahead of assignment by source","generic_single_line, because props.conf is evaluated later and therefore overrides inputs.conf","generic_single_line, because a source stanza is more specific than an input-wide sourcetype","weblogic, because a props.conf source stanza can only rename source types, never assign them"],a:[0],e:"Source type assignment has its own documented order, and the platform stops at the first method that succeeds: explicit assignment by data input, then explicit assignment by data source, then rule-based recognition, then automatic matching, then delayed rules, then automatic learning. Because inputs.conf assigns by input, it is evaluated first and wins. The trap is generalising ordinary configuration-file precedence, where a more specific stanza usually beats a broader one; that rule governs which stanza applies within a file, not this cross-file source type ordering.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-source-types/why-source-types-matter",hard:true},
 {exam:"cloudadmin",cat:"c9finetune",q:"A Japanese application writes Shift-JIS log files. The events index, but non-ASCII characters appear in the raw text as escaped hex sequences. Which change fixes this, and where in the pipeline does the setting act?",o:["Set CHARSET to SHIFT-JIS in props.conf on the indexer tier; it acts during the parsing phase","Set NO_BINARY_CHECK to true in props.conf on the forwarder; it acts during the input phase","Set CHARSET to SHIFT-JIS in props.conf on the forwarder; it acts during the input phase","Set CHARSET to AUTO in inputs.conf on the input stanza; it acts before the input phase"],a:[2],e:"CHARSET is a props.conf setting that applies at input time, when the data is first read, so it belongs on whichever component owns the input. That is why a Splunk Cloud customer sets it on the forwarder rather than centrally. Splunk assumes UTF-8 by default on nix and AUTO on Windows, and when characters are not valid in the assumed encoding it escapes them as hex, which is the symptom described. The trap is option 0: the attribute name and value are right but the tier and phase are wrong. CHARSET = AUTO is legal, but it goes in props.conf, never inputs.conf.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-character-set-encoding",hard:true},
 {exam:"cloudadmin",cat:"c9finetune",q:"To 'save CPU' an admin adds queue = indexQueue to a TCP input on a heavy forwarder. Afterwards the line-breaking and timestamp rules defined for that source type stop applying to the data. What is the explanation?",o:["indexQueue suppresses index-time transforms only, so line breaking and timestamping still run","indexQueue is not a valid value, so the input silently reverts to system default event handling","indexQueue routes data to the aggregator alone, which skips transforms but keeps the timestamper","indexQueue sends the data straight to the index, bypassing props.conf and other parsing rules"],a:[3],e:"The queue setting on an input decides where the input processor deposits what it reads. The default is parsingQueue, which applies props.conf and the rest of the parsing rules. Setting indexQueue sends events directly into the index instead. The trap is assuming it is a narrow optimisation that only skips transforms: it bypasses the entire parsing pipeline, so line merging, timestamp extraction, index-time transforms and per-event routing are all lost at once. This is a fine-tuning decision made at the input, not a parsing setting.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-network-sources/get-data-from-tcp-and-udp-ports",hard:true},
 /* --- Parsing & Data Preview --- */
 {exam:"cloudadmin",cat:"c10parse",q:"Java stack traces arrive as one event per line. On the heavy forwarder an admin sets SHOULD_LINEMERGE = false together with a BREAK_ONLY_BEFORE regex that matches the leading date. Nothing changes. Why?",o:["BREAK_ONLY_BEFORE is a line-merging setting, ignored while SHOULD_LINEMERGE is false","BREAK_ONLY_BEFORE takes effect only once MAX_EVENTS is raised above its default of 256 lines","BREAK_ONLY_BEFORE needs a capturing group in its regular expression to mark the event starts","BREAK_ONLY_BEFORE is a search-time setting and cannot influence how the platform builds events"],a:[0],e:"BREAK_ONLY_BEFORE, BREAK_ONLY_BEFORE_DATE, MUST_BREAK_AFTER, the MUST_NOT_BREAK settings and MAX_EVENTS all apply only when SHOULD_LINEMERGE is true. Turning line merging off and then configuring a merge rule cancels the very setting you added. There are two valid repairs: keep SHOULD_LINEMERGE = true and use BREAK_ONLY_BEFORE, or set SHOULD_LINEMERGE = false and write a LINE_BREAKER regex, which is the faster option because line merging is comparatively slow. The trap is option 2, since the capturing group is a LINE_BREAKER requirement, not a BREAK_ONLY_BEFORE one.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-event-line-breaking",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"An admin sets SHOULD_LINEMERGE = false and writes a LINE_BREAKER regular expression consisting of two literal newline pairs with no parentheses. Events do not break where expected. What does LINE_BREAKER require?",o:["A lookahead assertion, because the platform breaks at the position where the assertion matches","A capturing group, whose matched text is discarded and marks the boundary between two events","An anchor at the start of the line, because breaking is evaluated one raw line at a time","A named group called event, which the platform uses to label the start of every new event"],a:[1],e:"LINE_BREAKER must contain a capturing group. The start of the first capturing group is treated as the end of the previous event, the end of that group as the start of the next event, and the text the group matched is discarded, so it never appears in any event. The default value, a bracketed character class for carriage return and newline repeated one or more times, shows the required shape. Forgetting the parentheses is the single most common LINE_BREAKER mistake. For very large multiline events, also check LINE_BREAKER_LOOKBEHIND, which defaults to 100 characters of carryover between raw chunks.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-event-line-breaking",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"Large single-line JSON payloads are arriving cut short, and the shortened events carry an index-time field named meta::truncated. Which props.conf setting governs this behaviour, and what is its default value?",o:["MAX_EVENTS, which caps how much of a single event the platform keeps, defaulting to 256 lines","LINE_BREAKER_LOOKBEHIND, which caps raw chunk carryover, defaulting to 100 characters","MAX_TIMESTAMP_LOOKAHEAD, which caps how far parsing reads, defaulting to 128 characters","TRUNCATE, which caps the maximum line length, defaulting to 10000 bytes; use 0 to disable"],a:[3],e:"TRUNCATE sets the maximum line length in bytes and defaults to 10000. Lines longer than that are broken into further lines using LINE_BREAKER and TRUNCATE, and the platform stamps the result with meta::truncated, which is the fingerprint named in the scenario. Setting TRUNCATE = 0 disables truncation entirely, though the docs caution that very long lines are often a sign of garbage data. The closest trap is MAX_EVENTS: it also caps event size, but by line count during line merging, and it does not add meta::truncated.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-event-line-breaking",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"In what order does the Splunk platform attempt to assign a timestamp to an event during the parsing phase?",o:["File modification time, then a date in the source name, then TIME_FORMAT, then the current time","Advanced datetime.xml recognition, then TIME_FORMAT, then a date in the source name, then now","An explicit TIME_FORMAT, then automatic recognition, then source name or file time, then now","The current system time, unless a TIME_FORMAT matches, in which case the event text is used"],a:[2],e:"The documented precedence is: a time or date found using an explicit TIME_FORMAT; then automatic identification using the source type; then year inference for a date with no year; then a date found in the source or file name, provided the events carry a time; then, for file sources, the file modification time; then advanced recognition configured in datetime.xml; and only as a last resort the current system time at index. The trap is where datetime.xml sits. Many candidates assume the timestamp processor runs first, when in fact it is near the end of the list, after the props.conf-driven methods.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-timestamps/how-timestamp-assignment-works",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"Today is 26 May. Events whose text carries only '10 Apr' with no year element are all being stamped with today's date rather than with April. Which explanation fits the documented behaviour?",o:["The events fall outside MAX_DAYS_AGO, so the platform substitutes the current index time","Year inference produced next April, which exceeds MAX_DAYS_HENCE, so index time is used","TIME_PREFIX is unset, so the platform cannot find the timestamp and applies the current time","The platform never infers a year, so any timestamp lacking one always defaults to index time"],a:[1],e:"When a timestamp has no year, the platform infers one. With a base year known from previous events, day 100 for 10 April plus 4 is compared against day 147 for 26 May; because 104 is less than 147 the base year is incremented, producing a date next April. That is far beyond MAX_DAYS_HENCE, which defaults to only 2 days, so the extracted date is rejected and the platform falls back to the previous event's timestamp or to index time. Note that such events are not dropped. The trap is MAX_DAYS_AGO, which is real but defaults to 2000 days, nowhere near being triggered here.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-timestamps/how-timestamp-assignment-works",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"Each event carries a build date near its start and the real event time roughly 60 characters in, and Splunk keeps extracting the build date. Which configuration most reliably targets the correct timestamp?",o:["Set TIME_PREFIX to a regex just before the real time, then size MAX_TIMESTAMP_LOOKAHEAD","Set MAX_TIMESTAMP_LOOKAHEAD to 60 on its own, so the platform skips the first 60 characters","Set TIME_FORMAT on its own, since a strptime pattern matches anywhere and finds the later time","Set DATETIME_CONFIG to CURRENT, then repair the event time with an index-time field transform"],a:[0],e:"TIME_PREFIX is a regular expression that positions the scan; the timestamp algorithm looks only at text following the end of that first match, and it must match up to and including the character before the timestamp begins. MAX_TIMESTAMP_LOOKAHEAD, which defaults to 128 characters, is then applied from the position TIME_PREFIX established. The trap is option 1: lookahead does not skip characters, it only limits how far forward the scan may run, and used alone it still starts at the beginning of the event. Also remember that TIME_FORMAT with no TIME_PREFIX requires the timestamp at the very start of the event, or strptime fails.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-timestamps/configure-timestamp-recognition",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"props.conf on a heavy forwarder sets TZ = US/Eastern for a source type, but events still land at offsets that ignore it. Inspection shows the raw text of each event ends with a zone designator such as +0000. What explains this?",o:["TZ is valid only inside host stanzas, so a source type stanza cannot influence event time zones","TZ is a search-time setting, and it only changes how results are rendered for the current user","A time zone present in the raw event text takes precedence over the TZ setting in props.conf","The forwarder's own operating system time zone always overrides any TZ value in props.conf"],a:[2],e:"Time zone precedence runs: a zone found in the raw event text, such as UTC or an offset like -08:00; then TZ in props.conf where the event matches the host, source or source type; then the zone supplied by a forwarder when both ends are version 6.0 or later; and finally the zone of the indexing host. The events already declare +0000, so they win and TZ is never consulted. The trap is option 3, which inverts two rungs of the ladder: the forwarder-supplied zone sits below props.conf TZ, not above it. To reinterpret an ambiguous acronym in the text, use TZ_ALIAS, which affects only strings from event text.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-timestamps/specify-time-zones-for-timestamps",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"A scripted input emits multiline output with no timestamp anywhere in it. After an admin sets DATETIME_CONFIG = CURRENT, the events acquire sensible times but now merge together into unpredictable boundaries. Why?",o:["CURRENT forces SHOULD_LINEMERGE to true, so every line is appended onto the previous event","CURRENT is illegal in upper case, so the resulting parsing error leaves boundaries undefined","CURRENT moves line breaking into the indexing phase, where merge settings are not evaluated","CURRENT switches off timestamp identification, so the default BREAK_ONLY_BEFORE_DATE fails"],a:[3],e:"Both CURRENT and NONE explicitly disable timestamp identification, and the docs warn that the default event boundary detection, BREAK_ONLY_BEFORE_DATE = true, then has nothing to detect and may not behave as you want. The remedy the docs give is to control merging yourself with SHOULD_LINEMERGE together with the BREAK_ONLY and MUST_BREAK settings. Know the difference too: CURRENT stamps the current system time at index, while NONE uses time of receipt, which for file inputs means the file modification time. Option 1 inverts a real warning, since these values must be given in upper case.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-timestamps/configure-timestamp-recognition",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"On the Set Source Type page you choose a timestamp format in the Timestamps tab, then type a conflicting TIME_FORMAT value into the Advanced tab and click Apply. Which value does the preview use, and where can you see it?",o:["The Advanced tab value wins, and that change is not reflected back in the Timestamps tab","The Timestamps tab value wins, because those tab settings are applied after Advanced entries","Whichever value you supplied most recently wins, and both tabs then display that same value","Neither value is used, and the underlying source type default is applied to the preview run"],a:[0],e:"Data Preview combines settings in a fixed order, highest first: Advanced tab changes, then Event Breaks or Timestamps tab changes, then the settings of the underlying source type, then the system defaults for all source types. The documentation adds the detail that catches people out: after you edit the Advanced tab and return to the Event Breaks or Timestamps tabs, your Advanced changes are not visible there. The trap is trusting the friendly tabs as the record of truth, when the Advanced tab writes attribute and value pairs straight into props.conf and quietly outranks them.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/how-to-get-data-into-your-splunk-deployment/modify-event-processing",hard:true},
 {exam:"cloudadmin",cat:"c10parse",q:"Data Preview showed a new source type breaking and timestamping a sample file perfectly, so the admin saved it and applied it. The same data arriving on a forwarder's TCP input in production parses incorrectly. Which explanation is consistent with the documentation?",o:["Preview writes its settings back to the indexer and overwrote the production props.conf","Source type overrides apply to file and upload inputs, but never to network inputs","Preview samples only the first 1000 events, so a later format change stays hidden","Preview commits its events to a scratch index, and production applies its own rules"],a:[1],e:"The documentation states that source type overrides work only on file and directory monitoring inputs or files you upload, and that you cannot override the source type on a network input. Preview validates how a source type would parse a sample; it does not prove that the source type will ever be applied to a given input, nor that a parsing tier will see the settings, which on Splunk Cloud means a heavy forwarder. Preview also never commits events to any index, and some source types such as the Log to Metrics category cannot be previewed at all.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-source-types/override-automatic-source-type-assignment",hard:true},
 /* --- Manipulating Raw Data --- */
 {exam:"cloudadmin",cat:"c11rawdata",q:"A Splunk Cloud admin packages a private app whose <code>props.conf</code> contains:<br><code>[pci_gateway]</code><br><code>SEDCMD-mask = s/cc=\\d{12}(\\d{4})/cc=xxxxxxxxxxxx\\1/g</code><br>A teammate insists nothing will be masked until a stanza named <code>mask</code> is added to <code>transforms.conf</code>. Who is correct, and why?",o:["The teammate is right, since every props.conf class must resolve to a transforms.conf stanza.","The teammate is right, because SEDCMD hands its regex to a transform that sets DEST_KEY to _raw.","The admin is right, since SEDCMD acts on _raw directly and the class name is just a label.","The admin is right, because SEDCMD runs at search time and never consults index-time transforms."],a:[2],e:"<code>SEDCMD-&lt;class&gt;</code> is self-contained. The docs describe two separate anonymization methods: a sed script configured entirely in <code>props.conf</code>, or a regex transform that needs <em>both</em> <code>props.conf</code> and <code>transforms.conf</code>. The <code>-mask</code> clause exists only because the stem plus the clause form the class name; it is a label you choose, not a pointer to a stanza. The closest distractor is option 1 &mdash; it correctly describes how a <code>TRANSFORMS-</code> masking transform works (<code>REGEX</code> + <code>FORMAT</code> + <code>DEST_KEY = _raw</code>), but that is the <em>other</em> method. <strong>Exam trap:</strong> both settings live in <code>props.conf</code> and both take a <code>-&lt;class&gt;</code> suffix, which makes people assume both point at <code>transforms.conf</code>. Only <code>TRANSFORMS-</code> does. Option 3 fails on a second doc-stated fact: SEDCMD applies only to <code>_raw</code>, and only at index time.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/anonymize-data",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"You must substitute every lowercase <code>a</code>, <code>b</code>, and <code>c</code> in a source type's events with uppercase <code>A</code>, <code>B</code>, and <code>C</code> &mdash; a character-for-character swap, not a string replacement. Which entry does this?",o:["SEDCMD-case = y/abc/ABC/","SEDCMD-case = s/abc/ABC/","SEDCMD-case = y/abc/ABC/g","REPORT-case = y/abc/ABC/"],a:[0],e:"<code>SEDCMD</code> supports exactly two sed commands: replace, <code>s/&lt;regex&gt;/&lt;replacement&gt;/flags</code>, and character substitution, <code>y/&lt;string1&gt;/&lt;string2&gt;/</code>, which swaps each character in string1 for the character at the same position in string2. The docs give this precise example: <code>SEDCMD-abc = y/abc/ABC/</code>. The closest distractor is option 1: <code>s/abc/ABC/</code> is valid syntax, but it matches the literal three-character sequence <code>abc</code> and would leave a standalone <code>b</code> untouched &mdash; a different result entirely. <strong>Exam trap:</strong> <code>y///</code> takes no flags, so the trailing <code>g</code> in option 2 is invalid; <code>g</code> and numeric match selectors belong to <code>s///</code> only. Option 3 is doubly wrong: <code>REPORT-</code> is a search-time setting and takes transform stanza names, not sed scripts.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/anonymize-data",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"An index-time transform is defined as:<br><code>[mask_ssn]</code><br><code>REGEX = (.*)ssn=\\d{5}(\\d{4}.*)</code><br><code>DEST_KEY = _raw</code><br>and invoked from <code>props.conf</code> with <code>TRANSFORMS-mask = mask_ssn</code>. Events index successfully but SSNs are still fully visible. What is wrong?",o:["SOURCE_KEY must be set to _raw so the regular expression is applied to the raw event text.","WRITE_META must be set to true before the platform will write the match back into the event.","The regex needs a (?m) prefix, without which an index-time transform will never match.","FORMAT is missing, so nothing defines the replacement text that DEST_KEY writes back."],a:[3],e:"<code>DEST_KEY</code> says <em>where</em> to write; <code>FORMAT</code> says <em>what</em> to write. The spec is explicit: \"FORMAT is required for index-time extractions,\" using <code>$1</code>, <code>$2</code> and so on to reference capture groups. The fix is <code>FORMAT = $1ssn=xxxxx$2</code>. With no <code>FORMAT</code>, the index-time default is <code>&lt;stanza-name&gt;::$1</code>, which is not the masked event you wanted. The closest distractor is option 1: <code>WRITE_META = true</code> is genuinely required for index-time field extractions &mdash; but only for those writing to <code>_meta</code>, not for a <code>DEST_KEY = _raw</code> masking transform. <strong>Exam trap:</strong> candidates memorize <code>REGEX</code> + <code>DEST_KEY</code> as the masking pair and drop the middle term. <code>(?m)</code> (option 2) only matters for genuinely multiline events, and <code>SOURCE_KEY</code> already defaults to <code>_raw</code>.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/configuration-file-reference/10.4.2-configuration-file-reference/transforms.conf",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"Verbose debug events are consuming ingest license. You want matching events discarded before they are written to any index, so they never count against the license. Which <code>transforms.conf</code> setting pair accomplishes this?",o:["DEST_KEY = nullQueue and FORMAT = queue","DEST_KEY = queue and FORMAT = nullQueue","DEST_KEY = _raw and FORMAT = nullQueue","DEST_KEY = queue and FORMAT = indexQueue"],a:[1],e:"<code>queue</code> is the KEY (the destination attribute you are writing to); <code>nullQueue</code> is the VALUE you write into it. The documented pattern is <code>REGEX = &lt;pattern&gt;</code>, <code>DEST_KEY = queue</code>, <code>FORMAT = nullQueue</code>. The docs confirm the license effect directly: data filtered so that it never gets added to an index does not count toward indexing volume. The closest distractor is option 0, which has the right two words in the wrong slots &mdash; <code>nullQueue</code> is not a valid KEY name, so the transform silently fails. <strong>Exam trap:</strong> <code>queue</code>, <code>_raw</code>, <code>_MetaData:Index</code> and <code>_TCP_ROUTING</code> are all KEYs that go on the left of <code>DEST_KEY</code>; <code>nullQueue</code> and <code>indexQueue</code> are values. Option 3 is the opposite outcome &mdash; it explicitly keeps the events.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/perform-advanced-configuration/route-and-filter-data",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"You want to keep only sshd events from a source and discard everything else. <code>props.conf</code> reads <code>TRANSFORMS-keep = setparsing, setnull</code>, where <code>setparsing</code> matches sshd events to <code>indexQueue</code> and <code>setnull</code> matches everything to <code>nullQueue</code>. No events arrive at all. What fixes it?",o:["Reverse the list so setnull runs first, because transforms apply in the order listed.","Give setnull a lower priority value so setparsing wins the collision between the two.","Split them into TRANSFORMS-keep and TRANSFORMS-null so that each class runs on its own.","Change setnull to a RULESET, because RULESET stanzas are always evaluated after TRANSFORMS."],a:[0],e:"The <code>props.conf</code> spec states that a comma-separated <code>TRANSFORMS-</code> list is applied in list order. Here <code>setnull</code> runs last, matches every event with <code>REGEX = .</code>, and re-tags even the sshd events that <code>setparsing</code> had already routed to <code>indexQueue</code> &mdash; so everything is thrown away. Listing <code>setnull</code> first tags all events for <code>nullQueue</code>, then <code>setparsing</code> re-tags the sshd matches back to <code>indexQueue</code>. The closest distractor is option 1: <code>priority</code> is a real <code>props.conf</code> key, but it resolves collisions between competing <em>stanzas</em>, not the execution order of transforms inside one list. <strong>Exam trap:</strong> the keep-some / drop-rest pattern is counterintuitive &mdash; the catch-all null transform must come <em>first</em>, not last.",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/perform-advanced-configuration/route-and-filter-data",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"Events arriving under one source type must be split at index time, so that any event containing the string <code>Application</code> is written to a different index than the rest. Which <code>transforms.conf</code> line performs the redirect?",o:["DEST_KEY = MetaData:Index, with FORMAT naming the target index to use","DEST_KEY = _MetaData:Sourcetype, with FORMAT set to the index name","DEST_KEY = _MetaData:Index, with FORMAT set to the target index name","DEST_KEY = _INDEX_ROUTING, with FORMAT naming the target index to use"],a:[2],e:"The documented KEY for index redirection is <code>_MetaData:Index</code>, with a leading underscore. The spec's own example is <code>[AppRedirect] REGEX = (Application) / DEST_KEY = _MetaData:Index / FORMAT = Verbose</code>. The closest distractor is option 0 &mdash; and it is the single most common real-world error, because the sibling keys genuinely <em>do</em> drop the underscore: <code>MetaData:Host</code>, <code>MetaData:Source</code>, and <code>MetaData:Sourcetype</code> have no leading underscore, while <code>_MetaData:Index</code> does. <strong>Exam trap:</strong> the docs warn that KEY names are case-sensitive and must be used exactly as listed, so <code>MetaData:Index</code> is simply an unrecognized key and the transform does nothing. Note also that the host, source, and sourcetype keys need their values prefixed (<code>host::</code>, <code>source::</code>, <code>sourcetype::</code>) &mdash; the index key does not.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/configuration-file-reference/10.4.2-configuration-file-reference/transforms.conf",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"A session token must be stripped out of <code>_raw</code> <strong>before</strong> events are written to disk, using a transform stanza named <code>strip_token</code>. Which <code>props.conf</code> setting invokes that stanza correctly?",o:["REPORT-strip = strip_token, which invokes the stanza as events are returned by a search.","EXTRACT-strip = strip_token, which applies the stanza's regular expression to _raw.","SEDCMD-strip = strip_token, which runs the named transform against _raw at index time.","TRANSFORMS-strip = strip_token, which invokes the stanza during index-time processing."],a:[3],e:"<code>TRANSFORMS-&lt;class&gt;</code> is the index-time invocation; the spec describes it as creating indexed fields and performing index-time transformations, and it is what masking and routing transforms are attached to. The closest distractor is option 0: <code>REPORT-&lt;class&gt;</code> has near-identical syntax and also takes a comma-separated list of <code>transforms.conf</code> stanza names applied in list order &mdash; but it runs at <strong>search time</strong>, so the token would still be sitting on disk in the indexed event. <strong>Exam trap:</strong> if the requirement says \"before it is indexed,\" \"on disk,\" or \"so it never lands in the index,\" the answer is <code>TRANSFORMS</code>, never <code>REPORT</code>. <code>EXTRACT-</code> is search-time and takes an inline regex rather than a stanza name; <code>SEDCMD</code> takes a sed script, not a stanza name.",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/configuration-file-reference/10.4.2-configuration-file-reference/props.conf",hard:true},
 {exam:"cloudadmin",cat:"c11rawdata",q:"A regex transform masks card numbers correctly in most events from a source type, but on the same source type some events run past 6,000 characters, and in those events the card number arrives unmasked. What is the most likely cause?",o:["MAX_TIMESTAMP_LOOKAHEAD defaults to 128, which truncates the text the transform can see.","LOOKAHEAD defaults to 4096 characters, so the match never reaches the longer events.","TRUNCATE defaults to 10000 bytes and silently discards the tail of these longer events.","LOOKAHEAD defaults to 256 characters and must be raised for any index-time transform."],a:[1],e:"<code>LOOKAHEAD</code> in <code>transforms.conf</code> sets how many characters into an event the transform searches, and its default is 4096. The anonymization guidance is explicit: when you use a regex transform to mask data, set <code>LOOKAHEAD</code> to a number larger than your largest expected event, or anonymization can fail. At 6,000 characters, anything past position 4096 is never examined. The closest distractor is option 2 &mdash; <code>TRUNCATE</code> is real and its default really is 10000 bytes, but 6,000-character events are comfortably under that limit, so truncation is not the cause. <strong>Exam trap:</strong> this failure is partial and silent, so it reads like a bad regex. Note <code>MAX_TIMESTAMP_LOOKAHEAD</code> (default 128) is a different setting entirely &mdash; it constrains timestamp extraction, not transforms.",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/anonymize-data",hard:true},
 /* --- Apps --- */
 {exam:"cloudadmin",cat:"c12apps",q:"You upload an in-house private app on a Victoria Experience stack. The AppInspect report returns 0 failures, 0 errors, and 3 manual checks, and the app status shows Rejected. What is your next step?",o:["Re-upload the package with a higher version number so AppInspect skips the manual check phase.","Contact Splunk Support, because a manual check count above zero blocks self-service install.","Acknowledge the Splunk General Terms in the report, which clears manual checks and installs it.","Install it from the ACS API instead, since ACS bypasses the manual portion of app validation."],a:[1],e:"The bar for self-service private app installation is stated as a hard rule: the AppInspect validation report must show <b>0 Failures, 0 Errors, and 0 Manual Checks</b>. The docs repeat it in the report-review procedure — if the report shows a value greater than zero for Manual Checks, you <b>must contact Splunk Support</b> to install the app, because manual checks require review by the Splunk AppInspect team. The closest distractor is option 2, and it is a genuinely dangerous one: the Service Description does describe acknowledging the Splunk General Terms regarding the potential impact of unremedied issues, and the Approved status can be reached that way. But that path covers <i>known issues</i>, not manual checks. Option 3 fails because ACS runs the same validation pipeline — changing the interface does not change the vetting outcome.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/manage-private-apps-on-your-splunk-cloud-platform-deployment",hard:true},
 {exam:"cloudadmin",cat:"c12apps",q:"You are packaging a private app so it can be installed self-service on Splunk Cloud Platform. Which set of packaging requirements does Splunk document for private apps?",o:["Package as a .zip or .spl file up to 512 MB, and bundle any static dependencies inside it.","Package as a .tar.gz file of any size, and list static dependencies in app.conf for resolution.","Package as .spl, .tar, .tar.gz, or .tgz, keep it under 128 MB, and use dynamic dependencies.","Package as a .spl file up to 128 MB, and include the local directory so settings survive."],a:[2],e:"The private app creation checklist gives three concrete constraints: package the app in <b>.spl, .tar, .tar.gz, or .tgz</b> format, <b>limit the package size to 128 MB</b>, and ensure the package has <b>no static dependencies</b>, because Splunk Cloud Platform supports dynamic dependencies only. The closest distractor is option 3: 128 MB is the right number, and <code>.spl</code> is a valid format, which makes the option feel correct at a glance. It fails on the second clause — shipping a <code>local</code> directory is not the documented mechanism, and .spl is not the only accepted format. Two related facts worth carrying into the exam: apps must ship with data models unaccelerated to pass AppInspect, and lookup files inside an app are preserved rather than overwritten on upgrade in Victoria Experience.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/manage-private-apps-on-your-splunk-cloud-platform-deployment",hard:true},
 {exam:"cloudadmin",cat:"c12apps",q:"After you install version 2.0 of an in-house private app on your Splunk Cloud Platform stack, a dashboard breaks and your team wants version 1.9 back. What does Splunk document about downgrading an installed app?",o:["You cannot revert in place; uninstall the app, then upload the earlier version again.","Select the prior version from the version list on the Manage Apps page and click Install.","Rollback happens automatically when you reinstall the app from the in-product app browser.","Use the ACS apps endpoint with a version parameter, the supported rollback path in Cloud."],a:[0],e:"The private app documentation states it directly for both Experiences: if you want to downgrade to an earlier version of an app, you must <b>first uninstall the app, then upload the earlier version</b>. The app management docs reinforce it — after you update an app you cannot revert to an earlier version. The closest distractor is option 1, which describes something that genuinely exists in the neighborhood: on Classic Experience the Uploaded Apps table lets you click Install on an earlier package you previously uploaded, versus Update for a later one. But Victoria Experience does not even support downloading previously uploaded apps from the UI, and neither Experience offers a true in-place rollback. Plan accordingly: keep your own copy of the prior package before you upgrade, because Splunk Cloud will not hand it back to you.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/manage-private-apps-on-your-splunk-cloud-platform-deployment",hard:true},
 /* --- Cloud Support --- */
 {exam:"cloudadmin",cat:"c13support",q:"Users report that data from a group of Windows servers stopped arriving about an hour ago. Before you open a Splunk Cloud Platform support case, which self-triage step does Splunk documentation point you to?",o:["Check Settings > Indexes for the affected index and lower its searchable retention setting.","Check the deployment server logs under $SPLUNK_HOME/var/log on the Splunk Cloud indexers.","Check the CMC Forwarders: Deployment dashboard for instances with a status of Missing.","Check the ACS maintenance endpoint to confirm a Splunk window removed those forwarders."],a:[2],e:"Isolating the problem before contacting Support means proving whether the fault is on your side of the wire. The CMC <b>Forwarders: Deployment</b> dashboard reports each forwarder's Status as Active or Missing along with Last Connected to Indexers, and the docs specifically say to investigate any sudden spike of missing forwarders as a possible systemic failure. CMC also ships a preconfigured SIM Alert - Missing Forwarders that runs every 15 minutes. If the forwarders show Missing, the problem is in your environment, not the stack, and no case is warranted yet. The closest distractor is option 1: reading forwarder-side logs is exactly the right instinct on Splunk Enterprise, but you have no file system access to any Splunk Cloud tier, so those logs are unreachable. Pair CMC with searches against <code>index=_internal</code> for the same triage on the Cloud side.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/monitor-your-splunk-cloud-platform-deployment/use-the-forwarder-dashboards/monitor-forwarder-deployments",hard:true},
 {exam:"cloudadmin",cat:"c13support",q:"Your organization was not notified before a recent Splunk Cloud Platform maintenance window, and a colleague was then unable to open a support case about the impact. Which statement correctly describes Splunk Cloud Platform support contacts?",o:["Anyone holding sc_admin can open cases, and all sc_admin users receive maintenance notices.","Operational contacts open cases, while entitlement contacts receive the maintenance notices.","Splunk sends maintenance notices to every user in the stack, and any of them can open cases.","Only authorized contacts open cases, and operational contacts get the maintenance notices."],a:[3],e:"Two distinct contact lists, and the exam likes to swap them. <b>Authorized support contacts</b> — named in your Splunk support agreement, with one acting as Support portal administrator who can update the list — are the only people who can open and track cases. <b>Operational contacts</b> are the people notified when your environment undergoes maintenance or experiences a performance-impacting event, and keeping that list current is explicitly listed as a customer maintenance responsibility. The closest distractor is option 1, which names both real roles but reverses their jobs. Option 0 confuses platform RBAC with commercial entitlement: <code>sc_admin</code> governs what you can do inside the stack, not who Splunk will accept a case from. Cases are filed from the Support Portal (Get started > Create Case) or in Splunk Cloud via About > File a Bug.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/get-started-managing-splunk-cloud-platform/welcome-to-the-splunk-cloud-platform-admin-manual",hard:true},
 {exam:"cloudadmin",cat:"c13support",q:"On a Classic Experience stack you create a new index in Splunk Web so that a cloud add-on running on your IDM can write to it. The index exists and looks healthy, but no data ever lands in it. What does the documentation say you must do?",o:["Restart the IDM from Settings > Server controls so it picks up the new index definition.","Open a Splunk Support case and ask them to sync the new index with your IDM instance.","Re-create the index through the ACS API, which pushes index changes to the IDM tier too.","Install the add-on again on the search head, since Classic runs modular inputs there now."],a:[1],e:"This is the classic Classic-versus-Victoria case boundary. The index creation procedure carries a step labelled <b>Required step for Classic Experience customers</b>: if the new index must be available to data collection apps on your IDM, <b>contact Splunk Support and request they sync the index with your IDM</b>. On Victoria there is no IDM, so the step disappears entirely. The closest distractor is option 2, and it is plausible because ACS really is the self-service path for index management — but the ACS docs note ACS does not manage internal indexes, and nothing in ACS reaches the IDM tier. Option 3 states the Victoria behavior (modular inputs on the search head) and applies it to a Classic stack, which is the single most common Experience mix-up on this exam.",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-your-indexes-and-data-in-splunk-cloud-platform/manage-splunk-cloud-platform-indexes",hard:true},
];

/* ============ Cloud Admin Course — self-paced lessons mapped to the official course deck ============ */
/* ============ SPLK-1005 Fundamentals bank ============
   Same 13 blueprint categories as CLOUD_QUESTIONS, one difficulty tier below:
   single-fact recall and one-step application, hard:false throughout. */
const CLOUDFUND_QUESTIONS = [
 /* --- Splunk Cloud Overview --- */
 {exam:"cloudfund",cat:"c1over",q:"Under the Splunk Cloud Platform shared responsibility model, who installs, configures, and upgrades the forwarders that send data in?",o:["Splunk, as part of its scheduled maintenance windows","The customer, on the systems they own and manage","Splunk Support, after you open a case in the portal","The deployment server, which upgrades them for you"],a:[1],e:"<p>Setup, enablement, and sending data from forwarders is explicitly the <b>customer's responsibility</b>. You install, configure, and manage your own forwarders, including keeping their versions compatible with the service.</p><p>Splunk maintenance windows are a real thing, but they cover the <b>Splunk Cloud Platform service itself</b>, such as version upgrades to the search and indexing tiers. They never reach out to the forwarders running in your environment.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:false},
 {exam:"cloudfund",cat:"c1over",q:"Which role gives a Splunk Cloud Platform customer the capabilities needed to administer their own deployment?",o:["splunk_system_upgrader, the rolling upgrade role","admin, which Splunk reserves for its own maintenance","sc_admin, the Splunk Cloud Platform admin role","power, which can edit shared objects and alerts"],a:[2],e:"<p>Splunk Cloud Platform provides the <b>sc_admin</b> role, which carries the capabilities required to administer the service. An sc_admin performs self-service tasks such as installing apps, creating and managing indexes, and managing users and their passwords, all through Splunk Web.</p><p>The <b>admin</b> role is the tempting answer for anyone coming from Splunk Enterprise, but on Splunk Cloud Platform Splunk uses the Admin and system user roles for its own monitoring and maintenance, and you should not modify them.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:false},
 {exam:"cloudfund",cat:"c1over",q:"Which statement describes a real difference between the Victoria and Classic Experiences of Splunk Cloud Platform?",o:["Only Classic Experience supports self service app installation","Only Victoria Experience can run federated searches on a stack","Only Classic Experience lets customers create their own indexes","Only Classic Experience requires an IDM for modular inputs"],a:[3],e:"<p>An <b>Inputs Data Manager (IDM)</b> is required to run modular and scripted inputs only on Classic Experience. On <b>Victoria Experience</b> those inputs run directly on the search head, and Splunk migrates existing IDM apps to the search tier during the upgrade.</p><p>Self-service app installation is reversed in the first option: it is <b>Victoria Experience</b> that supports self-service installation of private apps and most public Splunkbase apps, not Classic.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/get-started-managing-splunk-cloud-platform/determine-your-splunk-cloud-platform-experience",hard:false},
 /* --- Index Management --- */
 {exam:"cloudfund",cat:"c2index",q:"Setting aside metadata files, what two kinds of files make up a Splunk index inside each bucket?",o:["Raw data in compressed form plus tsidx index files","Uncompressed raw event text plus tsidx index files","Compressed raw data plus a per-index CSV lookup file","Compressed raw data plus a per-index summary index"],a:[0],e:"<p>As the indexer indexes data it writes the <b>rawdata journal</b>, which is the raw data in compressed form, plus <b>tsidx files</b>, which are the index structures that point back into that raw data. Each bucket directory holds a rawdata journal along with its associated tsidx and metadata files, and together these constitute the index.</p><p>The uncompressed raw event text option gets the tsidx half right but fails on the rawdata half. Splunk always compresses the journal on disk, which is why an index typically occupies far less space than the raw source data it was built from.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/manage-indexers-and-indexer-clusters/10.4/manage-index-storage/how-the-indexer-stores-indexes",hard:false},
 {exam:"cloudfund",cat:"c2index",q:"An admin configures an index to move expired data to Dynamic Data Self-Storage (DDSS). What happens to that data once it lands in the self-storage location?",o:["It stays searchable in Splunk Cloud for another 30 days","It remains searchable in Splunk Cloud with no time limit","It can be restored to Splunk Cloud from the Indexes page","It can no longer be searched from Splunk Cloud Platform"],a:[3],e:"<p>With <b>DDSS</b>, expired buckets are copied into a storage location you own and manage, such as your own S3 or GCS bucket. Splunk Cloud does not delete the data until the move succeeds, but once it is there the data can no longer be searched from Splunk Cloud Platform. You can restore it to a Splunk Enterprise instance if you need to search it again.</p><p>The option about restoring from the Indexes page describes <b>DDAA</b>, the Splunk-managed archive, not self-storage. DDAA data can be restored back into searchable storage from Splunk Web and then stays searchable for 30 days, which is also what the first option is really describing.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-your-indexes-and-data-in-splunk-cloud-platform/manage-splunk-cloud-platform-indexes",hard:false},
 {exam:"cloudfund",cat:"c2index",q:"A user pipes a search to the <code>delete</code> command. What does that command actually do to the matched events?",o:["It frees the disk space that the matched events occupied","It hides the matched events from future search results","It rolls the affected hot buckets to warm and then purges","It removes the matched events and shortens index retention"],a:[1],e:"<p>The <b>delete</b> command marks every event returned by the search as deleted so that subsequent searches do not return them. No user, not even one with admin permissions, can view the data afterward, but the command explicitly <b>does not reclaim disk space</b>.</p><p>Freeing disk space is the tempting wrong answer because deletion sounds like removal. On Splunk Cloud there is no CLI, so the only way to actually purge data from disk is to stop forwarding to the index and lower the Searchable retention setting until the buckets age out.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/spl-search-reference/10.5.2605/search-commands/delete",hard:false},
 /* --- User Authentication & Roles --- */
 {exam:"cloudfund",cat:"c3auth",q:"In Splunk Cloud Platform, which default role holds the <code>delete_by_keyword</code> capability that the <code>delete</code> command requires?",o:["The sc_admin role, the Splunk Cloud administrator role","The admin role, which holds the admin_all_objects","The can_delete role, created for just this purpose","The power role, which can also schedule searches"],a:[2],e:"<p>The capability that gates the delete command is <b>delete_by_keyword</b>, and by default only the <b>can_delete</b> role carries it. Note that can_delete is a role, not a capability, so the admin assigns the role to a user rather than adding a capability to an existing role.</p><p>Choosing sc_admin is the natural guess because it is the Splunk Cloud administrator role, but the capability table shows delete_by_keyword unchecked for user, power, admin and sc_admin alike. Splunk recommends creating a separate account holding can_delete and logging in with it only when you intend to delete data.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/spl-search-reference/10.5.2605/search-commands/delete",hard:false},
 {exam:"cloudfund",cat:"c3auth",q:"Which external authentication options does Splunk Cloud Platform support for user accounts?",o:["LDAP or Active Directory, plus SAML v2 sign-on","SAML v2 single sign-on only; LDAP is not supported","Built-in Duo or RSA multifactor authentication only","LDAP only; SAML sign-on needs Splunk Enterprise"],a:[0],e:"<p>Splunk Cloud Platform lets you authenticate users against <b>LDAP</b> or Active Directory, and it supports single sign-on with any <b>SAML v2</b> identity provider. Both schemes are available, and only SHA-256 signatures are supported in the SAML message between your IdP and Splunk Cloud.</p><p>The built-in Duo or RSA option is wrong and is the trap worth remembering. Splunk Enterprise has native Duo and RSA multifactor support, but Splunk Cloud does not; to get MFA on Splunk Cloud you must front it with a SAML v2 IdP that provides MFA itself.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:false},
 {exam:"cloudfund",cat:"c3auth",q:"An admin creates a custom role that inherits from an existing role. What happens to the capabilities that come from the parent role?",o:["They are copied in and can be individually removed","They are ignored unless re-selected on the child role","They apply to searches only, not to management tasks","They are granted and cannot be deselected there"],a:[3],e:"<p>Capabilities on the Splunk platform are <b>always additive</b>. On the Capabilities tab of the child role, inherited capabilities appear grayed out and already selected, and you cannot deselect them; the same is true for indexes inherited on the Indexes tab.</p><p>The idea that inherited capabilities can be individually removed is the common misconception. Because you cannot subtract, the correct design is to inherit from a role that grants no more than you want, rather than inheriting broadly and then trying to strip privileges back out.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/manage-users-and-security/10.5.2605/manage-splunk-platform-users-and-roles/create-and-manage-roles-with-splunk-web",hard:false},
 /* --- Configuration Files --- */
 {exam:"cloudfund",cat:"c4conf",q:"Why should an admin never edit a configuration file that lives in a <code>default</code> directory?",o:["The default directory is read-only on every Splunk install","An upgrade overwrites default, so the change is lost","Settings in default outrank local and cannot be changed","Splunk ignores the default directory when merging settings"],a:[1],e:"<p>The <b>default</b> directory holds preconfigured files shipped with the software, and the upgrade process overwrites its contents automatically. Any edit you make there is silently removed at the next upgrade, so customizations belong in a <code>local</code> directory such as <code>etc/system/local</code> or an app's <code>local</code> folder.</p><p>The claim that default outranks local inverts the precedence rule. A setting defined in a non-default directory takes precedence over the same setting in default, which is exactly the mechanism that lets local survive upgrades and still win the merge.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-file-directories",hard:false},
 {exam:"cloudfund",cat:"c4conf",q:"What does the <code>btool</code> command-line tool report?",o:["The settings currently held in running splunkd memory","A live diff between two Splunk instances' conf files","The merged settings from all copies of one conf file","Every conf file on disk holding a given setting name"],a:[2],e:"<p><b>btool</b> simulates the configuration merging process using the on-disk conf files and prints the resulting merged settings in order of precedence. It works on one conf file at a time, and adding <code>--debug</code> shows which file on disk each setting came from.</p><p>The memory option is the tempting miss because it sounds like what you want. The btool report reflects what is on disk, not what splunkd currently has loaded, so a change that requires a restart shows up in btool output even though it is not yet active.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/troubleshoot/10.4/first-steps/use-btool-to-troubleshoot-configurations",hard:false},
 {exam:"cloudfund",cat:"c4conf",q:"A Splunk Cloud admin needs to change a setting that normally lives in a configuration file. How is that change made?",o:["Open an SSH session to the search head and edit the file","Edit the file locally, then upload it on the Indexes page","Use Splunk Web, the ACS API, or an app that sets it","Run the splunk edit CLI command against the stack URL"],a:[2],e:"<p>Splunk Cloud Platform gives customers no filesystem or shell access to the stack; the firewall blocks SSH, so you cannot edit conf files or use the CLI against the deployment. Configuration is done through <b>Splunk Web</b>, the <b>Admin Config Service (ACS) API</b>, or by installing an app whose own conf files carry the setting.</p><p>The CLI option is the natural habit carried over from Splunk Enterprise, where editing files and running <code>splunk</code> commands are both valid. On Splunk Cloud, any supported task that genuinely requires command-line access is performed by Splunk on your behalf through a support case.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-config-service-manual/10.5.2605/welcome-to-the-admin-config-service-acs/about-the-admin-config-service-acs-api",hard:false},
 /* --- Getting Data In --- */
 {exam:"cloudfund",cat:"c5gdi",q:"An admin needs to drop certain events at the collection tier so they never reach Splunk Cloud Platform. Which forwarder type supports per-event filtering?",o:["A universal forwarder, using the outputs.conf file","A universal forwarder with indexer acknowledgment on","A light forwarder, which forwards only unparsed data","A heavy forwarder, which parses data into events"],a:[3],e:"<p>Only a <b>heavy forwarder</b> runs the full parsing pipeline, so it breaks the stream into individual events and can then filter or route them based on event content. The Splunk forwarder comparison table lists per-event filtering and event routing as heavy forwarder capabilities only.</p><p>The universal forwarder options fail because a <b>universal forwarder</b> does not parse data into events, so it cannot inspect them; <code>outputs.conf</code> controls where data is sent, not which events get discarded.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/introduction-to-forwarding/types-of-forwarders",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"You download the Splunk Cloud Platform universal forwarder credentials package, splunkclouduf.spl. What do you do with that file on the forwarder?",o:["Extract it into the etc/system/local directory on the host","Install it as an app with the splunk install app command","Rename it to outputs.conf and copy it into etc/system/local","Upload it on the Forwarding and receiving page in Splunk Web"],a:[1],e:"<p>The credentials package is a Splunk app, so you install it with <code>$SPLUNK_HOME/bin/splunk install app /tmp/splunkclouduf.spl</code> and then restart the forwarder. The app supplies the <b>outputs.conf</b> settings and TLS certificates the forwarder needs to reach your Splunk Cloud Platform receiving port.</p><p>Hand-extracting the archive into <code>etc/system/local</code> fails because the package is not a loose set of files for the system context; it is a packaged app, and installing it that way skips the app install process that puts the certificates in the right place.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/universal-forwarder-manual/10.4/configure-the-universal-forwarder/enable-a-receiver-for-the-splunk-cloud-platform",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"What does indexer acknowledgment give a forwarder that sends data to Splunk Cloud Platform?",o:["It resends any block the receiver never confirms writing","It compresses each block of data before sending it onward","It spreads blocks evenly over every available receiver","It writes a local copy of each block before sending it"],a:[0],e:"<p>With <b>indexer acknowledgment</b>, the forwarder keeps each roughly 64 KB block in its wait queue until the receiver confirms that the block was written to the file system. If no acknowledgment arrives, the forwarder resends the block. You turn it on with <code>useACK = true</code> in <code>outputs.conf</code>, and it is disabled by default.</p><p>Spreading blocks over receivers is <b>load balancing</b>, a separate feature you get by listing several servers in a target group. Load balancing decides where a block goes; it never confirms that the block was safely written.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/perform-advanced-configuration/protect-against-loss-of-in-flight-data",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"By default, what kind of data does a universal forwarder send to Splunk Cloud Platform?",o:["Parsed data, already split into individual tagged events","Raw data, passed along unaltered over a plain TCP stream","Unparsed data, tagged with source, source type, and host","Indexed data, written into buckets before it is forwarded"],a:[2],e:"<p>A universal forwarder sends <b>unparsed</b> data, which is a form of cooked data. It does not identify individual events, but it does tag the stream with source, source type, and host and split it into roughly 64 KB blocks. Setting <code>sendCookedData = false</code> is what makes a forwarder send raw data instead.</p><p>Parsed data is what a <b>heavy forwarder</b> sends, because only the heavy forwarder runs the full parsing pipeline that breaks the stream into individual events. That is the tier difference the exam is testing here.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/introduction-to-forwarding/types-of-forwarders",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"What is the Inputs Data Manager (IDM) in Splunk Cloud Platform used for?",o:["Storing the warm and cold buckets for high volume indexes","Managing deployment apps for the on premises forwarders","Terminating the syslog streams sent by network appliances","Running scripted and modular inputs as a hosted solution"],a:[3],e:"<p>The <b>Inputs Data Manager (IDM)</b> is a Splunk-hosted component for scripted and modular inputs, so you usually do not have to stand up your own infrastructure for cloud-based add-ons. It is required only on Classic Experience; on Victoria Experience you run those inputs on the search head instead.</p><p>Managing deployment apps is the job of a <b>deployment server</b>, which you host yourself and which pushes configurations to forwarders. The IDM runs inputs; it does not distribute apps to your forwarders.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/get-data-into-splunk-cloud-platform/introduction-to-getting-data-in",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"Which statement about HTTP Event Collector (HEC) on Splunk Cloud Platform is correct?",o:["It accepts events over TCP, UDP, or HTTPS on port 9997","It accepts events over HTTP and HTTPS using a token","It needs a universal forwarder in front of every client","It replaces the forwarder credentials app on the client"],a:[1],e:"<p><b>HEC</b> accepts data only over the HTTP and Secure HTTP (HTTPS) protocols, and it uses token-based authentication: a client presents a token value in the Authorization header rather than Splunk credentials. On Splunk Cloud Platform, HEC is enabled by default and you create tokens in Splunk Web.</p><p>The option listing TCP and UDP on port 9997 fails because those are <b>network inputs</b> and the Splunk-to-Splunk receiving port, which are entirely separate input types from HEC.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/get-data-in/10.5.2605/get-data-with-http-event-collector/set-up-and-use-http-event-collector-in-splunk-web",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"You are creating an HEC token on Splunk Cloud Platform and want its events to land in a new index. What must you do first?",o:["Create the index, since HEC cannot create one for you","Set a default index in the HEC global settings dialog","Ask Splunk Support to enable standard HEC on the stack","Add an output group so HEC can forward to that index"],a:[0],e:"<p>On Splunk Cloud Platform, the index you select for an HEC token <b>must already exist</b>; you cannot create a new index during the token setup process. Create the index first from the Indexes page, then point the token at it.</p><p>Editing HEC <b>global settings</b> is not possible on Splunk Cloud Platform. You can only change settings on the tokens you create, so a default index set globally is a Splunk Enterprise capability, not a Cloud one.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/get-data-in/10.5.2605/get-data-with-http-event-collector/set-up-and-use-http-event-collector-in-splunk-web",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"In outputs.conf, which setting names the receivers that a target group sends data to?",o:["defaultGroup, set in the global tcpout stanza","indexAndForward, set in the global tcpout stanza","server, set in the tcpout target group stanza","useACK, set in the tcpout target group stanza"],a:[2],e:"<p>The <b>server</b> setting is required in a target group stanza such as <code>[tcpout:my_indexers]</code> and takes one or more entries in host-or-address-plus-port form. Listing more than one entry there is also how you get automatic load balancing.</p><p><b>defaultGroup</b> is a tempting pick because it also deals with destinations, but it belongs in the global <code>[tcpout]</code> stanza and only names which target groups receive events. It never names the individual receiving hosts.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/configure-forwarders/configure-forwarding-with-outputs.conf",hard:false},
 {exam:"cloudfund",cat:"c5gdi",q:"Why would an organization place an intermediate forwarding tier in front of Splunk Cloud Platform?",o:["To let the universal forwarders route events by field value","To keep a fully searchable copy of the data in the network","To remove the need for the forwarder credentials package","To limit which hosts reach Splunk Cloud over the internet"],a:[3],e:"<p>An <b>intermediate forwarding tier</b> is a set of heavy forwarders that acts as an aggregation point for other forwarders, so only that small set of hosts communicates with Splunk Cloud Platform over the internet. Because the tier parses data, you can also route or drop events before they leave your network.</p><p>Letting universal forwarders route by field value is wrong because a <b>universal forwarder</b> never gains that ability, no matter what sits downstream. Conditional routing requires parsed events, which is a heavy forwarder function.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/introduction/use-forwarders-to-get-data-into-splunk-cloud-platform",hard:false},
 /* --- Forwarder Management --- */
 {exam:"cloudfund",cat:"c6fwdmgmt",q:"Where does the deployment server that manages a Splunk Cloud customer's forwarders run?",o:["On the Splunk Cloud search head tier, managed by Splunk","On the Splunk Cloud indexer tier, reachable via ACS","On the Inputs Data Manager (IDM) that Splunk provides","On a Splunk instance the customer installs and runs"],a:[3],e:"<p>Splunk Cloud Platform does not host a deployment server for you. Your subscription includes a <b>deployment server license</b> that you request from Splunk Support, but you install and run that instance yourself, typically inside your own network alongside the forwarders it manages.</p><p>Assuming Splunk hosts it on the search head tier is the tempting error, since Splunk does manage the indexers and search heads. Forwarder setup, configuration, version compatibility, and the deployment server that drives them are all explicitly the customer's responsibility.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:false},
 {exam:"cloudfund",cat:"c6fwdmgmt",q:"On a deployment server, which directory holds the deployment apps that get pushed out to forwarders? Paths shown are relative to the Splunk install directory.",o:["The etc/deployment-apps folder on that server","The etc/apps folder on the deployment server itself","The etc/deployment-apps folder on each forwarder","The etc/system/local folder on that same server"],a:[0],e:"<p>The deployment server's app repository is <code>$SPLUNK_HOME/etc/deployment-apps</code>, which is the default value of the <b>repositoryLocation</b> setting in <code>serverclass.conf</code>. An app must already exist there before a server class stanza can map it to a group of clients.</p><p>Choosing etc/apps on the deployment server confuses the source with the destination. On the client side, <b>targetRepositoryLocation</b> defaults to <code>$SPLUNK_HOME/etc/apps</code>, which is where the forwarder installs the app it downloads, not where the deployment server stores it.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.2-configuration-file-reference/serverclass.conf",hard:false},
 {exam:"cloudfund",cat:"c6fwdmgmt",q:"Which configuration file on a universal forwarder tells it which deployment server to phone home to?",o:["outputs.conf, which sets the indexer destination","deploymentclient.conf, pushed in a base app","serverclass.conf, which defines client groups","inputs.conf, which defines what gets monitored"],a:[1],e:"<p><b>deploymentclient.conf</b> points the forwarder at its deployment server through the <code>targetUri</code> setting under the <code>[target-broker:deploymentServer]</code> stanza. The client then phones home on a repeating interval, controlled by <code>phoneHomeIntervalInSecs</code>, to check for new or changed apps.</p><p>Picking serverclass.conf is the closest miss because it is the other half of the same conversation. That file lives on the <b>deployment server</b>, where it maps apps to groups of clients; it is never read by the forwarder itself.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/update-your-deployment/9.4/configure-the-deployment-system/configure-deployment-clients",hard:false},
 /* --- Monitor Inputs --- */
 {exam:"cloudfund",cat:"c7monitor",q:"An admin wants Splunk Cloud Platform to continuously monitor a log directory on a Linux server. What is required?",o:["A universal or heavy forwarder running on that server","An Inputs Data Manager instance pointed at that path","A repeated single file upload from Splunk Web each day","An HEC token created for that directory on the stack"],a:[0],e:"<p>To use the <b>monitor</b> input on Splunk Cloud Platform you must run a universal or heavy forwarder on the machine holding the files. Data collection happens on the forwarder, which then sends the data to your Splunk Cloud Platform instance.</p><p>Uploading through Splunk Web is a real Cloud capability, but the <b>upload</b> input handles one static file at a time and is not a continuous monitor. It cannot watch a directory for new data as it is written.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"In a monitor input path, which Splunk wildcard searches recursively through subdirectories?",o:["The asterisk, matching within one path segment","The ellipsis, which is three periods in a row","The question mark, matching a single character","The percent sign, matching any file extension"],a:[1],e:"<p>The <b>ellipsis</b> wildcard recurses through directories and any number of levels of subdirectories. For example, <code>/foo/.../bar.log</code> matches <code>/foo/1/bar.log</code> and <code>/foo/1/2/bar.log</code>, and its regular expression equivalent is <code>.*</code>.</p><p>The asterisk is the tempting wrong answer because it is a wildcard too, but it matches only within a single path segment and does not descend into subfolders. So <code>/foo/*/bar</code> matches <code>/foo/1/bar</code> but not <code>/foo/1/2/bar</code>.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/specify-input-paths-with-wildcards",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"What syntax do the whitelist and blacklist settings inside a monitor stanza use?",o:["Splunk wildcards, the same syntax used in the input path","Glob patterns that each match one directory segment name","Regular expressions that match the file name or path","SPL search terms evaluated against each file's contents"],a:[2],e:"<p>Allow list and deny list rules use <b>regular expression</b> syntax to match the file name or path, and the rules must sit inside an input stanza such as <code>[monitor:///mnt/logs]</code>. That is why an entry like <code>whitelist = \\.log$</code> uses a backslash and a dollar sign rather than a wildcard.</p><p>Splunk wildcards are the tempting answer because they appear right next door in the same stanza, but they belong in the <b>input path</b> itself. Path specifications do not accept regular expressions, and the filter lists do not accept the ellipsis or asterisk wildcards.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/include-or-exclude-specific-incoming-data",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"A monitor stanza defines both a whitelist and a blacklist, and one file matches both patterns. What happens to that file?",o:["It is monitored, because the allow list is evaluated first","It is monitored, but its events go to the default index","The whole input is disabled until you remove one filter","It is not monitored, since the deny list takes precedence"],a:[3],e:"<p>The two filters are independent, but when a file matches both, the <b>deny list wins</b> and the Splunk platform does not index that file. Splunk documents this plainly: deny lists take precedence over allow lists.</p><p>Assuming the allow list is checked first and therefore wins is the classic trap. Order of evaluation is not what decides the outcome; the <b>blacklist</b> setting simply overrides the <code>whitelist</code> setting whenever both match.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/include-or-exclude-specific-incoming-data",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"Logs arrive at paths like /logs/servers/host08/app.log and the admin wants the host field set to host08. Which monitor setting does that?",o:["host_segment, set to 3 for the third path segment","host_regex, which reads the host from file contents","host, which hardcodes one host for the whole stanza","connection_host, which resolves the sending address"],a:[0],e:"<p><b>host_segment</b> takes an integer N and uses the Nth forward-slash-separated segment of the path as the host. In <code>/logs/servers/host08/app.log</code> the third segment is <code>host08</code>, so <code>host_segment = 3</code> produces the wanted value.</p><p><b>host_regex</b> is the tempting near-miss because it also derives a host dynamically, but it applies a regular expression to the file name and uses the first capturing group. It does not read the contents of the file, and it is not the segment-based option this path calls for.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories-with-inputs.conf",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"What does setting followTail = 1 do the first time a monitor input encounters a file?",o:["It reads from the start, then holds the file handle open","It begins at the end and reads only newly written data","It stops checking the file after writes pause briefly","It rereads the whole file each time the file is renamed"],a:[1],e:"<p>With <b>followTail</b> set to 1, monitoring begins at the end of the file, much like the *nix command <code>tail -f</code>, so existing content is skipped and only data written after that first encounter is read. After the first encounter the Splunk platform tracks the file with its own file position records.</p><p>Stopping checks after writes pause describes <b>time_before_close</b>, which sets how long the input waits before closing a file at end-of-file. That setting governs closing behavior, not where reading starts.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories-with-inputs.conf",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"A monitored directory holds thousands of old unchanging log files next to a few active ones. Which setting keeps the input from rechecking the stale files?",o:["time_before_close, which delays closing an open file","alwaysOpenFile, which opens files to check for changes","ignoreOlderThan, which sets a file age threshold","initCrcLength, which extends the file fingerprint"],a:[2],e:"<p><b>ignoreOlderThan</b> compares each file's modification time against the current time and puts anything older than the given window on an ignore list, which speeds up file tracking in directory trees full of historical files. You give it a number and a unit, such as <code>ignoreOlderThan = 7d</code>.</p><p><b>alwaysOpenFile</b> is the tempting opposite: it makes the platform open files to see whether they have been indexed, which increases load and slows indexing rather than reducing the work.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories-with-inputs.conf",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"Which setting must a batch input stanza include, and what does it do?",o:["queue = indexQueue, which bypasses the parsing pipeline","move_policy = archive, which moves files after reading","followTail = 1, which starts reading at the end of file","move_policy = sinkhole, which deletes files it reads"],a:[3],e:"<p>A <b>batch</b> stanza requires <code>move_policy = sinkhole</code>, which loads the file destructively: the Splunk platform indexes the file and then deletes it. That is the key difference from a <code>monitor</code> input, which watches files continuously and never removes them.</p><p>The archive value is the tempting wrong answer because it sounds like a safer version of the same idea, but <code>move_policy</code> has no such value. Batch inputs only sinkhole, so you must never point one at files you want to keep.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/monitor-files-and-directories-with-inputs.conf",hard:false},
 {exam:"cloudfund",cat:"c7monitor",q:"Several files in a monitored directory share a long identical header, so the Splunk platform treats them as one file. Which setting increases the number of bytes used for the fingerprint?",o:["initCrcLength, whose default value is 256 bytes","crcSalt, which adds the source path to the file CRC","time_before_close, whose default value is 3 seconds","alwaysOpenFile, which forces a read of every file"],a:[0],e:"<p>The monitoring processor fingerprints a file by hashing its first 256 bytes into a cyclic redundancy check. <b>initCrcLength</b> raises that byte count so the fingerprint extends past a shared static header, and its default value is 256 bytes.</p><p><b>crcSalt</b> is the tempting alternative because it also fixes duplicate CRCs, but it does so by adding a string, typically the full source path, to the CRC rather than by reading more of the file. It also breaks rotation tracking, so files get reindexed when they roll.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-files-and-directories/how-the-splunk-platform-handles-log-file-rotation",hard:false},
 /* --- Network & Other Inputs --- */
 {exam:"cloudfund",cat:"c8network",q:"Splunk documentation recommends using TCP rather than UDP whenever possible for network inputs. What is the documented reason?",o:["UDP inputs cannot be assigned an index or a source type in the stanza.","UDP inputs can only be created with the CLI, never from Splunk Web.","UDP inputs must always listen on a port number that is above 1024.","UDP does not guarantee delivery of the network packets it carries."],a:[3],e:"<p>Splunk documentation states that the best practice is to use <b>TCP</b> to send network data whenever possible, because <b>UDP</b> is not a desirable transport: it does not guarantee the delivery of network packets. Data that arrives over UDP can simply drop off the queue and be lost if the input queue fills up.</p><p>The idea that a UDP input cannot take an index or source type fails because the <code>[udp://...]</code> stanza accepts the same <code>index</code>, <code>sourcetype</code>, <code>source</code>, and <code>host</code> settings that the <code>[tcp://...]</code> stanza does. The protocol choice is about delivery reliability, not about which settings the stanza supports.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-network-sources/get-data-from-tcp-and-udp-ports",hard:false},
 {exam:"cloudfund",cat:"c8network",q:"An admin needs to onboard syslog from several hundred network devices. What does Splunk documentation recommend as the best practice for collecting this data?",o:["Land the syslog on a syslog server such as syslog-ng, then forward it.","Open a UDP input on port 514 on each device and point it at the indexer.","Send the syslog straight to the Splunk Cloud Platform indexers over UDP.","Configure a monitor input on every network device to read its own logs."],a:[0],e:"<p>For syslog, the documented best practice is to land the data on a dedicated <b>syslog server</b>, such as <b>syslog-ng</b> or <b>Splunk Connect for Syslog</b>, and then have a forwarder read it and send it on. A separate syslog service also lets you keep the raw messages on disk if a retention policy requires untouched events.</p><p>Sending syslog straight to the indexers over UDP fails because the Splunk platform is not a substitute for a syslog server: the stream lands on a single receiver, UDP packets can be dropped, and any message that arrives while that receiver is down is irrecoverably lost.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-data-from-network-sources/get-data-from-tcp-and-udp-ports",hard:false},
 {exam:"cloudfund",cat:"c8network",q:"In an <code>inputs.conf</code> stanza, what does the <code>persistentQueueSize</code> setting do?",o:["It caps the memory that the parsing pipeline uses for one input.","It writes input data to disk once the in-memory queue is full.","It sets how long a forwarder holds events awaiting indexer acks.","It reserves disk space on the index that receives that input."],a:[1],e:"<p><b>Persistent queuing</b> protects against data loss when an input arrives faster than the forwarder can process it. By default the in-memory input queue is only 500 KB, so setting <code>persistentQueueSize</code> inside the input stanza tells the forwarder to spill the overflow into files on disk instead of dropping it. It is available for network, FIFO, scripted, Windows Event Log, and HEC inputs.</p><p>The indexer acknowledgment answer fails because acknowledgment is an <code>outputs.conf</code> feature that governs the forwarder-to-indexer wait queue on the output side. <code>persistentQueueSize</code> sizes the input-side queue instead, and each input gets its own queue.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/improve-the-data-input-process/use-persistent-queues-to-help-prevent-data-loss",hard:false},
 {exam:"cloudfund",cat:"c8network",q:"An admin adds a <code>[script://...]</code> input to a universal forwarder. Which directory is a valid location for the script that the stanza calls?",o:["$SPLUNK_HOME/etc/apps/my_app/scripts","$SPLUNK_HOME/etc/apps/my_app/local","$SPLUNK_HOME/etc/apps/my_app/bin","$SPLUNK_HOME/etc/system/local/bin"],a:[2],e:"<p>The Splunk platform runs a scripted input only when the script lives in one of three places: <code>$SPLUNK_HOME/etc/system/bin</code>, the <b>bin</b> directory of an app under <code>$SPLUNK_HOME/etc/apps</code>, or <code>$SPLUNK_HOME/bin/scripts</code>. Best practice is to use the <b>bin</b> directory nearest the <code>inputs.conf</code> file that calls the script, and the stanza also takes an <code>interval</code> setting that defaults to 60 seconds.</p><p>A <code>scripts</code> folder inside the app fails because the platform does not look there. The directory name has to be <code>bin</code>, so moving the same file into the app's <code>bin</code> directory is what makes the input run.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-other-kinds-of-data-in/get-data-from-apis-and-other-remote-data-interfaces-through-scripted-inputs",hard:false},
 {exam:"cloudfund",cat:"c8network",q:"A Windows forwarder already collects local channels with <code>[WinEventLog://Security]</code>. The admin must now collect event logs from a remote Windows server that has no forwarder on it. Which file configures that collection?",o:["inputs.conf, by adding a server setting to the WinEventLog stanza.","outputs.conf, by defining an output group for the remote machine.","server.conf, by listing the remote hosts the forwarder connects to.","wmi.conf, which handles remote collection through WMI providers."],a:[3],e:"<p>The <b>wmi.conf</b> file handles remote Windows data collection through <b>Windows Management Instrumentation</b>. A stanza such as <code>[WMI:AppAndSys]</code> uses a <code>server</code> setting plus either <code>event_log_file</code> or a <code>wql</code> query to pull event log or performance data from other machines. The <code>[WinEventLog://...]</code> and <code>[perfmon://...]</code> stanzas in <code>inputs.conf</code> collect from the local machine only.</p><p>Adding a <code>server</code> setting to the <code>WinEventLog</code> stanza fails because that input has no remote-host capability. It reads the channels on the machine where the forwarder itself runs, so remote hosts have to be named in <code>wmi.conf</code> instead.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/get-windows-data/monitor-data-through-windows-management-instrumentation-wmi",hard:false},
 {exam:"cloudfund",cat:"c8network",q:"How does a client authenticate itself to the HTTP Event Collector (HEC)?",o:["The client presents a HEC token value that HEC validates on connect.","The client sends the Splunk username and password in the request body.","The client presents a TLS client certificate issued by the HEC endpoint.","The client authenticates with a session key from the auth REST endpoint."],a:[0],e:"<p>HEC uses a <b>token-based authentication model</b>. Each token is a 32-character GUID that the client sends in the <code>Authorization</code> header, preceded by the keyword <code>Splunk</code>. If the token is valid, HEC accepts the connection and indexes the payload using the source, source type, and index that are configured on that token.</p><p>Sending a Splunk username and password fails because the point of a HEC token is that you never embed credentials in the application. Access is managed per token, which is why disabling or deleting one token cuts off only the clients that use it.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/get-data-in/10.5.2605/get-data-with-http-event-collector/set-up-and-use-http-event-collector-in-splunk-web",hard:false},
 /* --- Fine-tuning Inputs --- */
 {exam:"cloudfund",cat:"c9finetune",q:"Which of the following happens during the <b>parsing</b> phase of the data pipeline rather than the input phase?",o:["Applying the CHARSET setting to convert the source data to UTF-8.","Breaking the stream into events and extracting the timestamps.","Reading the source and tagging it with an index and a source type.","Writing the raw events and their index-time fields into the index."],a:[1],e:"<p>The <b>parsing phase</b> is where the Splunk platform breaks the incoming stream into individual events and pulls the timestamp out of each one. Settings such as <code>LINE_BREAKER</code>, <code>SHOULD_LINEMERGE</code>, <code>TRUNCATE</code>, <code>TIME_PREFIX</code>, and <code>TIME_FORMAT</code> all take effect here, which is why they belong on the first component that parses the data.</p><p>The <code>CHARSET</code> answer fails because character set conversion belongs to the <b>input phase</b>, alongside the rest of <code>inputs.conf</code>. It is applied as the data is read, before any event breaking or timestamp extraction happens.</p>",d:"https://help.splunk.com/en/data-management/splunk-enterprise-admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-parameters-and-the-data-pipeline",hard:false},
 {exam:"cloudfund",cat:"c9finetune",q:"In which configuration file does an admin set <code>CHARSET</code> to control the character encoding of a data source?",o:["inputs.conf, in the stanza for the data input that reads that source.","indexes.conf, in the stanza for the index that stores the source.","props.conf, in a stanza matching the host, source, or source type.","transforms.conf, in the stanza the input's TRANSFORMS clause names."],a:[2],e:"<p><code>CHARSET</code> is a <b>props.conf</b> setting. You apply it in a stanza that matches the data, such as <code>[host::GreekSource]</code>, and give it an encoding like <code>ISO-8859-7</code>, or set <code>CHARSET=AUTO</code> to have the platform detect the encoding. The Splunk platform attempts UTF-8 by default, so you set this only when a source is not UTF-8.</p><p>Putting it in <code>inputs.conf</code> fails because an input stanza defines where the data comes from and which index, source, and source type it gets, not how the bytes are decoded. On Splunk Cloud Platform you edit <code>props.conf</code> on the forwarder.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-character-set-encoding",hard:false},
 {exam:"cloudfund",cat:"c9finetune",q:"A data input sets <code>sourcetype = app_json</code>. A <code>props.conf</code> stanza named <code>[source::/var/log/app/...]</code> on the same forwarder sets <code>sourcetype = app_generic</code>. Which source type do the events get?",o:["app_generic, because a source stanza is more specific than an input.","app_generic, because props.conf is read after inputs.conf is read.","Whatever automatic source type recognition matches for the data.","app_json, because an explicit type on the input takes precedence."],a:[3],e:"<p>The Splunk platform assigns source types by working down a fixed order of precedence, and the first method that produces an answer wins. <b>Explicit source type specification based on the data input</b> is the very first method in that order, so the <code>sourcetype</code> set on the input stanza is what the events are indexed with.</p><p>The <code>[source::...]</code> answer fails because explicit specification based on the <b>data source</b> is only the second method. It takes effect only when the input itself declared no source type, and it is followed in turn by rule-based recognition and automatic source type matching.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-source-types/why-source-types-matter",hard:false},
 /* --- Parsing & Data Preview --- */
 {exam:"cloudfund",cat:"c10parse",q:"An admin needs a Splunk instance sitting in front of Splunk Cloud Platform that breaks events and extracts timestamps before the data is forwarded on. Which component performs that <b>parsing phase</b> work?",o:["A universal forwarder installed on the source host","A heavy forwarder that sends to the cloud stack","A deployment server managing forwarder configs","A monitoring console instance in the deployment"],a:[1],e:"<p>Splunk lists the parsing phase as the point where line breaking, timestamp extraction, and <code>TRANSFORMS</code> are applied, and only an <b>indexer</b> or a <b>heavy forwarder</b> can perform it. Because a Splunk Cloud Platform customer cannot edit files on the cloud indexers, the heavy forwarder is the component you stand up for this job.</p><p>A universal forwarder is the tempting choice because it is the usual sending agent, but it does not parse event data. Splunk allows a universal forwarder into the parsing phase only for <code>INDEXED_EXTRACTIONS</code> on structured files, not for general event breaking or timestamping.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-parameters-and-the-data-pipeline",hard:false},
 {exam:"cloudfund",cat:"c10parse",q:"An admin uploads a sample log file in Splunk Web and lands on the <b>Set Source Type</b> page. What is the main purpose of this data preview step?",o:["To check event breaks and timestamps before indexing","To store the sample file permanently in the target index","To grant role-based access to the index the data uses","To schedule a recurring search over the uploaded sample"],a:[0],e:"<p>The <b>Set Source Type</b> page is the data preview stage of the Add Data workflow. It shows how the Splunk platform will break the sample into events and which timestamps it will assign, so you can correct event breaks and timestamps and then save the result as a new source type.</p><p>Storing the sample in the target index is the wrong idea because preview is a rehearsal, not an ingest. Data preview reads the sample and renders the outcome; nothing is written to an index until you finish the workflow and click through to the input settings.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/how-to-get-data-into-your-splunk-deployment/assign-the-correct-source-types-to-your-data",hard:false},
 {exam:"cloudfund",cat:"c10parse",q:"What must a <code>LINE_BREAKER</code> regular expression in <code>props.conf</code> always contain?",o:["A named field alias for the resulting event text","A capturing group, whose contents are discarded","A trailing anchor that matches the end of a line","A backreference to the previous event timestamp"],a:[1],e:"<p>Splunk documents that the <code>LINE_BREAKER</code> expression <b>must contain a capturing group</b>, a pair of parentheses. The start of that first capturing group marks the end of the previous event, the end of it marks the start of the next event, and the text inside it is discarded.</p><p>The trailing end-of-line anchor is tempting because the default value <code>([\\r\\n]+)</code> does match newlines, but an anchor is optional styling. Remove the parentheses from that same default and the setting breaks, which is exactly why the capturing group is the requirement.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-event-line-breaking",hard:false},
 {exam:"cloudfund",cat:"c10parse",q:"What is the default value of the <code>TRUNCATE</code> setting in <code>props.conf</code>?",o:["1,000 bytes per line","10,000 bytes per line","50,000 bytes per line","100,000 bytes per line"],a:[1],e:"<p>The <b>TRUNCATE</b> setting caps the maximum line length in bytes, and its default is <b>10,000</b>. Anything longer is cut at that limit and tagged with the index-time field <code>meta::truncated</code>, so oversized lines are a signal worth investigating.</p><p>The 100,000 option looks right because Splunk Web displays only the first 100,000 bytes of an event in search results. That is a display limit at search time, not the parsing-phase line length cap that <code>TRUNCATE</code> controls.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-event-line-breaking",hard:false},
 {exam:"cloudfund",cat:"c10parse",q:"An admin adds <code>BREAK_ONLY_BEFORE</code> to a source type stanza but event breaking does not change. Which condition must hold for <code>BREAK_ONLY_BEFORE</code> to take effect?",o:["SHOULD_LINEMERGE must be set to false","LINE_BREAKER must be left at its default","SHOULD_LINEMERGE must be set to true","MAX_EVENTS must be raised from default"],a:[2],e:"<p>Splunk groups <code>BREAK_ONLY_BEFORE</code> with the settings that apply <b>only when SHOULD_LINEMERGE is true</b>. Line merging is what reassembles already-broken lines into multiline events, and the merge rules are the only place this setting is consulted.</p><p>Setting <code>SHOULD_LINEMERGE</code> to false is the opposite of what is needed. That turns line merging off entirely, so the platform emits one event per line as determined by <code>LINE_BREAKER</code> and every merge rule, including this one, is ignored.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/configure-event-line-breaking",hard:false},
 {exam:"cloudfund",cat:"c10parse",q:"Events carry their timestamp partway into each line, and <code>TIME_FORMAT</code> alone keeps failing to parse it. Which <code>props.conf</code> setting marks where the timestamp begins?",o:["TZ, which names the time zone for the events","MAX_TIMESTAMP_LOOKAHEAD, a character limit","TIME_PREFIX, a regex that comes before it","DATETIME_CONFIG, a timestamp processor file"],a:[2],e:"<p><b>TIME_PREFIX</b> is a regular expression that must match up to and including the character just before the timestamp starts; the platform then looks for the timestamp only after that match. Splunk warns that if you set <code>TIME_FORMAT</code> without a prefix, the timestamp has to sit at the very start of every event or parsing fails.</p><p><code>MAX_TIMESTAMP_LOOKAHEAD</code> is the near miss because it also concerns position, but it only limits how many characters are scanned, counted from where <code>TIME_PREFIX</code> lands. It narrows the search window rather than locating the timestamp, and its default is 128 characters.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-timestamps/configure-timestamp-recognition",hard:false},
 /* --- Manipulating Raw Data --- */
 {exam:"cloudfund",cat:"c11rawdata",q:"In a Splunk Cloud Platform deployment, an admin wants to strip account numbers out of raw events before they are indexed. Where is the <code>SEDCMD</code> setting configured?",o:["In transforms.conf on the Splunk Cloud search head","In inputs.conf on the sending universal forwarder","In outputs.conf on the sending universal forwarder","In props.conf on the sending heavy forwarder"],a:[3],e:"<p><b>SEDCMD</b> is a <code>props.conf</code> setting, and Splunk Cloud Platform customers configure it on a <b>heavy forwarder</b> that ingests the data and forwards it to the cloud stack. Splunk applies it during the parsing phase, so the masking happens before the event is written to an index.</p><p>Putting it in <code>transforms.conf</code> is the closest miss, since the regular expression transform method for anonymizing data really does live there. That method still needs a <code>TRANSFORMS</code> reference in <code>props.conf</code>, and <code>SEDCMD</code> itself is never a transforms.conf setting.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/anonymize-data",hard:false},
 {exam:"cloudfund",cat:"c11rawdata",q:"Which line correctly uses a sed substitution in <code>props.conf</code> to replace every match of a pattern?",o:["SEDCMD-mask = s/regex/replacement/g","SEDCMD-mask = y/regex/replacement/g","SEDCMD-mask = s/replacement/regex/g","TRANSFORMS-mask = s/regex/replacement/g"],a:[0],e:"<p>The documented syntax is <b>SEDCMD-class = s/regex/replacement/flags</b>. The regular expression comes first, the replacement text second, and the <code>g</code> flag replaces every match instead of just one; the class suffix after the hyphen is any label you choose.</p><p>The <code>y</code> form is a real sed operator, which makes it the tempting wrong answer, but it does one-for-one character substitution rather than regular expression replacement. Use <code>y/string1/string2/</code> only when swapping individual characters.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/anonymize-data",hard:false},
 {exam:"cloudfund",cat:"c11rawdata",q:"A heavy forwarder uses <code>SEDCMD</code> to mask credit card numbers during parsing. What happens to the original unmasked values?",o:["They stay searchable in a hidden metadata field","They are kept in a separate audit-only index","They are restored automatically at search time","They never reach the index, only masked text"],a:[3],e:"<p><code>SEDCMD</code> rewrites the <b>_raw</b> field at index time, so the event that gets written to the index already contains the masked text. The original characters are simply gone from the indexed data, which is what makes this a genuine anonymization control rather than a display trick.</p><p>Restoration at search time is the tempting answer because Splunk does offer search-time masking through field filters, which leave the underlying data intact. That is the opposite approach; an index-time change like <code>SEDCMD</code> cannot be undone without re-ingesting the source.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-data-in/get-started-with-getting-data-in/10.5.2605/configure-event-processing/anonymize-data",hard:false},
 {exam:"cloudfund",cat:"c11rawdata",q:"An admin wants a noisy subset of events discarded so they are never indexed and never count toward license volume. Which pair of <code>transforms.conf</code> settings does this?",o:["DEST_KEY = queue with FORMAT = indexQueue","DEST_KEY = _raw with FORMAT = nullQueue","DEST_KEY = queue with FORMAT = nullQueue","DEST_KEY = _TCP_ROUTING with FORMAT = null"],a:[2],e:"<p>Routing to the <b>nullQueue</b> is Splunk's equivalent of sending data to <code>/dev/null</code>. You set <code>DEST_KEY = queue</code> to target the queue key and <code>FORMAT = nullQueue</code> as the destination; the matching events are neither forwarded nor indexed and do not count toward indexing volume.</p><p>Pairing the queue key with <code>indexQueue</code> is the near miss, because it uses the correct <code>DEST_KEY</code> but the opposite destination. That value sends events onward to be indexed, and it is normally used to rescue specific events after a broad rule has already routed everything to the null queue.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/forward-and-process-data/forwarding-and-receiving-data/10.5.2605/perform-advanced-configuration/route-and-filter-data",hard:false},
 {exam:"cloudfund",cat:"c11rawdata",q:"An index-time transform must send only the events it matches to a different index. Which <code>DEST_KEY</code> value performs that per-event index assignment?",o:["_MetaData:Index, with FORMAT naming the index","MetaData:Source, with FORMAT naming the index","_TCP_ROUTING, with FORMAT naming an index name","queue, with FORMAT naming the index to write to"],a:[0],e:"<p>The <b>_MetaData:Index</b> key holds the index where an event will be stored, so a transform that sets <code>DEST_KEY = _MetaData:Index</code> with <code>FORMAT</code> set to the index name performs per-event index assignment. Splunk lists this alongside per-event queue filtering and routing as parsing phase work.</p><p><code>_TCP_ROUTING</code> is the tempting alternative because it also routes events, but it selects an output target group defined in <code>outputs.conf</code>, meaning which receiver gets the data. That is a network destination, not the index the event lands in.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/configuration-file-reference/10.4.2-configuration-file-reference/transforms.conf",hard:false},
 {exam:"cloudfund",cat:"c11rawdata",q:"How does an index-time change such as <code>SEDCMD</code> differ from a search-time change such as <code>FIELDALIAS</code>?",o:["Index-time changes apply only to accelerated reports","Index-time changes can be reversed by editing a macro","Index-time changes are evaluated once per user search","Index-time changes affect the data as it is stored"],a:[3],e:"<p>Splunk assigns <code>SEDCMD</code> and <code>TRANSFORMS</code> to the <b>parsing phase</b>, where they alter events before those events are written to disk. Search-time settings such as <code>FIELDALIAS</code>, <code>EXTRACT</code>, and <code>KV_MODE</code> run against already-stored data every time a search executes, leaving the stored events untouched.</p><p>Saying an index-time change is evaluated once per search reverses the two phases. That describes search-time behavior; an index-time change is applied once during ingestion, and correcting it means re-ingesting the data rather than editing a search-time object.</p>",d:"https://help.splunk.com/en/splunk-enterprise/administer/admin-manual/10.4/administer-splunk-enterprise-with-configuration-files/configuration-parameters-and-the-data-pipeline",hard:false},
 /* --- Apps --- */
 {exam:"cloudfund",cat:"c12apps",q:"An admin uploads a private app package to Splunk Cloud Platform. What happens automatically at that point?",o:["Splunk Support opens a Cloud App Request case for review","The app installs on search heads and indexers right away","Splunk runs the app through AppInspect validation","The app is published to Splunkbase as a restricted app"],a:[2],e:"<p>When you upload an app, Splunk Cloud Platform automatically runs it through <b>Splunk AppInspect</b> validation to confirm it meets Splunk Cloud requirements. The package must reach a status of Approved before the Install button becomes available, and the report must show zero Failures, Errors, and Manual Checks.</p><p>Immediate installation is the tempting answer because self-service feels instant. Installation is a separate step you take only after vetting succeeds; if the report shows any Manual Checks, you must contact Splunk Support to get the app installed.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/manage-private-apps-on-your-splunk-cloud-platform-deployment",hard:false},
 {exam:"cloudfund",cat:"c12apps",q:"What is a private app on Splunk Cloud Platform?",o:["A custom app you build that is not on Splunkbase","A Splunkbase app whose developer restricted downloads","A premium app such as Enterprise Security or ITSI","A Splunk-authored app that ships with every stack"],a:[0],e:"<p>A <b>private app</b> is a custom app you create for your own Splunk Cloud deployment and that is not publicly available on Splunkbase. Splunk Cloud supports self-service installation of private apps through the app management page in Splunk Web or through the ACS API.</p><p>The restricted-Splunkbase-app option names a genuinely different concept. A <b>restricted app</b> is published on Splunkbase but the developer limits who may download it, so installing one requires the authorized user's splunk.com credentials rather than a private app upload.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/manage-private-apps-on-your-splunk-cloud-platform-deployment",hard:false},
 {exam:"cloudfund",cat:"c12apps",q:"Installing which kind of app on Splunk Cloud Platform requires a request to Splunk Support rather than self-service?",o:["Any app that creates a new index on the deployment","Any add-on that contains props.conf and transforms.conf","Any app from Splunkbase rather than built in house","A premium solution such as Enterprise Security or ITSI"],a:[3],e:"<p><b>Premium solutions</b> such as Enterprise Security and IT Service Intelligence must be installed by Splunk Support, not through self-service. Support is also required when an app is not available for self-service, is not on Splunkbase, or must be installed on the IDM.</p><p>The Splunkbase option is the tempting one but has it backwards: more than 98% of Splunkbase apps are available for <b>self-service installation</b> straight from the in-product app browser in Splunk Web, which is exactly why the premium exception is worth memorizing.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/manage-apps-and-add-ons-in-splunk-cloud-platform/install-apps-on-your-splunk-cloud-platform-deployment",hard:false},
 /* --- Cloud Support --- */
 {exam:"cloudfund",cat:"c13support",q:"Before opening a support case about skipped scheduled searches, which built-in app should a Splunk Cloud admin check first?",o:["The Monitoring Console, carried over from Splunk Enterprise","The Cloud Monitoring Console, included with the stack","The Splunk deployment server forwarder management page","The Search and Reporting app's Job Inspector view only"],a:[1],e:"<p>The <b>Cloud Monitoring Console (CMC)</b> ships with every Splunk Cloud Platform environment and is the self-triage tool for deployment health, license usage, indexing performance, and search behavior. It has a dedicated Skipped scheduled searches dashboard and flags a skipped rate above 25% under Attention required.</p><p>The plain Monitoring Console is the near-miss: that is the Splunk Enterprise tool, and on Splunk Cloud the CMC replaces it. Reaching for CMC first often resolves the issue outright and gives Support concrete evidence when a case really is needed.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/administer/admin-manual/10.5.2605/monitor-your-splunk-cloud-platform-deployment/use-the-overview-dashboard",hard:false},
 {exam:"cloudfund",cat:"c13support",q:"Which of these tasks is Splunk's responsibility rather than the Splunk Cloud admin's?",o:["Upgrading the Splunk Cloud Platform software itself","Installing and upgrading the forwarders that send data","Creating indexes and setting their retention periods","Assigning roles and managing user account passwords"],a:[0],e:"<p>Splunk provides the current compatible version of Splunk Cloud Platform as a <b>Splunk-initiated Service Update</b> during scheduled maintenance windows. Customers do not upgrade the stack software, and they have no infrastructure access with which to do so.</p><p>Forwarder upkeep is the tempting choice because forwarders talk to the Splunk-managed stack, but they are the customer's own machines. Installing, configuring, and managing forwarders, including keeping their versions compatible, is explicitly the customer's responsibility, as are indexes, roles, users, and apps via the <b>sc_admin</b> role.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:false},
 {exam:"cloudfund",cat:"c13support",q:"Splunk notifies customers about upcoming maintenance windows and performance-impacting events. Which list must the admin keep accurate so those notices reach the right people?",o:["The sc_admin users defined in Splunk Web Settings","The email recipients saved on each scheduled alert","The role-to-email mapping stored in the CMC app","The Operational Contacts in the support portal"],a:[3],e:"<p><b>Operational Contacts</b> are maintained in your splunk.com support portal, not inside the Splunk Cloud stack. They receive notice of planned and unplanned downtime, scheduled maintenance window alerts, and email updates on incident-triggered cases, and keeping them current is listed as a customer maintenance responsibility.</p><p>Assuming the sc_admin user list drives these notices is the natural but wrong inference. Accounts inside Splunk Web control what someone can do on the stack; they have no bearing on who Splunk contacts about service events.</p>",d:"https://help.splunk.com/en/splunk-cloud-platform/get-started/service-terms-and-policies/10.5.2605/information-about-the-service/splunk-cloud-platform-service-details",hard:false},
];

function CLOUD_COURSE(){
 return [
  {key:'c1',cat:['c1over'],title:'Splunk Cloud Overview & Topology',modules:'Modules 1 & 14',blurb:'How Splunk Cloud is architected and who manages what.',doc:CL_GDI,
   summary:`<ul><li><b>Shared responsibility:</b> Splunk manages the indexers, search heads, and <b>platform upgrades</b>; you manage forwarders, inputs, and (if used) your own deployment server.</li>
   <li><b>No OS / CLI / filesystem access</b> — you administer via <b>Splunk Web</b>, the <b>Admin Config Service (ACS)</b>, or a <b>Support case</b>.</li>
   <li><b>Victoria vs Classic:</b> find yours under <b>Support &amp; Services &gt; About</b>; Splunk assigns it. Victoria runs inputs on the search head (no IDM); Classic requires an IDM.</li>
   <li><b>Four ways to get data in:</b> forwarders, HEC, apps/add-ons, and the IDM.</li>
   <li><b>Module 14 (Managing Cloud):</b> Federated Search, Private Connectivity (AWS), and self-service admin via ACS.</li></ul>`},
  {key:'c2',cat:['c5gdi','c7monitor','c8network'],title:'Getting Data Into Cloud',modules:'Modules 6, 8, 9, 10, 11',blurb:'Forwarders, HEC, IDM, and monitor inputs the Cloud way.',doc:CL_FWD,
   summary:`<ul><li><b>Connect a UF:</b> download the <code>splunkclouduf.spl</code> credentials package (Splunk Web &gt; Apps &gt; Universal Forwarder), install it, and restart. It carries outputs.conf + TLS certs; can enable <b>indexer acknowledgment</b> (re-sends on no-ack).</li>
   <li><b>UF vs HF:</b> a UF forwards unparsed data; <b>parsed/event data needs an HF or IDM</b>. Intermediate forwarders aggregate at ~<b>2:1</b> to Cloud indexers.</li>
   <li><b>IDM:</b> required on <b>Classic</b> for scripted/modular inputs; on <b>Victoria</b> those run on the search head.</li>
   <li><b>HEC on Cloud:</b> port <b>443</b>, with the <code>http-inputs-</code> hostname prefix.</li>
   <li><b>Monitor inputs:</b> only <code>[monitor://path]</code> is required; a raw-event <b>time-zone offset wins</b> over props.conf <code>TZ</code>.</li></ul>`},
  {key:'c3',cat:['c2index'],title:'Index Management in Cloud',modules:'Module 3',blurb:'Creating indexes, retention, and the DDAS/DDAA/DDSS tiers.',doc:CL_MANIDX,
   summary:`<ul><li><b>Create indexes</b> in Splunk Web (Settings &gt; Indexes) or via <b>ACS</b> — never by editing <code>indexes.conf</code>.</li>
   <li><b>Retention</b> = Max raw data size + Searchable retention (days); data removed by whole buckets, oldest first. Max active indexes: <b>400 (Classic) / 1000 (Victoria)</b>.</li>
   <li><b>Data tiers:</b> DDAS (searchable) → then <b>DDAA</b> (Splunk-managed archive, 500&nbsp;GB blocks, restorable ~24h) or <b>DDSS</b> (your own AWS/GCP storage, restore to your own Splunk to search). Only one per index.</li>
   <li><b>Delete:</b> deleting an index is final; the <code>delete</code> command only hides events (doesn't free disk). Monitor with the <b>CMC</b>.</li></ul>`},
  {key:'c4',cat:['c4conf','c3auth'],title:'Config & Admin Access (ACS)',modules:'Modules 2, 4, 13',blurb:'ACS, config without CLI, users/auth, and Ingest Actions.',doc:CL_ACS,
   summary:`<ul><li><b>No .conf editing:</b> change config via <b>Splunk Web</b>, the <b>ACS API/CLI</b>, or <b>Support</b>. ACS needs the <code>sc_admin</code> role + a bearer token and isn't supported on single-instance stacks.</li>
   <li><b>ACS self-service:</b> indexes, HEC tokens, IP allow lists, a <b>limits.conf subset</b> (Victoria), users/roles, apps, maintenance windows.</li>
   <li><b>Users &amp; auth:</b> roles → capabilities; the Cloud super-role is <code>sc_admin</code>; SAML is the common SSO.</li>
   <li><b>Ingest Actions (Module 13):</b> build rulesets in <b>Splunk Web</b> to <b>mask/truncate/filter/route</b> data — the Cloud-native replacement for hand-edited <code>SEDCMD</code>/transforms.</li></ul>`},
  {key:'c5',cat:['c12apps'],title:'Apps & Private Apps',modules:'Module 5',blurb:'Self-service install, AppInspect vetting, and premium apps.',doc:CL_INSTALL,
   summary:`<ul><li><b>Self-service install</b> (needs <code>sc_admin</code>) for most Splunkbase apps — must pass <b>AppInspect with 0 Failures / 0 Errors / 0 Manual Checks</b>.</li>
   <li><b>Premium apps (ES/ITSI)</b>, IDM installs, and &gt;0 manual checks require <b>Support</b>.</li>
   <li><b>Private apps:</b> <code>.spl/.tgz</code> ≤128&nbsp;MB, dynamic dependencies only; Cloud auto-runs AppInspect on upload.</li>
   <li><b>Victoria</b> auto-deploys apps to all search heads; a <b>restart is only needed</b> when the app has <b>static assets or props/transforms</b>. No self-service rollback.</li></ul>`},
  {key:'c6',cat:['c13support'],title:'Working with Cloud Support',modules:'Module 15',blurb:'Isolate first, then open a case the right way.',doc:CL_SUPPORT,
   summary:`<ul><li><b>Self-triage first:</b> use the <b>CMC</b> dashboards and search <code>index=_internal</code> / <code>index=_audit</code> to isolate the problem.</li>
   <li><b>Open cases</b> through the Splunk Support Portal; anyone with the <b>appropriate entitlement</b> can submit.</li>
   <li><b>Severity:</b> P1 (inaccessible) is 24×7; <b>Standard covers P1, Premium adds P2</b>.</li>
   <li><b>Needs Support:</b> premium-app installs/updates, IDM index sync (Classic), and config outside the ACS-editable subset.</li></ul>`},
  {key:'c7',cat:['c6fwdmgmt'],title:'Forwarder Management',modules:'Module 7',blurb:'Central management of forwarders in the Cloud model.',doc:CL_FWD,
   summary:`<ul><li><b>Splunk Cloud does NOT provide a deployment server</b> — the customer hosts one (on-prem or their own cloud) to manage forwarders.</li>
   <li>Push <code>splunkclouduf.spl</code> + inputs as <b>deployment-apps</b> from that deployment server to your forwarder clients.</li>
   <li>A <b>UF has no Splunk Web/UI</b> — configure it via <b>CLI, config files, or a deployment app</b> (not the web menu).</li></ul>`},
 ];
}
